def _prepend_local_vendor_sitepackages() -> str | None:
    """Add repo-local vendored site-packages ahead of sys.path when present."""
    vendor_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".vendor_site")
    if not os.path.isdir(vendor_dir):
        return None
    vendor_norm = os.path.normcase(os.path.normpath(vendor_dir))
    for existing in sys.path:
        try:
            if os.path.normcase(os.path.normpath(str(existing))) == vendor_norm:
                return vendor_dir
        except Exception:
            continue
    sys.path.insert(0, vendor_dir)
    return vendor_dir


class FileDropFrame(QFrame):
    """Small reusable widget: drag-drop (or browse) one file path."""

    file_dropped = Signal(str)

    def __init__(self, title: str, placeholder: str, parent: QWidget | None = None):
        """Build a labeled frame with path display and browse button."""
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setFrameShape(QFrame.StyledPanel)
        self.setFrameShadow(QFrame.Raised)

        layout = QVBoxLayout(self)
        title_label = QLabel(title)
        title_label.setStyleSheet("font-weight: 600;")

        self.path_edit = QLineEdit()
        self.path_edit.setReadOnly(True)
        self.path_edit.setPlaceholderText(placeholder)

        browse_btn = QPushButton("Browse")
        browse_btn.clicked.connect(self._browse_file)

        layout.addWidget(title_label)
        layout.addWidget(self.path_edit)
        layout.addWidget(browse_btn)

    def set_path(self, file_path: str) -> None:
        """Display the chosen file path."""
        self.path_edit.setText(file_path)

    def clear_path(self) -> None:
        """Clear displayed path."""
        self.path_edit.clear()

    def dragEnterEvent(self, event):  # noqa: N802
        """Accept drag if MIME data contains local URLs."""
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
            return
        event.ignore()

    def dropEvent(self, event):  # noqa: N802
        """Emit the first local file dropped onto this frame."""
        urls = event.mimeData().urls()
        for url in urls:
            if url.isLocalFile():
                self.file_dropped.emit(url.toLocalFile())
                event.acceptProposedAction()
                return
        event.ignore()

    def _browse_file(self) -> None:
        """Open file dialog and emit selected path."""
        file_path, _ = QFileDialog.getOpenFileName(
            self, "Choose data file", "", "Data files (*.dat);;All files (*.*)"
        )
        if file_path:
            self.file_dropped.emit(file_path)


