        def make_grid_section(title: str) -> tuple[QGroupBox, QGridLayout]:
            group = QGroupBox(title)
            layout = QGridLayout(group)
            layout.setContentsMargins(8, 8, 8, 8)
            layout.setHorizontalSpacing(3)
            layout.setVerticalSpacing(4)
            layout.setColumnStretch(0, 0)
            layout.setColumnStretch(1, 0)
            layout.setColumnStretch(2, 0)
            layout.setColumnStretch(3, 0)
            layout.setColumnStretch(4, 1)
            layout.setAlignment(Qt.AlignTop | Qt.AlignLeft)
            return group, layout

        def compact_grid_pairs(layout: QGridLayout, label_cols: tuple[int, ...] = (0, 2, 4, 6)) -> None:
            """Keep labels visually attached to their paired controls inside grid sections."""
            for idx in range(layout.count()):
                item = layout.itemAt(idx)
                widget = item.widget() if item is not None else None
                if widget is None:
                    continue
                row, col, row_span, col_span = layout.getItemPosition(idx)
                _ = row
                if col_span != 1 or row_span != 1:
                    continue
                if isinstance(widget, QLabel) and col in label_cols:
                    layout.setAlignment(widget, Qt.AlignRight | Qt.AlignVCenter)
                elif col in tuple(c + 1 for c in label_cols):
                    layout.setAlignment(widget, Qt.AlignLeft | Qt.AlignVCenter)

        def make_vbox_section(title: str) -> tuple[QGroupBox, QVBoxLayout]:
            group = QGroupBox(title)
            layout = QVBoxLayout(group)
            layout.setContentsMargins(8, 8, 8, 8)
            layout.setSpacing(8)
            return group, layout

