    def _create_span_selector(self):
        """Create the ion-TOF fine ROI selector on the histogram axis."""
        try:
            selector = SpanSelector(
                self.ax_hist_ion,
                self._on_ion_span_selected,
                "horizontal",
                useblit=True,
                props={"alpha": 0.22, "facecolor": "#00b4d8"},
                interactive=True,
                drag_from_anywhere=True,
            )
        except TypeError:
            selector = SpanSelector(
                self.ax_hist_ion,
                self._on_ion_span_selected,
                "horizontal",
                useblit=True,
                rectprops={"alpha": 0.22, "facecolor": "#00b4d8"},
            )
        self._update_ion_hist_span_selector_state()
        return selector

    def _create_ion_tof_fit_selector(self):
        """Create one lightweight selector proxy for the custom multi-box ROI picker."""
        selector = _SelectorToggleProxy()
        selector.set_active(False)
        self._update_ion_tof_fit_selector_state()
        return selector

    def _create_ion_tof_bg_selector(self):
        """Create one lightweight selector proxy for the custom TOF-background range picker."""
        selector = _SelectorToggleProxy()
        selector.set_active(False)
        self._update_ion_tof_bg_selector_state()
        return selector

    def _canvas_display_scale_factors(self) -> tuple[float, float]:
        """Return `(display_px/logical_px)` scale factors between matplotlib and the Qt canvas."""
        canvas = getattr(self, "canvas", None)
        fig = getattr(self, "figure", None)
        if canvas is None or fig is None:
            return 1.0, 1.0
        width = max(int(canvas.width()), 1)
        height = max(int(canvas.height()), 1)
        sx = 1.0
        sy = 1.0
        bbox = getattr(fig, "bbox", None)
        with contextlib.suppress(Exception):
            if bbox is not None:
                bbox_w = float(bbox.width)
                bbox_h = float(bbox.height)
                if np.isfinite([bbox_w, bbox_h]).all() and bbox_w > 1e-9 and bbox_h > 1e-9:
                    sx = float(bbox_w) / float(width)
                    sy = float(bbox_h) / float(height)
        if (not np.isfinite([sx, sy]).all()) or sx <= 0.0 or sy <= 0.0:
            return 1.0, 1.0
        return float(sx), float(sy)

    def _mpl_display_to_canvas_point(self, x_display: float | None, y_display: float | None) -> QPoint | None:
        """Convert matplotlib display coordinates (origin bottom-left) to Qt canvas coords."""
        canvas = getattr(self, "canvas", None)
        if canvas is None or x_display is None or y_display is None:
            return None
        vals = np.asarray([x_display, y_display], dtype=np.float64).reshape(-1)
        if vals.size != 2 or (not np.isfinite(vals).all()):
            return None
        sx, sy = self._canvas_display_scale_factors()
        x_logical = float(vals[0]) / float(sx)
        y_logical = float(canvas.height()) - (float(vals[1]) / float(sy))
        if not np.isfinite([x_logical, y_logical]).all():
            return None
        return QPoint(int(round(x_logical)), int(round(y_logical)))

    def _ion_tof_fit_drag_preview_widget(self) -> QFrame | None:
        """Legacy helper kept for state cleanup; coincidence drag preview no longer uses a child widget."""
        return getattr(self, "ion_tof_fit_drag_preview_frame", None)

    def _hide_ion_tof_fit_drag_preview(self) -> None:
        """Hide the fast Qt coincidence-box drag preview rectangle."""
        frame = getattr(self, "ion_tof_fit_drag_preview_frame", None)
        if frame is not None:
            with contextlib.suppress(Exception):
                frame.hide()

    def _update_ion_tof_fit_drag_preview(self, anchor_pos: QPoint | None, current_pos: QPoint | None) -> None:
        """Refresh coincidence-box drag preview using matplotlib artists only."""
        if anchor_pos is None or current_pos is None:
            self._hide_ion_tof_fit_drag_preview()
            return
        self._hide_ion_tof_fit_drag_preview()
        self._update_ion_tof_fit_preview_artists(draw_canvas=True)

    def _toolbar_mode_active(self) -> bool:
        """Return whether matplotlib toolbar currently owns mouse interactions (pan/zoom)."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return False
        mode = str(getattr(tb, "mode", "") or "").strip()
        if mode != "":
            return True
        actions = getattr(tb, "_actions", {})
        if isinstance(actions, dict):
            for key in ("pan", "zoom"):
                action = actions.get(key)
                if action is None:
                    continue
                with contextlib.suppress(Exception):
                    if action.isChecked():
                        return True
        return False

    def _toolbar_pan_zoom_action_states(self) -> tuple[bool, bool]:
        """Return `(pan_checked, zoom_checked)` for the matplotlib toolbar buttons."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return False, False
        actions = getattr(tb, "_actions", {})
        if not isinstance(actions, dict):
            return False, False

        def _checked(name: str) -> bool:
            action = actions.get(name)
            if action is None:
                return False
            with contextlib.suppress(Exception):
                return bool(action.isChecked())
            return False

        return _checked("pan"), _checked("zoom")

    def _toolbar_has_active_drag(self) -> bool:
        """Return whether matplotlib still tracks an in-progress pan/zoom drag gesture."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return False
        return bool(getattr(tb, "_pan_info", None) is not None or getattr(tb, "_zoom_info", None) is not None)

    def _cancel_toolbar_active_drag(self) -> bool:
        """Cancel any half-finished matplotlib pan/zoom drag so the toolbar can recover cleanly."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return False
        changed = False

        pan_info = getattr(tb, "_pan_info", None)
        if pan_info is not None:
            with contextlib.suppress(Exception):
                tb.release_pan(None)
                changed = True
            if getattr(tb, "_pan_info", None) is not None:
                with contextlib.suppress(Exception):
                    tb.canvas.mpl_disconnect(pan_info.cid)
                with contextlib.suppress(Exception):
                    tb._pan_info = None
                changed = True

        zoom_info = getattr(tb, "_zoom_info", None)
        if zoom_info is not None:
            class _ZoomCancelEvent:
                def __init__(self, x_val: float, y_val: float):
                    self.x = float(x_val)
                    self.y = float(y_val)
                    self.key = None

            with contextlib.suppress(Exception):
                tb.release_zoom(_ZoomCancelEvent(zoom_info.start_xy[0], zoom_info.start_xy[1]))
                changed = True
            if getattr(tb, "_zoom_info", None) is not None:
                with contextlib.suppress(Exception):
                    tb.canvas.mpl_disconnect(zoom_info.cid)
                with contextlib.suppress(Exception):
                    tb.remove_rubberband()
                with contextlib.suppress(Exception):
                    tb._zoom_info = None
                with contextlib.suppress(Exception):
                    tb.canvas.draw_idle()
                changed = True

        return changed

    def _sync_toolbar_canvas_cursor(self) -> None:
        """Refresh the matplotlib canvas cursor so it matches the current pan/zoom state."""
        tb = getattr(self, "toolbar", None)
        canvas = getattr(self, "canvas", None)
        fig = getattr(self, "figure", None)
        if tb is None or canvas is None or fig is None:
            return
        update_cursor = getattr(tb, "_update_cursor", None)
        if not callable(update_cursor):
            if not self._toolbar_mode_active():
                with contextlib.suppress(Exception):
                    canvas.unsetCursor()
            return

        inaxes = None
        with contextlib.suppress(Exception):
            local_pos = canvas.mapFromGlobal(QCursor.pos())
            if canvas.rect().contains(local_pos):
                x_disp = float(local_pos.x())
                y_disp = float(canvas.height() - local_pos.y())
                for ax in reversed(list(getattr(fig, "axes", []))):
                    bbox = getattr(ax, "bbox", None)
                    if ax is None or bbox is None:
                        continue
                    with contextlib.suppress(Exception):
                        if bool(bbox.contains(x_disp, y_disp)):
                            inaxes = ax
                            break

        class _CursorEvent:
            def __init__(self, inaxes_now):
                self.inaxes = inaxes_now

        with contextlib.suppress(Exception):
            update_cursor(_CursorEvent(inaxes))

    def _force_toolbar_idle(self) -> bool:
        """Force matplotlib toolbar pan/zoom state back to idle when it becomes internally inconsistent."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return False
        changed = self._cancel_toolbar_active_drag()
        pan_checked, zoom_checked = self._toolbar_pan_zoom_action_states()
        if pan_checked or zoom_checked:
            actions = getattr(tb, "_actions", {})
            if isinstance(actions, dict):
                for key in ("pan", "zoom"):
                    action = actions.get(key)
                    if action is None:
                        continue
                    with contextlib.suppress(Exception):
                        if action.isChecked():
                            was = action.blockSignals(True)
                            action.setChecked(False)
                            action.blockSignals(was)
                            changed = True
        mode_text = str(getattr(tb, "mode", "") or "").strip()
        active_tool = getattr(tb, "_active", None)
        if mode_text != "" or active_tool not in (None, ""):
            with contextlib.suppress(Exception):
                tb.mode = ""
                changed = True
            with contextlib.suppress(Exception):
                setattr(tb, "_active", None)
                changed = True
        with contextlib.suppress(Exception):
            tb.canvas.widgetlock.release(tb)
        if hasattr(tb, "_update_buttons_checked"):
            with contextlib.suppress(Exception):
                tb._update_buttons_checked()
        for ax in list(getattr(tb.canvas.figure, "axes", [])):
            with contextlib.suppress(Exception):
                ax.set_navigate_mode(None)
        with contextlib.suppress(Exception):
            tb.set_message("")
        self._update_ion_hist_span_selector_state()
        self._update_ion_tof_bg_selector_state()
        self._update_ion_tof_fit_selector_state()
        self._sync_toolbar_canvas_cursor()
        return changed

    def _sync_toolbar_interaction_state(self) -> None:
        """Keep matplotlib toolbar internals, selector availability, and cursor state consistent."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            self._update_ion_hist_span_selector_state()
            self._update_ion_tof_bg_selector_state()
            self._update_ion_tof_fit_selector_state()
            return
        pan_checked, zoom_checked = self._toolbar_pan_zoom_action_states()
        mode_text = str(getattr(tb, "mode", "") or "").strip()
        active_tool = getattr(tb, "_active", None)
        inconsistent_idle = (not pan_checked and not zoom_checked) and (
            mode_text != "" or active_tool not in (None, "") or self._toolbar_has_active_drag()
        )
        if inconsistent_idle:
            self._force_toolbar_idle()
            return
        self._update_ion_hist_span_selector_state()
        self._update_ion_tof_bg_selector_state()
        self._update_ion_tof_fit_selector_state()
        self._sync_toolbar_canvas_cursor()

    def _update_ion_hist_span_selector_state(self) -> None:
        """Keep Fine ROI span-selector disabled while other interaction modes are active."""
        selector = getattr(self, "ion_selector", None)
        if selector is None:
            return
        enabled = not (
            bool(getattr(self, "_ion_hist_modifier_guard_active", False))
            or bool(getattr(self, "_ion_hist_span_pause_until_release", False))
            or self._toolbar_mode_active()
        )
        if enabled == getattr(self, "_ion_hist_span_selector_active_state", None):
            return
        with contextlib.suppress(Exception):
            selector.set_active(enabled)
        self._ion_hist_span_selector_active_state = bool(enabled)
        if not enabled:
            self.pending_ion_span_range = None
            self.ion_span_apply_timer.stop()
            with contextlib.suppress(Exception):
                selector.clear()
            with contextlib.suppress(Exception):
                self.canvas.unsetCursor()

    def _update_ion_tof_bg_selector_state(self) -> None:
        """Enable the TOF-background range picker only when its toggle is on and the toolbar is idle."""
        selector = getattr(self, "ion_tof_bg_selector", None)
        button = getattr(self, "ion_tof_bg_pick_btn", None)
        fit_button = getattr(self, "ion_tof_fit_pick_btn", None)
        if selector is None or button is None:
            return
        enabled = (
            bool(button.isChecked())
            and self._has_pairs()
            and (not self._toolbar_mode_active())
            and (not bool(fit_button is not None and fit_button.isChecked()))
        )
        if enabled == getattr(self, "_ion_tof_bg_selector_active_state", None):
            return
        with contextlib.suppress(Exception):
            selector.set_active(enabled)
        self._ion_tof_bg_selector_active_state = bool(enabled)
        if enabled:
            with contextlib.suppress(Exception):
                self.canvas.setCursor(Qt.CrossCursor)
        else:
            self._ion_tof_bg_pending_tof = None
            self._ion_tof_bg_hover_tof = None
            with contextlib.suppress(Exception):
                selector.clear()
            self._update_ion_tof_bg_preview_artists(draw_canvas=False)
            if not bool(getattr(self, "ion_tof_fit_pick_btn", None) and self.ion_tof_fit_pick_btn.isChecked()):
                with contextlib.suppress(Exception):
                    self.canvas.unsetCursor()

    def _update_ion_tof_fit_selector_state(self) -> None:
        """Enable the coincidence-map ROI selector only when its toggle is on and the toolbar is idle."""
        selector = getattr(self, "ion_tof_fit_selector", None)
        button = getattr(self, "ion_tof_fit_pick_btn", None)
        bg_button = getattr(self, "ion_tof_bg_pick_btn", None)
        if selector is None or button is None:
            return
        enabled = (
            bool(button.isChecked())
            and self._has_pairs()
            and (not self._toolbar_mode_active())
            and (not bool(bg_button is not None and bg_button.isChecked()))
        )
        if enabled == getattr(self, "_ion_tof_fit_selector_active_state", None):
            return
        with contextlib.suppress(Exception):
            selector.set_active(enabled)
        self._ion_tof_fit_selector_active_state = bool(enabled)
        if enabled:
            with contextlib.suppress(Exception):
                self.canvas.setCursor(Qt.CrossCursor)
        else:
            self._ion_tof_fit_pending_axis = None
            self._ion_tof_fit_pending_points = []
            self._ion_tof_fit_hover_point = None
            self._ion_tof_fit_press_armed = False
            self._ion_tof_fit_drag_active = False
            self._ion_tof_fit_drag_anchor_canvas_pos = None
            self._hide_ion_tof_fit_drag_preview()
            with contextlib.suppress(Exception):
                selector.clear()
            self._update_ion_tof_fit_preview_artists(draw_canvas=False)
            if not bool(getattr(self, "ion_tof_bg_pick_btn", None) and self.ion_tof_bg_pick_btn.isChecked()):
                with contextlib.suppress(Exception):
                    self.canvas.unsetCursor()

    def _schedule_toolbar_interaction_sync(self) -> None:
        """Defer selector/tool-state sync until after toolbar action handlers run."""
        QTimer.singleShot(0, self._sync_toolbar_interaction_state)
        QTimer.singleShot(40, self._sync_toolbar_interaction_state)

    def _cancel_active_canvas_interaction(self, *, announce: bool = True) -> bool:
        """Cancel any active plot interaction so a right-click can always recover the canvas."""
        cancelled = False

        if self._toolbar_mode_active() or self._toolbar_has_active_drag():
            self._force_toolbar_idle()
            cancelled = True

        ion_tof_pick_btn = getattr(self, "ion_tof_fit_pick_btn", None)
        ion_tof_pick_active = bool(
            isinstance(ion_tof_pick_btn, QPushButton) and ion_tof_pick_btn.isCheckable() and ion_tof_pick_btn.isChecked()
        )
        ion_tof_preview_active = bool(
            getattr(self, "_ion_tof_fit_pending_axis", None) is not None
            or len(getattr(self, "_ion_tof_fit_pending_points", [])) > 0
            or getattr(self, "_ion_tof_fit_hover_point", None) is not None
        )
        if ion_tof_pick_active or ion_tof_preview_active:
            if ion_tof_pick_active:
                was = ion_tof_pick_btn.blockSignals(True)
                ion_tof_pick_btn.setChecked(False)
                ion_tof_pick_btn.blockSignals(was)
            self._ion_tof_fit_pending_axis = None
            self._ion_tof_fit_pending_points = []
            self._ion_tof_fit_hover_point = None
            self._ion_tof_fit_press_armed = False
            self._ion_tof_fit_drag_active = False
            self._ion_tof_fit_drag_anchor_canvas_pos = None
            self._hide_ion_tof_fit_drag_preview()
            self._update_ion_tof_fit_selector_state()
            self._update_ion_tof_fit_preview_artists(draw_canvas=True)
            cancelled = True

        ion_tof_bg_pick_btn = getattr(self, "ion_tof_bg_pick_btn", None)
        ion_tof_bg_pick_active = bool(
            isinstance(ion_tof_bg_pick_btn, QPushButton) and ion_tof_bg_pick_btn.isCheckable() and ion_tof_bg_pick_btn.isChecked()
        )
        ion_tof_bg_preview_active = bool(
            getattr(self, "_ion_tof_bg_pending_tof", None) is not None
            or getattr(self, "_ion_tof_bg_hover_tof", None) is not None
        )
        if ion_tof_bg_pick_active or ion_tof_bg_preview_active:
            if ion_tof_bg_pick_active:
                was = ion_tof_bg_pick_btn.blockSignals(True)
                ion_tof_bg_pick_btn.setChecked(False)
                ion_tof_bg_pick_btn.blockSignals(was)
            self._ion_tof_bg_pending_tof = None
            self._ion_tof_bg_hover_tof = None
            self._update_ion_tof_bg_selector_state()
            self._update_ion_tof_bg_preview_artists(draw_canvas=True)
            cancelled = True

        rbasex_pick_active = bool(
            self._rbasex_profile_range_pick_enabled()
            or self.dragging_rbasex_profile_range
            or self.pending_rbasex_profile_xrange is not None
        )
        if rbasex_pick_active:
            self._set_rbasex_profile_range_pick_enabled(False, announce=False)
            cancelled = True

        theta_source = self.dragging_theta_source if self.dragging_theta_source is not None else self.pending_theta_drag_source
        theta_preview_active = bool(
            theta_source is not None or self.pending_theta_drag_xy is not None or self.pending_theta_drag_deg is not None
        )
        if theta_preview_active:
            if hasattr(self, "theta_drag_preview_timer") and self.theta_drag_preview_timer.isActive():
                self.theta_drag_preview_timer.stop()
            self.dragging_theta_source = None
            self.pending_theta_drag_source = None
            self.pending_theta_drag_xy = None
            self.pending_theta_drag_deg = None
            # 16i: a cancelled theta drag never reaches the release commit, so
            # clear its draw-event suspension here as well.
            self._suspend_overlay_draw_event_sync = False
            if theta_source == "centered" and self.centered_hist_data is not None:
                self._refresh_theta_profile_panels(announce=False, fast_drag=False)
            elif theta_source == "rbasex" and self.rbasex_recon_result is not None:
                self._refresh_rbasex_profile_panels(announce=False, fast_drag=False)
            else:
                with contextlib.suppress(Exception):
                    self.canvas.draw_idle()
            cancelled = True

        polar_base_band = self.polar_roi_drag_base_band
        polar_drag_active = bool(
            self.dragging_polar_roi
            or self.pending_polar_roi_band is not None
            or getattr(self, "polar_roi_drag_mode", None) is not None
        )
        if polar_drag_active:
            if hasattr(self, "polar_roi_preview_timer") and self.polar_roi_preview_timer.isActive():
                self.polar_roi_preview_timer.stop()
            self.dragging_polar_roi = False
            self.pending_polar_roi_band = None
            self.polar_roi_drag_mode = None
            self.polar_roi_drag_anchor_r = None
            self.polar_roi_drag_base_band = None
            if polar_base_band is None:
                self._set_polar_roi_inputs(None, None)
            else:
                self._set_polar_roi_inputs(float(polar_base_band[0]), float(polar_base_band[1]))
            self._update_circle_overlay_only(enforce_axis=False, fast_drag=False)
            cancelled = True

        circle_drag_active = bool(
            self.dragging_circle or self.pending_drag_center is not None or self.preview_circle_center is not None
        )
        if circle_drag_active:
            if hasattr(self, "drag_preview_timer") and self.drag_preview_timer.isActive():
                self.drag_preview_timer.stop()
            self.dragging_circle = False
            self.pending_drag_center = None
            self.preview_circle_center = None
            self._update_circle_overlay_only(enforce_axis=False, fast_drag=False)
            cancelled = True

        ion_drag_active = bool(
            self.dragging_ion_filter or self.pending_drag_ion_center is not None or self.preview_ion_center is not None
        )
        if ion_drag_active:
            if hasattr(self, "ion_drag_preview_timer") and self.ion_drag_preview_timer.isActive():
                self.ion_drag_preview_timer.stop()
            self.dragging_ion_filter = False
            self.pending_drag_ion_center = None
            self.preview_ion_center = None
            self._update_ion_overlay_only(enforce_axis=False, fast_drag=False)
            cancelled = True

        ion_rotation_active = bool(self.dragging_ion_rotation or self.pending_ion_rotation_deg is not None)
        if ion_rotation_active:
            self.dragging_ion_rotation = False
            self.pending_ion_rotation_deg = None
            if hasattr(self, "ion_rot_offset_edit"):
                self._set_line_edit_numeric(self.ion_rot_offset_edit, float(self.ion_user_rotation_deg), ".6g")
            self._clear_ion_rotation_drag_preview_state(restore_preview=True)
            cancelled = True

        hist_span_active = bool(
            getattr(self, "_ion_hist_span_pause_until_release", False)
            or self.pending_ion_span_range is not None
            or (hasattr(self, "ion_span_apply_timer") and self.ion_span_apply_timer.isActive())
        )
        if hist_span_active:
            self._ion_hist_span_pause_until_release = False
            self.pending_ion_span_range = None
            if hasattr(self, "ion_span_apply_timer"):
                self.ion_span_apply_timer.stop()
            selector = getattr(self, "ion_selector", None)
            if selector is not None:
                with contextlib.suppress(Exception):
                    selector.clear()
            qt_modifiers = None
            with contextlib.suppress(Exception):
                qt_modifiers = QApplication.keyboardModifiers()
            self._sync_ion_hist_modifier_guard(qt_modifiers, default_inactive=(qt_modifiers is None))
            self._update_ion_hist_span_selector_state()
            cancelled = True

        if cancelled and announce:
            self._set_status("Right-click cancelled the active plot interaction.")
        return cancelled

    @staticmethod
    def _normalize_ion_tof_bg_range(
        tof_range: tuple[float, float] | list[float] | np.ndarray | None,
    ) -> tuple[float, float] | None:
        """Normalize one TOF background window into `(tof_min, tof_max)`."""
        if tof_range is None:
            return None
        vals = np.asarray(tof_range, dtype=np.float64).reshape(-1)
        if vals.size < 2 or (not np.isfinite(vals[:2]).all()):
            return None
        t0, t1 = sorted((float(vals[0]), float(vals[1])))
        if abs(t1 - t0) <= 1e-12:
            return None
        return float(t0), float(t1)

    @classmethod
    def _normalize_ion_tof_bg_ranges(
        cls,
        ranges: list[tuple[float, float]] | tuple[tuple[float, float], ...] | None,
    ) -> tuple[tuple[float, float], ...]:
        """Return all valid normalized TOF background windows."""
        if not isinstance(ranges, (list, tuple)):
            return ()
        out: list[tuple[float, float]] = []
        for tof_range in ranges:
            norm = cls._normalize_ion_tof_bg_range(tof_range)
            if norm is not None:
                out.append(norm)
        return tuple(out)

    def _current_ion_tof_bg_ranges(self) -> tuple[tuple[float, float], ...]:
        """Return the stored TOF background windows shared by X-TOF and Y-TOF views."""
        return self._normalize_ion_tof_bg_ranges(getattr(self, "ion_tof_bg_ranges", []))

    def _set_ion_tof_bg_ranges(
        self,
        ranges: list[tuple[float, float]] | tuple[tuple[float, float], ...],
    ) -> tuple[tuple[float, float], ...]:
        """Store normalized TOF background windows."""
        norm_ranges = self._normalize_ion_tof_bg_ranges(ranges)
        self.ion_tof_bg_ranges = [tuple(tof_range) for tof_range in norm_ranges]
        return norm_ranges

    def _clear_ion_tof_bg_pending_selection(self, *, update_preview: bool = False) -> None:
        """Clear the in-progress TOF background-range selection."""
        self._ion_tof_bg_pending_tof = None
        self._ion_tof_bg_hover_tof = None
        if update_preview:
            self._update_ion_tof_bg_preview_artists(draw_canvas=True)

    def _current_ion_tof_bg_preview_range(self) -> tuple[float, float] | None:
        """Return the currently previewed TOF background window from anchor + hover."""
        anchor = getattr(self, "_ion_tof_bg_pending_tof", None)
        hover = getattr(self, "_ion_tof_bg_hover_tof", None)
        if anchor is None or hover is None:
            return None
        return self._normalize_ion_tof_bg_range((anchor, hover))

    def _ion_tof_bg_range_index_at_tof(self, tof_value: float) -> int | None:
        """Return the topmost stored TOF background window containing `tof_value`."""
        if not np.isfinite(float(tof_value)):
            return None
        ranges = self._current_ion_tof_bg_ranges()
        if len(ranges) <= 0:
            return None
        for rev_idx, tof_range in enumerate(reversed(ranges)):
            t0, t1 = tof_range
            if t0 <= float(tof_value) <= t1:
                return len(ranges) - 1 - rev_idx
        return None

    def _update_ion_tof_bg_preview_artists(self, *, draw_canvas: bool) -> None:
        """Refresh the live TOF-background preview on the ion X/Y-TOF subplot."""
        ax = getattr(self, "ax_ion_tof_xy", None)
        if ax is None:
            return
        preview_gids = {"ion_tof_bg_preview_range", "ion_tof_bg_preview_anchor"}
        for patch in list(getattr(ax, "patches", [])):
            gid = getattr(patch, "get_gid", lambda: None)()
            if gid in preview_gids:
                with contextlib.suppress(Exception):
                    patch.remove()
        for line in list(getattr(ax, "lines", [])):
            gid = getattr(line, "get_gid", lambda: None)()
            if gid in preview_gids:
                with contextlib.suppress(Exception):
                    line.remove()
        anchor = getattr(self, "_ion_tof_bg_pending_tof", None)
        preview_range = self._current_ion_tof_bg_preview_range()
        if anchor is not None or preview_range is not None:
            xlim = ax.get_xlim()
            ylim = ax.get_ylim()
            y0, y1 = float(ylim[0]), float(ylim[1])
            if anchor is not None and np.isfinite(float(anchor)):
                preview_anchor = ax.plot(
                    [float(anchor), float(anchor)],
                    [y0, y1],
                    color="#ff9f1c",
                    linewidth=1.05,
                    linestyle=":",
                    alpha=0.95,
                    zorder=6.9,
                    scalex=False,
                    scaley=False,
                )[0]
                preview_anchor.set_gid("ion_tof_bg_preview_anchor")
            if preview_range is not None:
                t0, t1 = preview_range
                preview_patch = Rectangle(
                    (t0, min(y0, y1)),
                    t1 - t0,
                    max(abs(y1 - y0), 1e-9),
                    fill=True,
                    linewidth=1.0,
                    edgecolor="#ff9f1c",
                    facecolor="#ff9f1c",
                    linestyle="--",
                    alpha=0.14,
                    zorder=6.6,
                )
                preview_patch.set_gid("ion_tof_bg_preview_range")
                ax.add_patch(preview_patch)
            with contextlib.suppress(Exception):
                ax.set_xlim(xlim[0], xlim[1], auto=False)
                ax.set_ylim(ylim[0], ylim[1], auto=False)
        if draw_canvas and (self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy")):
            self._draw_axes_preview([ax])

    def _set_ion_tof_bg_enabled(self, enabled: bool, *, announce: bool = False) -> None:
        """Update the stored background-subtraction enable state and keep checkbox in sync."""
        self.ion_tof_bg_enabled = bool(enabled)
        checkbox = getattr(self, "ion_tof_bg_enable_checkbox", None)
        if checkbox is not None and bool(checkbox.isChecked()) != bool(enabled):
            was = checkbox.blockSignals(True)
            checkbox.setChecked(bool(enabled))
            checkbox.blockSignals(was)
        if announce:
            state_text = "ON" if enabled else "OFF"
            self._set_status(f"Ion X/Y-TOF background subtraction {state_text}.")

    def _ion_tof_bg_subtraction_enabled(self) -> bool:
        """Return whether ion X/Y-TOF background subtraction is active."""
        return bool(getattr(self, "ion_tof_bg_enabled", False))

    def _invalidate_ion_tof_bg_model(self, *, clear_summary: bool) -> None:
        """Clear cached background-subtraction model state."""
        self._ion_tof_bg_model_cache_key = None
        self._ion_tof_bg_model_state = None
        if clear_summary:
            self.ion_tof_bg_fit_state = None

    def _format_ion_tof_bg_summary(self) -> str:
        """Return compact multi-line summary for the current outside-box background-subtraction state."""
        box_count = self._ion_tof_bg_box_count()
        fit = self.ion_tof_bg_fit_state
        enabled = self._ion_tof_bg_subtraction_enabled()
        if not isinstance(fit, dict):
            if box_count <= 0:
                return "No background subtraction fit."
            state_text = "ON" if enabled else "OFF"
            return f"BG boxes={box_count}. Fit the outside-box XY-density/radial-floor background model. State={state_text}."
        lines = []
        train_count = int(fit.get("bg_training_count", 0))
        signal_count = int(fit.get("signal_training_count", 0))
        point_count = int(fit.get("point_count", 0))
        removed_count = int(fit.get("removed_count", 0))
        kept_count = int(fit.get("kept_count", max(point_count - removed_count, 0)))
        threshold = fit.get("score_threshold")
        bg_scale = fit.get("bg_scale")
        lines.append(
            f"BG model: boxes={int(fit.get('box_count', box_count))}, bg={train_count}, sig={signal_count}, "
            f"keep={kept_count}, remove={removed_count}"
        )
        detail = f"points={point_count}"
        if isinstance(threshold, (int, float, np.integer, np.floating)) and np.isfinite(float(threshold)):
            detail += f", thresh={float(threshold):.3f}"
        if isinstance(bg_scale, (int, float, np.integer, np.floating)) and np.isfinite(float(bg_scale)):
            detail += f", scale={float(bg_scale):.3f}"
        detail += f", state={'ON' if enabled else 'OFF'}"
        lines.append(detail)
        fit_mode = str(fit.get("fit_mode", "")).strip()
        if fit_mode:
            lines.append(fit_mode)
        return "\n".join(lines)

    def _sync_ion_tof_bg_controls(self) -> None:
        """Refresh background-subtraction widgets and summary label."""
        self._set_ion_tof_bg_enabled(self._ion_tof_bg_subtraction_enabled(), announce=False)
        if hasattr(self, "ion_tof_bg_result_label"):
            self.ion_tof_bg_result_label.setText(self._format_ion_tof_bg_summary())
        self._update_ion_tof_bg_selector_state()

    def _handle_ion_tof_bg_ranges_changed(self, *, announce_text: str | None = None) -> bool:
        """Invalidate or refit the background model after the fit-box signal proxy changes."""
        enabled = self._ion_tof_bg_subtraction_enabled()
        self._invalidate_ion_tof_bg_model(clear_summary=True)
        ok = True
        if enabled and self._ion_tof_bg_training_ready():
            ok = isinstance(self._ensure_ion_tof_bg_model(show_dialog=False, force_refit=True), dict)
            if not ok:
                self._set_ion_tof_bg_enabled(False, announce=False)
        elif enabled and (not self._ion_tof_bg_training_ready()):
            self._set_ion_tof_bg_enabled(False, announce=False)
        self._sync_ion_tof_bg_controls()
        cleared_dependent = False
        if self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy"):
            if enabled:
                cleared_dependent = self._refresh_after_bg_filter_change(preserve_hist_view=True)
            else:
                self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=False, preserve_view=True)
        if announce_text:
            msg = str(announce_text)
            if enabled and cleared_dependent:
                msg += " Projection/reconstruction cleared; reapply ring selection."
            self._set_status(msg)
        return ok

    def _on_ion_tof_bg_pick_toggled(self, checked: bool) -> None:
        """Toggle shared TOF-background range picking mode for the ion X/Y-TOF map."""
        if checked and (not self._has_pairs()):
            was = self.ion_tof_bg_pick_btn.blockSignals(True)
            self.ion_tof_bg_pick_btn.setChecked(False)
            self.ion_tof_bg_pick_btn.blockSignals(was)
            self._set_status("Run Process and Plot before selecting TOF background ranges.")
            return
        if checked and bool(getattr(self, "ion_tof_fit_pick_btn", None) and self.ion_tof_fit_pick_btn.isChecked()):
            fit_btn = self.ion_tof_fit_pick_btn
            was = fit_btn.blockSignals(True)
            fit_btn.setChecked(False)
            fit_btn.blockSignals(was)
        self._clear_ion_tof_bg_pending_selection(update_preview=False)
        self._update_ion_tof_bg_selector_state()
        self._update_ion_tof_fit_selector_state()
        self._update_ion_tof_bg_preview_artists(draw_canvas=bool(self._has_pairs()))
        coord_axis = self._ion_tof_pos_axis_label().upper()
        if checked:
            self._set_status(
                f"Ion {coord_axis}-TOF background-range picker on. Click left then right TOF edges to add ranges; "
                "double-click inside a background window to remove it."
            )
        else:
            self._set_status(f"Ion {coord_axis}-TOF background-range picker off.")

    def _commit_ion_tof_bg_range(
        self,
        tof_range: tuple[float, float] | list[float] | np.ndarray,
    ) -> bool:
        """Store one TOF background window and invalidate/refit the current model."""
        norm_range = self._normalize_ion_tof_bg_range(tof_range)
        if norm_range is None:
            return False
        ranges = list(self._current_ion_tof_bg_ranges())
        ranges.append(norm_range)
        self._set_ion_tof_bg_ranges(ranges)
        self._clear_ion_tof_bg_pending_selection(update_preview=False)
        self._handle_ion_tof_bg_ranges_changed(
            announce_text=f"Ion X/Y-TOF background ranges: {len(self._current_ion_tof_bg_ranges())} selected. Fit the BG model to update subtraction."
        )
        return True

    def _remove_ion_tof_bg_range_at_tof(self, tof_value: float) -> bool:
        """Remove one stored TOF background window containing `tof_value`."""
        idx = self._ion_tof_bg_range_index_at_tof(tof_value)
        if idx is None:
            return False
        ranges = list(self._current_ion_tof_bg_ranges())
        if idx < 0 or idx >= len(ranges):
            return False
        ranges.pop(idx)
        self._set_ion_tof_bg_ranges(ranges)
        self._clear_ion_tof_bg_pending_selection(update_preview=False)
        self._handle_ion_tof_bg_ranges_changed(
            announce_text=(
                f"Ion X/Y-TOF background ranges: {len(ranges)} remaining."
                if len(ranges) > 0
                else "Ion X/Y-TOF background ranges cleared."
            )
        )
        return True

    def clear_ion_tof_background_subtraction(self, _checked: bool = False) -> None:
        """Clear the fitted background model, legacy TOF ranges, and active subtraction state."""
        had_ranges = len(self._current_ion_tof_bg_ranges()) > 0
        had_boxes = self._ion_tof_bg_training_ready()
        was_enabled = self._ion_tof_bg_subtraction_enabled()
        self._set_ion_tof_bg_ranges([])
        self._clear_ion_tof_bg_pending_selection(update_preview=False)
        self._invalidate_ion_tof_bg_model(clear_summary=True)
        self._set_ion_tof_bg_enabled(False, announce=False)
        self._sync_ion_tof_bg_controls()
        cleared_dependent = False
        if self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy"):
            if was_enabled:
                cleared_dependent = self._refresh_after_bg_filter_change(preserve_hist_view=True)
            else:
                self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=False, preserve_view=True)
        if had_ranges or had_boxes or was_enabled:
            msg = "Ion X/Y-TOF background subtraction cleared."
            if was_enabled and cleared_dependent:
                msg += " Projection/reconstruction cleared; reapply ring selection."
            self._set_status(msg)

    def _on_ion_tof_bg_enabled_toggled(self, checked: bool) -> None:
        """Enable or disable the fitted outside-box XY-density/radial-floor background subtraction."""
        if not checked:
            if self._ion_tof_bg_subtraction_enabled():
                self._set_ion_tof_bg_enabled(False, announce=False)
                self._sync_ion_tof_bg_controls()
                cleared_dependent = False
                if self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy"):
                    cleared_dependent = self._refresh_after_bg_filter_change(preserve_hist_view=True)
                msg = "Ion X/Y-TOF background subtraction OFF."
                if cleared_dependent:
                    msg += " Projection/reconstruction cleared; reapply ring selection."
                self._set_status(msg)
            return
        if not self._has_pairs():
            was = self.ion_tof_bg_enable_checkbox.blockSignals(True)
            self.ion_tof_bg_enable_checkbox.setChecked(False)
            self.ion_tof_bg_enable_checkbox.blockSignals(was)
            self._set_status("Run Process and Plot before enabling background subtraction.")
            return
        if not self._ion_tof_bg_training_ready():
            was = self.ion_tof_bg_enable_checkbox.blockSignals(True)
            self.ion_tof_bg_enable_checkbox.setChecked(False)
            self.ion_tof_bg_enable_checkbox.blockSignals(was)
            self._set_status("Add at least one X-TOF or Y-TOF fit box first; BG fitting now uses the points outside those boxes.")
            return
        ok = bool(self.fit_ion_tof_background_model(announce=False))
        if not ok:
            self._set_ion_tof_bg_enabled(False, announce=False)
            self._sync_ion_tof_bg_controls()
            return
        self._set_ion_tof_bg_enabled(True, announce=False)
        self._sync_ion_tof_bg_controls()
        cleared_dependent = False
        if self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy"):
            cleared_dependent = self._refresh_after_bg_filter_change(preserve_hist_view=True)
        removed = int((self.ion_tof_bg_fit_state or {}).get("removed_count", 0))
        msg = f"Ion X/Y-TOF background subtraction ON. Estimated background points removed: {removed}."
        if cleared_dependent:
            msg += " Projection/reconstruction cleared; reapply ring selection."
        self._set_status(msg)

    def _on_ion_tof_fit_pick_toggled(self, checked: bool) -> None:
        """Toggle multi-box ROI picking mode for the ion X/Y-TOF map."""
        if checked and (not self._has_pairs()):
            was = self.ion_tof_fit_pick_btn.blockSignals(True)
            self.ion_tof_fit_pick_btn.setChecked(False)
            self.ion_tof_fit_pick_btn.blockSignals(was)
            self._set_status("Run Process and Plot before selecting an X/Y-TOF alignment ROI.")
            return
        if checked and bool(getattr(self, "ion_tof_bg_pick_btn", None) and self.ion_tof_bg_pick_btn.isChecked()):
            bg_btn = self.ion_tof_bg_pick_btn
            was = bg_btn.blockSignals(True)
            bg_btn.setChecked(False)
            bg_btn.blockSignals(was)
        self._clear_ion_tof_fit_pending_selection(update_preview=False)
        self._update_ion_tof_bg_selector_state()
        self._update_ion_tof_fit_selector_state()
        self._update_ion_tof_fit_preview_artists(draw_canvas=bool(self._has_pairs()))
        coord_axis = self._ion_tof_pos_axis_label().upper()
        if checked:
            self._set_status(
                f"Ion {coord_axis}-TOF box picker on. Drag one box or click two opposite corners to add boxes; "
                "double-click inside a box to remove it."
            )
        else:
            self._set_status(f"Ion {coord_axis}-TOF box picker off.")

    @staticmethod
    def _ion_tof_polygon_bounds(points: list[tuple[float, float]] | tuple[tuple[float, float], ...] | None) -> tuple[float, float, float, float] | None:
        """Return the bounding box `(tof_min, tof_max, coord_min, coord_max)` for one polygon."""
        if not points:
            return None
        arr = np.asarray(points, dtype=np.float64).reshape(-1, 2)
        if arr.shape[0] <= 0 or (not np.isfinite(arr).all()):
            return None
        return (
            float(np.min(arr[:, 0])),
            float(np.max(arr[:, 0])),
            float(np.min(arr[:, 1])),
            float(np.max(arr[:, 1])),
        )

    @staticmethod
    def _normalize_ion_tof_fit_box(
        box: tuple[float, float, float, float] | list[float] | np.ndarray | None,
    ) -> tuple[float, float, float, float] | None:
        """Normalize one rectangle box into `(tof_min, tof_max, coord_min, coord_max)`."""
        if box is None:
            return None
        vals = np.asarray(box, dtype=np.float64).reshape(-1)
        if vals.size < 4 or (not np.isfinite(vals[:4]).all()):
            return None
        t0, t1 = sorted((float(vals[0]), float(vals[1])))
        c0, c1 = sorted((float(vals[2]), float(vals[3])))
        if abs(t1 - t0) <= 1e-12 or abs(c1 - c0) <= 1e-12:
            return None
        return float(t0), float(t1), float(c0), float(c1)

    @classmethod
    def _normalize_ion_tof_fit_boxes(
        cls,
        boxes: list[tuple[float, float, float, float]] | tuple[tuple[float, float, float, float], ...] | None,
    ) -> tuple[tuple[float, float, float, float], ...]:
        """Return all valid normalized fit boxes."""
        if not isinstance(boxes, (list, tuple)):
            return ()
        out: list[tuple[float, float, float, float]] = []
        for box in boxes:
            norm_box = cls._normalize_ion_tof_fit_box(box)
            if norm_box is not None:
                out.append(norm_box)
        return tuple(out)

    @staticmethod
    def _ion_tof_fit_box_union(
        boxes: list[tuple[float, float, float, float]] | tuple[tuple[float, float, float, float], ...] | None,
    ) -> tuple[float, float, float, float] | None:
        """Return the union bounds of all valid fit boxes."""
        norm_boxes = MainWindow._normalize_ion_tof_fit_boxes(boxes)
        if len(norm_boxes) <= 0:
            return None
        arr = np.asarray(norm_boxes, dtype=np.float64).reshape(-1, 4)
        return (
            float(np.min(arr[:, 0])),
            float(np.max(arr[:, 1])),
            float(np.min(arr[:, 2])),
            float(np.max(arr[:, 3])),
        )

    def _current_ion_tof_fit_boxes(
        self,
        axis_mode: str | None = None,
    ) -> tuple[tuple[float, float, float, float], ...]:
        """Return the stored fit boxes for one axis."""
        axis_key = self._current_ion_tof_pos_axis() if axis_mode is None else str(axis_mode).lower()
        axis_key = "y" if axis_key == "y" else "x"
        boxes = self.ion_tof_fit_boxes_by_axis.get(axis_key, [])
        return self._normalize_ion_tof_fit_boxes(boxes)

    def _set_ion_tof_fit_boxes(
        self,
        boxes: list[tuple[float, float, float, float]] | tuple[tuple[float, float, float, float], ...],
        *,
        axis_mode: str | None = None,
    ) -> tuple[tuple[float, float, float, float], ...]:
        """Store normalized fit boxes and keep the legacy union ROI in sync."""
        axis_key = self._current_ion_tof_pos_axis() if axis_mode is None else str(axis_mode).lower()
        axis_key = "y" if axis_key == "y" else "x"
        norm_boxes = self._normalize_ion_tof_fit_boxes(boxes)
        self.ion_tof_fit_boxes_by_axis[axis_key] = [tuple(box) for box in norm_boxes]
        self.ion_tof_fit_roi_by_axis[axis_key] = self._ion_tof_fit_box_union(norm_boxes)
        self.ion_tof_fit_polygon_by_axis[axis_key] = None
        return norm_boxes

    def _current_ion_tof_bg_signal_boxes_by_axis(
        self,
    ) -> dict[str, tuple[tuple[float, float, float, float], ...]]:
        """Return the stored X/Y-TOF fit boxes used as the signal proxy for BG fitting."""
        return {
            "x": self._normalize_ion_tof_fit_boxes(self.ion_tof_fit_boxes_by_axis.get("x", [])),
            "y": self._normalize_ion_tof_fit_boxes(self.ion_tof_fit_boxes_by_axis.get("y", [])),
        }

    def _ion_tof_bg_box_state_key(self) -> tuple[tuple[str, tuple[tuple[float, float, float, float], ...]], ...]:
        """Return a stable cache key for the stored BG-training signal boxes."""
        boxes = self._current_ion_tof_bg_signal_boxes_by_axis()
        return (
            ("x", tuple(tuple(float(v) for v in box) for box in boxes.get("x", ()))),
            ("y", tuple(tuple(float(v) for v in box) for box in boxes.get("y", ()))),
        )

    def _ion_tof_bg_box_count(self) -> int:
        """Return total X/Y-TOF fit-box count used by BG fitting."""
        boxes = self._current_ion_tof_bg_signal_boxes_by_axis()
        return int(len(boxes.get("x", ())) + len(boxes.get("y", ())))

    def _ion_tof_bg_training_ready(self) -> bool:
        """Return whether enough fit boxes exist to define signal/background proxies."""
        return self._ion_tof_bg_box_count() > 0

    def _clear_ion_tof_fit_pending_selection(self, *, update_preview: bool = False) -> None:
        """Clear the in-progress box corner selection."""
        self._ion_tof_fit_pending_axis = None
        self._ion_tof_fit_pending_points = []
        self._ion_tof_fit_hover_point = None
        self._ion_tof_fit_press_armed = False
        self._ion_tof_fit_drag_active = False
        self._ion_tof_fit_drag_anchor_canvas_pos = None
        self._hide_ion_tof_fit_drag_preview()
        if update_preview:
            self._update_ion_tof_fit_preview_artists(draw_canvas=True)

    def _invalidate_ion_tof_fit_preview_background(self) -> None:
        """Drop the cached coincidence-map preview background."""
        self.bg_ion_tof_xy_preview = None
        self._ion_tof_fit_preview_bg_key = None
        self._blit_bg_geom["ion_tof_xy_preview"] = None

    def _clear_ion_tof_fit_preview_artists(self) -> None:
        """Remove live coincidence-map preview artists, if present."""
        for attr in ("ion_tof_fit_preview_patch", "ion_tof_fit_preview_anchor_artist"):
            artist = getattr(self, attr, None)
            if artist is not None:
                with contextlib.suppress(Exception):
                    artist.remove()
                setattr(self, attr, None)

    def _current_ion_tof_fit_preview_bg_key(self) -> tuple[object, ...] | None:
        """Return a cache key describing the current ion TOF preview view."""
        ax = getattr(self, "ax_ion_tof_xy", None)
        if ax is None:
            return None
        bbox = getattr(ax, "bbox", None)
        xlim = tuple(float(v) for v in ax.get_xlim())
        ylim = tuple(float(v) for v in ax.get_ylim())
        if bbox is None:
            return (xlim, ylim)
        return (
            xlim,
            ylim,
            float(bbox.x0),
            float(bbox.y0),
            float(bbox.x1),
            float(bbox.y1),
        )

    def _ensure_ion_tof_fit_preview_background(self) -> bool:
        """Capture a clean ion TOF panel background for fast live preview.

        The preview artists are animated, so a single-axes render excludes them
        and the snapshot can never bake in a previously drawn preview box/anchor
        (16f: this tightens the legacy copy-from-current-canvas capture, which
        double-composited the stationary anchor).
        """
        ax = getattr(self, "ax_ion_tof_xy", None)
        if ax is None:
            return False
        bg_key = self._current_ion_tof_fit_preview_bg_key()
        if bg_key is None:
            return False
        if self.bg_ion_tof_xy_preview is not None and self._ion_tof_fit_preview_bg_key == bg_key:
            return True
        try:
            renderer = self.canvas.get_renderer()
            if renderer is not None:
                hidden = []
                for txt in self._axes_above_texts(ax, 7.5):
                    hidden.append((txt, txt.get_visible()))
                    txt.set_visible(False)
                try:
                    ax.draw(renderer)  # animated preview artists are skipped: clean
                    self.bg_ion_tof_xy_preview = self.canvas.copy_from_bbox(ax.bbox)
                    self._record_blit_bg_size("ion_tof_xy_preview")
                finally:
                    for txt, visible in hidden:
                        with contextlib.suppress(Exception):
                            txt.set_visible(visible)
                self._ion_tof_fit_preview_bg_key = bg_key
                return self.bg_ion_tof_xy_preview is not None
            self.bg_ion_tof_xy_preview = self.canvas.copy_from_bbox(ax.bbox)
            self._record_blit_bg_size("ion_tof_xy_preview")
            self._ion_tof_fit_preview_bg_key = bg_key
            return True
        except Exception:
            self._invalidate_ion_tof_fit_preview_background()
            return False

    def _present_ion_tof_fit_preview_from_background(self) -> bool:
        """Present the coincidence preview from cached background without a full redraw."""
        ax = getattr(self, "ax_ion_tof_xy", None)
        if ax is None or self.bg_ion_tof_xy_preview is None:
            return False
        if not self._blit_bg_size_matches("ion_tof_xy_preview"):
            # Stale geometry: never restore, fall back to a normal redraw.
            self._invalidate_ion_tof_fit_preview_background()
            return False
        try:
            self.canvas.restore_region(self.bg_ion_tof_xy_preview)
            if self.ion_tof_fit_preview_patch is not None and self.ion_tof_fit_preview_patch.axes is ax:
                ax.draw_artist(self.ion_tof_fit_preview_patch)
            if self.ion_tof_fit_preview_anchor_artist is not None and self.ion_tof_fit_preview_anchor_artist.axes is ax:
                ax.draw_artist(self.ion_tof_fit_preview_anchor_artist)
            # Keep above-layer artists (buttons, annotations) on top.
            for txt in self._axes_above_texts(ax, 7.5):
                ax.draw_artist(txt)
            self._mark_plot_scroll_preview_cache_dirty(refresh_soon=True)
            self._present_canvas_now(request_idle_draw=False)
            return True
        except Exception:
            self._invalidate_ion_tof_fit_preview_background()
            return False

    def _current_ion_tof_fit_preview_box(self) -> tuple[float, float, float, float] | None:
        """Return the currently previewed box from the first stored corner plus hover position."""
        axis_key = self._current_ion_tof_pos_axis()
        if getattr(self, "_ion_tof_fit_pending_axis", None) != axis_key:
            return None
        pending_pts = list(getattr(self, "_ion_tof_fit_pending_points", []))
        if len(pending_pts) <= 0:
            return None
        hover = getattr(self, "_ion_tof_fit_hover_point", None)
        if hover is None:
            return None
        anchor = pending_pts[0]
        return self._normalize_ion_tof_fit_box((anchor[0], hover[0], anchor[1], hover[1]))

    def _ion_tof_fit_box_index_at_point(
        self,
        tof_value: float,
        coord_value: float,
        *,
        axis_mode: str | None = None,
    ) -> int | None:
        """Return the topmost stored box index containing the clicked point."""
        boxes = self._current_ion_tof_fit_boxes(axis_mode)
        if len(boxes) <= 0 or (not np.isfinite([tof_value, coord_value]).all()):
            return None
        for rev_idx, box in enumerate(reversed(boxes)):
            t0, t1, c0, c1 = box
            if t0 <= float(tof_value) <= t1 and c0 <= float(coord_value) <= c1:
                return len(boxes) - 1 - rev_idx
        return None

    def _update_ion_tof_fit_preview_artists(self, *, draw_canvas: bool) -> None:
        """Refresh the live rectangle-box preview on the ion X/Y-TOF subplot."""
        ax = getattr(self, "ax_ion_tof_xy", None)
        if ax is None:
            return
        use_fast_preview = bool(sys.platform.startswith("win"))
        if self.ion_tof_fit_preview_patch is not None and self.ion_tof_fit_preview_patch.axes is not ax:
            self.ion_tof_fit_preview_patch = None
        if self.ion_tof_fit_preview_anchor_artist is not None and self.ion_tof_fit_preview_anchor_artist.axes is not ax:
            self.ion_tof_fit_preview_anchor_artist = None
        axis_key = self._current_ion_tof_pos_axis()
        if getattr(self, "_ion_tof_fit_pending_axis", None) == axis_key:
            pending_pts = list(getattr(self, "_ion_tof_fit_pending_points", []))
        else:
            pending_pts = []
        preview_box = self._current_ion_tof_fit_preview_box()
        created_artist = False
        if pending_pts or preview_box is not None:
            xlim = ax.get_xlim()
            ylim = ax.get_ylim()
            if pending_pts:
                preview_points = np.asarray(pending_pts, dtype=np.float64).reshape(-1, 2)
                scat = self.ion_tof_fit_preview_anchor_artist
                if scat is None or scat.axes is not ax:
                    scat = ax.scatter(
                        preview_points[:, 0],
                        preview_points[:, 1],
                        s=20,
                        color="#00d4ff",
                        edgecolors="white",
                        linewidths=0.55,
                        alpha=0.97,
                        zorder=7,
                        animated=use_fast_preview,
                    )
                    scat.set_gid("ion_tof_fit_preview_anchor")
                    self.ion_tof_fit_preview_anchor_artist = scat
                    created_artist = True
                with contextlib.suppress(Exception):
                    scat.set_offsets(preview_points)
                with contextlib.suppress(Exception):
                    scat.set_animated(use_fast_preview)
                with contextlib.suppress(Exception):
                    scat.set_visible(True)
            elif self.ion_tof_fit_preview_anchor_artist is not None:
                with contextlib.suppress(Exception):
                    self.ion_tof_fit_preview_anchor_artist.remove()
                self.ion_tof_fit_preview_anchor_artist = None
            if preview_box is not None:
                t0, t1, c0, c1 = preview_box
                preview_patch = self.ion_tof_fit_preview_patch
                if preview_patch is None or preview_patch.axes is not ax:
                    preview_patch = Rectangle(
                        (t0, c0),
                        t1 - t0,
                        c1 - c0,
                        fill=False,
                        linewidth=1.15,
                        edgecolor="#00d4ff",
                        linestyle="--",
                        alpha=0.95,
                        zorder=6,
                        animated=use_fast_preview,
                    )
                    preview_patch.set_gid("ion_tof_fit_preview_box")
                    ax.add_patch(preview_patch)
                    self.ion_tof_fit_preview_patch = preview_patch
                    created_artist = True
                with contextlib.suppress(Exception):
                    preview_patch.set_xy((t0, c0))
                with contextlib.suppress(Exception):
                    preview_patch.set_width(t1 - t0)
                with contextlib.suppress(Exception):
                    preview_patch.set_height(c1 - c0)
                with contextlib.suppress(Exception):
                    preview_patch.set_animated(use_fast_preview)
                with contextlib.suppress(Exception):
                    preview_patch.set_visible(True)
            elif self.ion_tof_fit_preview_patch is not None:
                with contextlib.suppress(Exception):
                    self.ion_tof_fit_preview_patch.remove()
                self.ion_tof_fit_preview_patch = None
            if created_artist:
                self._invalidate_ion_tof_fit_preview_background()
            with contextlib.suppress(Exception):
                ax.set_xlim(xlim[0], xlim[1], auto=False)
                ax.set_ylim(ylim[0], ylim[1], auto=False)
        else:
            self._clear_ion_tof_fit_preview_artists()
        if draw_canvas and (self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy")):
            if use_fast_preview and self._ensure_ion_tof_fit_preview_background():
                if self._present_ion_tof_fit_preview_from_background():
                    return
            self._draw_axes_preview([ax])

    def _update_ion_tof_fit_after_boxes_changed(self, axis_mode: str | None = None) -> bool:
        """Refresh fit state after stored boxes are added or removed."""
        axis_key = self._current_ion_tof_pos_axis() if axis_mode is None else str(axis_mode).lower()
        axis_key = "y" if axis_key == "y" else "x"
        coord_axis = self._ion_tof_pos_axis_label(axis_key).upper()
        boxes = self._current_ion_tof_fit_boxes(axis_key)
        bg_enabled = self._ion_tof_bg_subtraction_enabled()
        self._sync_ion_tof_alignment_controls(axis_key)
        if len(boxes) >= 2:
            ok = bool(self.fit_ion_tof_alignment_line())
            if not ok:
                self.ion_tof_fit_result_by_axis[axis_key] = None
                self._sync_ion_tof_alignment_controls(axis_key)
                if self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy"):
                    self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=False, preserve_view=True)
            self._handle_ion_tof_bg_ranges_changed(
                announce_text=(
                    f"Ion {coord_axis}-TOF fit boxes updated: axis now has {len(boxes)} boxes."
                    if self._ion_tof_bg_training_ready()
                    else "Ion X/Y-TOF fit boxes updated."
                )
            )
            return ok
        self.ion_tof_fit_result_by_axis[axis_key] = None
        self._sync_ion_tof_alignment_controls(axis_key)
        if self._has_pairs() or self._subplot_has_session_preview("ion_tof_xy"):
            self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=False, preserve_view=True)
        self._handle_ion_tof_bg_ranges_changed(
            announce_text=(
                "Ion X/Y-TOF fit boxes cleared."
                if not self._ion_tof_bg_training_ready()
                else f"Ion {coord_axis}-TOF fit boxes updated: axis now has {len(boxes)} boxes."
            )
        )
        if len(boxes) == 1:
            status = f"Ion {coord_axis}-TOF has 1 fit box. Add at least one more box to fit a line."
            if bg_enabled:
                status += " BG fitting can already use points outside the current boxes."
            self._set_status(status)
        else:
            self._set_status(f"Ion {coord_axis}-TOF fit boxes cleared.")
        return False

    def _commit_ion_tof_fit_box(
        self,
        box: tuple[float, float, float, float] | list[float] | np.ndarray,
        *,
        axis_mode: str | None = None,
    ) -> bool:
        """Store one finished fit box and refresh the matching fit."""
        axis_key = self._current_ion_tof_pos_axis() if axis_mode is None else str(axis_mode).lower()
        axis_key = "y" if axis_key == "y" else "x"
        norm_box = self._normalize_ion_tof_fit_box(box)
        if norm_box is None:
            return False
        boxes = list(self._current_ion_tof_fit_boxes(axis_key))
        boxes.append(norm_box)
        self._set_ion_tof_fit_boxes(boxes, axis_mode=axis_key)
        self._clear_ion_tof_fit_pending_selection(update_preview=False)
        self._update_ion_tof_fit_after_boxes_changed(axis_key)
        return True

    def _remove_ion_tof_fit_box_at_point(
        self,
        tof_value: float,
        coord_value: float,
        *,
        axis_mode: str | None = None,
    ) -> bool:
        """Remove one stored fit box containing the clicked point and refresh the fit."""
        axis_key = self._current_ion_tof_pos_axis() if axis_mode is None else str(axis_mode).lower()
        axis_key = "y" if axis_key == "y" else "x"
        idx = self._ion_tof_fit_box_index_at_point(tof_value, coord_value, axis_mode=axis_key)
        if idx is None:
            return False
        boxes = list(self._current_ion_tof_fit_boxes(axis_key))
        if idx < 0 or idx >= len(boxes):
            return False
        boxes.pop(idx)
        self._set_ion_tof_fit_boxes(boxes, axis_mode=axis_key)
        self._clear_ion_tof_fit_pending_selection(update_preview=False)
        self._update_ion_tof_fit_after_boxes_changed(axis_key)
        return True

    def _on_ion_tof_fit_roi_selected(self, eclick, erelease) -> None:
        """Compatibility helper: convert one drag-selected rectangle into one stored fit box."""
        if not self._has_pairs():
            return
        x0 = getattr(eclick, "xdata", None)
        x1 = getattr(erelease, "xdata", None)
        y0 = getattr(eclick, "ydata", None)
        y1 = getattr(erelease, "ydata", None)
        if x0 is None or x1 is None or y0 is None or y1 is None:
            return
        self._commit_ion_tof_fit_box((float(x0), float(x1), float(y0), float(y1)), axis_mode=self._current_ion_tof_pos_axis())

    def _set_ion_hist_modifier_guard(self, active: bool) -> None:
        """Temporarily disable Fine ROI interactions while Ctrl/Shift is held."""
        active_bool = bool(active)
        if active_bool == bool(getattr(self, "_ion_hist_modifier_guard_active", False)):
            return
        self._ion_hist_modifier_guard_active = active_bool
        if active_bool:
            self.pending_ion_span_range = None
            self.ion_span_apply_timer.stop()
            selector = getattr(self, "ion_selector", None)
            if selector is not None:
                with contextlib.suppress(Exception):
                    selector.clear()
        self._update_ion_hist_span_selector_state()

    def _sync_ion_hist_modifier_guard(self, qt_modifiers=None, *, default_inactive: bool = False) -> None:
        """Mirror current Qt Ctrl/Shift state into the histogram ROI interaction guard."""
        mods = qt_modifiers
        if mods is None:
            if default_inactive:
                mods = Qt.NoModifier
            else:
                with contextlib.suppress(Exception):
                    mods = QApplication.keyboardModifiers()
        active = False
        with contextlib.suppress(Exception):
            active = bool(mods & (Qt.ControlModifier | Qt.ShiftModifier))
        self._set_ion_hist_modifier_guard(active)

    @staticmethod
    def _qt_modifiers_from_mpl_event(event):
        """Extract Qt keyboard modifiers from a matplotlib mouse event when available."""
        if event is None:
            return None
        gui_event = getattr(event, "guiEvent", None)
        if gui_event is not None and hasattr(gui_event, "modifiers"):
            with contextlib.suppress(Exception):
                return gui_event.modifiers()
        if hasattr(event, "modifiers"):
            with contextlib.suppress(Exception):
                return event.modifiers()
        return None

    def _pause_ion_hist_span_selector_until_release(self) -> None:
        """Pause Fine ROI span handling for the current mouse gesture."""
        self._ion_hist_span_pause_until_release = True
        self.pending_ion_span_range = None
        self.ion_span_apply_timer.stop()
        selector = getattr(self, "ion_selector", None)
        if selector is not None:
            with contextlib.suppress(Exception):
                selector.clear()
        self._update_ion_hist_span_selector_state()

    def _resume_ion_hist_span_selector_after_release(self, qt_modifiers=None) -> None:
        """Restore Fine ROI span handling after a temporary gesture pause."""
        if not bool(getattr(self, "_ion_hist_span_pause_until_release", False)):
            self._sync_ion_hist_modifier_guard(qt_modifiers, default_inactive=(qt_modifiers is None))
            self._update_ion_hist_span_selector_state()
            return
        self._ion_hist_span_pause_until_release = False
        self._sync_ion_hist_modifier_guard(qt_modifiers, default_inactive=(qt_modifiers is None))
        self._update_ion_hist_span_selector_state()

    def _wire_horizontal_view_slider(self) -> None:
        """Bind the custom bottom slider to the plot area's horizontal scroll bar."""
        hbar = self.plot_scroll.horizontalScrollBar()

        def update_slider_range() -> None:
            self.h_view_slider.setMinimum(hbar.minimum())
            self.h_view_slider.setMaximum(hbar.maximum())
            self.h_view_slider.setValue(hbar.value())

        def on_hbar_changed(value: int) -> None:
            was = self.h_view_slider.blockSignals(True)
            self.h_view_slider.setValue(value)
            self.h_view_slider.blockSignals(was)

        def on_slider_changed(value: int) -> None:
            hbar.setValue(value)

        hbar.valueChanged.connect(on_hbar_changed)
        self.h_view_slider.valueChanged.connect(on_slider_changed)
        hbar.rangeChanged.connect(lambda _a, _b: update_slider_range())
        update_slider_range()

    def _build_control_tab_scroll_area(self, *groups: QGroupBox) -> QScrollArea:
        """Wrap one or more existing control groups into a tab-local scroll area."""
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)
        for group in groups:
            if group is not None:
                layout.addWidget(group)
        layout.addStretch(1)

        scroll = QScrollArea()
        scroll.setWidget(page)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOn)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        return scroll

    def _current_control_scroll_area(self) -> QScrollArea | None:
        """Return the active control-tab scroll area for wheel routing."""
        tabs = getattr(self, "control_tabs", None)
        if tabs is not None:
            widget = tabs.currentWidget()
            if isinstance(widget, QScrollArea):
                return widget
        scroll = getattr(self, "control_scroll", None)
        return scroll if isinstance(scroll, QScrollArea) else None

    def _current_control_tab_name(self) -> str:
        """Return the user-visible name of the currently selected control tab."""
        tabs = getattr(self, "control_tabs", None)
        if tabs is None:
            return "File"
        idx = tabs.currentIndex()
        if isinstance(idx, int) and 0 <= idx < tabs.count():
            return str(tabs.tabText(idx))
        return "File"

    def _refresh_settings_affordances(self) -> None:
        """Keep tray labels and toolbar hints aligned with the currently selected settings tab."""
        tab_name = self._current_control_tab_name()
        target_label = getattr(self, "settings_target_label", None)
        if isinstance(target_label, QLabel):
            target_label.setText(f"Target: {tab_name}")
        header_label = getattr(self, "settings_header_target_label", None)
        if isinstance(header_label, QLabel):
            header_label.setText(f"Editing: {tab_name}")

    def _scroll_current_control_tab_to_top(self) -> None:
        """Bring the start of the selected settings tab into view after switching domains."""
        scroll = self._current_control_scroll_area()
        if scroll is None:
            return
        with contextlib.suppress(Exception):
            scroll.verticalScrollBar().setValue(scroll.verticalScrollBar().minimum())

    def _settings_panel_current_height(self) -> int:
        """Return the current visible height of the settings tray from the splitter state."""
        splitter = getattr(self, "plot_settings_splitter", None)
        panel = getattr(self, "settings_panel", None)
        if panel is not None and not panel.isVisible():
            return 0
        if splitter is None:
            return 0
        with contextlib.suppress(Exception):
            sizes = splitter.sizes()
            if isinstance(sizes, list) and len(sizes) >= 2:
                return max(int(sizes[1]), 0)
        return 0

    def _settings_panel_is_visible(self) -> bool:
        """Return whether the settings tray is currently expanded enough to be considered visible."""
        return self._settings_panel_current_height() > 24

    def _set_settings_splitter_drag_active(self, active: bool) -> None:
        """Track whether the tray splitter handle is actively being dragged."""
        active = bool(active)
        panel = getattr(self, "settings_panel", None)
        if panel is not None and not panel.isVisible():
            active = False
        if getattr(self, "_settings_splitter_drag_active", False) == active:
            return
        self._settings_splitter_drag_active = active
        if not active:
            QTimer.singleShot(0, self._refresh_plot_view_after_layout_change)

    def _on_settings_splitter_moved(self, _pos: int, _index: int) -> None:
        """Remember the user's preferred tray height while they drag the splitter."""
        if not self._settings_panel_is_visible():
            return
        current_height = self._settings_panel_current_height()
        if current_height > 24:
            min_height = int(self.settings_panel.minimumHeight()) if hasattr(self, "settings_panel") else 140
            self._settings_panel_last_height = max(current_height, min_height)
        if not getattr(self, "_settings_splitter_drag_active", False):
            self._refresh_settings_affordances()

    def _update_settings_splitter_rubber_band(self, global_pos) -> None:
        """Show a lightweight preview line for the tray height while dragging the splitter."""
        splitter = getattr(self, "plot_settings_splitter", None)
        if splitter is None or not self._settings_panel_is_visible():
            return
        with contextlib.suppress(Exception):
            point = global_pos.toPoint() if hasattr(global_pos, "toPoint") else global_pos
            local = splitter.mapFromGlobal(point)
            pos = int(local.y()) if splitter.orientation() == Qt.Vertical else int(local.x())
            splitter.setRubberBand(pos)

    def _set_settings_panel_visible(self, visible: bool) -> None:
        """Show or hide the bottom settings tray and keep the toggle button in sync."""
        # Tray show/hide only changes layout; do not re-capture the expensive
        # scroll-preview pixmap during this transition (scroll itself refetches
        # it on demand). This removes a full-canvas rasterization from the Tab
        # hotkey path and makes the tray feel instant.
        self._skip_layout_preview_refresh = True
        splitter = getattr(self, "plot_settings_splitter", None)
        panel = getattr(self, "settings_panel", None)
        if splitter is not None and panel is not None:
            sizes = splitter.sizes()
            total = int(sum(sizes)) if isinstance(sizes, list) and sizes else int(max(splitter.height(), 1))
            total = max(total, int(max(splitter.height(), 1)))
            min_tray = int(max(getattr(self, "_settings_panel_min_height", 140), 0))
            if visible:
                with contextlib.suppress(Exception):
                    panel.setMaximumHeight(16777215)
                with contextlib.suppress(Exception):
                    panel.setMinimumHeight(min_tray)
                panel.show()
                splitter.setHandleWidth(int(max(getattr(self, "_settings_splitter_visible_handle_width", 6), 0)))
                desired = int(max(getattr(self, "_settings_panel_last_height", min_tray), min_tray))
                max_allowed = max(total - 140, min_tray)
                tray_height = min(desired, max_allowed)
                main_height = max(total - tray_height, 140)
                splitter.setSizes([main_height, tray_height])
            else:
                current_height = self._settings_panel_current_height()
                if current_height > 24:
                    self._settings_panel_last_height = max(current_height, min_tray)
                panel.hide()
                with contextlib.suppress(Exception):
                    panel.setMinimumHeight(0)
                with contextlib.suppress(Exception):
                    panel.setMaximumHeight(0)
                splitter.setHandleWidth(0)
                splitter.setSizes([max(total, 1), 0])
                self._settings_splitter_drag_active = False
                with contextlib.suppress(Exception):
                    splitter.setRubberBand(-1)
        toggle_btn = getattr(self, "settings_toggle_btn", None)
        if isinstance(toggle_btn, QPushButton):
            was = toggle_btn.blockSignals(True)
            is_visible = self._settings_panel_is_visible()
            toggle_btn.setChecked(is_visible)
            toggle_btn.setText("Hide [Tab]" if is_visible else "Settings [Tab]")
            toggle_btn.blockSignals(was)
        self._refresh_settings_affordances()
        if not bool(getattr(self, "_suspend_layout_refresh", False)):
            if self._settings_panel_is_visible():
                QTimer.singleShot(0, self._scroll_current_control_tab_to_top)
            QTimer.singleShot(0, self._refresh_plot_view_after_layout_change)
            QTimer.singleShot(0, self.bottom_panel.update)

    def _refresh_plot_view_after_layout_change(self) -> None:
        """Refresh the viewport cheaply after tray layout changes and rebuild blit caches lazily."""
        if not hasattr(self, "canvas"):
            return
        skip_preview = bool(getattr(self, "_skip_layout_preview_refresh", False))
        self._skip_layout_preview_refresh = False
        if not skip_preview:
            # Window actually resized (not a Tab tray toggle): follow the viewport.
            # Tab toggles must NOT resize the canvas: doing so re-lays-out and
            # re-scales every subplot, which is the visible "plots re-zoom" stutter.
            self._sync_plot_canvas_host_size()
        self._apply_deferred_restored_plot_scroll_state()
        with contextlib.suppress(Exception):
            self.plot_settings_splitter.updateGeometry()
        with contextlib.suppress(Exception):
            self.plot_panel.updateGeometry()
        with contextlib.suppress(Exception):
            self.bottom_panel.updateGeometry()
        with contextlib.suppress(Exception):
            refresh_timer = getattr(self, "_layout_refresh_timer", None)
            if refresh_timer is not None:
                refresh_timer.start()
        if skip_preview:
            # Tray toggled: keep the canvas geometry untouched; just refresh the
            # Qt panes so the tray appears instantly without any matplotlib
            # re-scaling of the plots.
            with contextlib.suppress(Exception):
                self._layout_refresh_timer.stop()
            with contextlib.suppress(Exception):
                self.plot_scroll.viewport().update()
            return
        with contextlib.suppress(Exception):
            self.plot_settings_splitter.update()
        with contextlib.suppress(Exception):
            self.plot_panel.update()
        with contextlib.suppress(Exception):
            self.bottom_panel.update()
        with contextlib.suppress(Exception):
            self.plot_scroll.viewport().update()

    def _finalize_plot_view_after_layout_change(self) -> None:
        """Finish tray/layout changes without forcing an unnecessary Matplotlib redraw."""
        if not hasattr(self, "canvas"):
            return
        if bool(getattr(self, "_skip_layout_preview_refresh", False)):
            self._skip_layout_preview_refresh = False
            with contextlib.suppress(Exception):
                self.plot_settings_splitter.update()
            with contextlib.suppress(Exception):
                self.plot_panel.update()
            with contextlib.suppress(Exception):
                self.bottom_panel.update()
            return
        self._sync_plot_canvas_host_size()
        self._apply_deferred_restored_plot_scroll_state()
        with contextlib.suppress(Exception):
            self.plot_settings_splitter.updateGeometry()
        with contextlib.suppress(Exception):
            self.plot_panel.updateGeometry()
        with contextlib.suppress(Exception):
            self.bottom_panel.updateGeometry()
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            pass
        else:
            with contextlib.suppress(Exception):
                self._refresh_plot_scroll_preview_cache()
        with contextlib.suppress(Exception):
            self.plot_settings_splitter.update()
        with contextlib.suppress(Exception):
            self.plot_panel.update()
        with contextlib.suppress(Exception):
            self.bottom_panel.update()

    def _toggle_settings_panel_from_button(self, checked: bool) -> None:
        """Respond to the top-bar settings toggle button."""
        self._set_settings_panel_visible(bool(checked))

    def _toggle_settings_panel_from_shortcut(self) -> None:
        """Toggle the settings tray from the keyboard while preserving the active control tab."""
        self._set_settings_panel_visible(not self._settings_panel_is_visible())

    def _select_control_tab(self, tab_name: str, show_panel: bool = True) -> None:
        """Switch the visible control tab if the requested tab exists."""
        tabs = getattr(self, "control_tabs", None)
        if tabs is None:
            return
        alias_map = getattr(self, "control_tab_aliases", {})
        tab_name = alias_map.get(str(tab_name), str(tab_name))
        index_map = getattr(self, "control_tab_indices", {})
        idx = index_map.get(str(tab_name), -1)
        if isinstance(idx, int) and 0 <= idx < tabs.count():
            changed = tabs.currentIndex() != idx
            if tabs.currentIndex() != idx:
                tabs.setCurrentIndex(idx)
            else:
                self._refresh_settings_affordances()
            if changed:
                QTimer.singleShot(0, self._scroll_current_control_tab_to_top)
            if show_panel:
                self._set_settings_panel_visible(True)

    def _control_tab_name_for_axes(self, ax) -> str | None:
        """Map a matplotlib subplot axis to its matching control tab."""
        if ax is self.ax_hist_ion:
            return "Ion Histogram"
        if ax is self.ax_ion_tof_xy:
            return "Ion Coincidence"
        if ax is self.ax_scatter_e:
            return "Electron Scatter"
        if ax is self.ax_scatter_i:
            return "Ion Scatter"
        if ax in (self.ax_centered_bin, self.ax_centered_theta_profile):
            return "Electron Binned Image"
        if ax in (self.ax_reserved_top, self.ax_rbasex_profile):
            return "Reconstruction"
        return None

    def _switch_control_tab_for_axes(self, ax, show_panel: bool = False) -> None:
        """Make subplot clicks select the matching control tab, optionally showing the tray."""
        if not bool(getattr(self, "_subplot_click_focus_enabled", False)):
            return
        tab_name = self._control_tab_name_for_axes(ax)
        if tab_name:
            self._select_control_tab(tab_name, show_panel=show_panel)

    def _install_global_wheel_scroll_filter(self) -> None:
        """Route wheel scrolling to control/plot scroll areas without requiring slider focus."""
        app = QApplication.instance()
        if app is not None:
            with contextlib.suppress(Exception):
                app.installEventFilter(self)

    @staticmethod
    def _is_descendant_object(child, parent) -> bool:
        """Return whether `child` is the same object as `parent` or nested under it."""
        obj = child
        while obj is not None:
            if obj is parent:
                return True
            with contextlib.suppress(Exception):
                obj = obj.parent()
                continue
            break
        return False

    def _focus_widget_is_plot_region(self, widget) -> bool:
        """Return whether the focused widget belongs to the plot area rather than the settings tray."""
        if widget is None:
            return False
        if widget in (
            getattr(self, "canvas", None),
            getattr(self, "toolbar", None),
            getattr(self, "plot_scroll", None),
            getattr(getattr(self, "plot_scroll", None), "viewport", lambda: None)(),
        ):
            return True
        return self._is_descendant_object(widget, getattr(self, "plot_panel", None)) or self._is_descendant_object(
            widget,
            getattr(self, "plot_scroll", None),
        )

    def _object_is_in_plot_region(self, obj) -> bool:
        """Return whether a Qt object belongs to the main plot viewport/tooling region."""
        plot_scroll = getattr(self, "plot_scroll", None)
        plot_viewport = getattr(plot_scroll, "viewport", lambda: None)()
        plot_canvas = getattr(self, "canvas", None)
        plot_toolbar = getattr(self, "toolbar", None)
        plot_host = getattr(self, "plot_canvas_host", None)
        plot_preview = getattr(self, "plot_scroll_preview_label", None)
        return bool(
            obj in (plot_scroll, plot_viewport, plot_canvas, plot_toolbar, plot_host, plot_preview)
            or self._is_descendant_object(obj, plot_scroll)
            or self._is_descendant_object(obj, plot_canvas)
            or self._is_descendant_object(obj, plot_toolbar)
            or self._is_descendant_object(obj, plot_host)
            or self._is_descendant_object(obj, plot_preview)
        )

    def _object_is_in_plot_canvas_region(self, obj) -> bool:
        """Return whether a Qt object belongs to the scrollable plot canvas region (not the toolbar)."""
        plot_scroll = getattr(self, "plot_scroll", None)
        plot_viewport = getattr(plot_scroll, "viewport", lambda: None)()
        plot_canvas = getattr(self, "canvas", None)
        plot_host = getattr(self, "plot_canvas_host", None)
        plot_preview = getattr(self, "plot_scroll_preview_label", None)
        return bool(
            obj in (plot_scroll, plot_viewport, plot_canvas, plot_host, plot_preview)
            or self._is_descendant_object(obj, plot_scroll)
            or self._is_descendant_object(obj, plot_canvas)
            or self._is_descendant_object(obj, plot_host)
            or self._is_descendant_object(obj, plot_preview)
        )

    def _dispatch_mouse_event_to_plot_canvas(self, payload: dict[str, object]) -> bool:
        """Send one queued mouse event payload to the live matplotlib canvas."""
        canvas = getattr(self, "canvas", None)
        if canvas is None or not isinstance(payload, dict):
            return False
        event_type = payload.get("type")
        local_pos = payload.get("local_pos")
        global_pos = payload.get("global_pos")
        if event_type is None or local_pos is None or global_pos is None:
            return False
        if not canvas.rect().contains(local_pos):
            return False
        clone = QMouseEvent(
            event_type,
            QPointF(local_pos),
            QPointF(global_pos),
            payload.get("button", Qt.NoButton),
            payload.get("buttons", Qt.NoButton),
            payload.get("modifiers", Qt.NoModifier),
        )
        QApplication.sendEvent(canvas, clone)
        return True

    def _queue_mouse_event_for_plot_canvas(self, event, source_obj) -> bool:
        """Queue one mouse event from the preview layer to replay on the live canvas."""
        canvas = getattr(self, "canvas", None)
        if canvas is None or event is None:
            return False
        global_pos = None
        with contextlib.suppress(Exception):
            global_pos = event.globalPosition().toPoint()
        if global_pos is None and source_obj is not None and hasattr(source_obj, "mapToGlobal"):
            with contextlib.suppress(Exception):
                global_pos = source_obj.mapToGlobal(event.position().toPoint())
        if global_pos is None:
            return False
        local_pos = canvas.mapFromGlobal(global_pos)
        if not canvas.rect().contains(local_pos):
            return False
        payload = {
            "type": event.type(),
            "local_pos": local_pos,
            "global_pos": global_pos,
            "button": getattr(event, "button", lambda: Qt.NoButton)(),
            "buttons": getattr(event, "buttons", lambda: Qt.NoButton)(),
            "modifiers": getattr(event, "modifiers", lambda: Qt.NoModifier)(),
        }
        QTimer.singleShot(0, lambda data=payload: self._dispatch_mouse_event_to_plot_canvas(data))
        return True

    @staticmethod
    def _apply_wheel_to_scroll_area(scroll_area: QScrollArea, event, prefer_horizontal: bool) -> bool:
        """Scroll one QScrollArea using wheel deltas; Shift prefers horizontal."""
        if scroll_area is None or event is None:
            return False
        delta = event.angleDelta()
        dx = int(delta.x())
        dy = int(delta.y())
        want_h = bool(prefer_horizontal)
        bar_primary = scroll_area.horizontalScrollBar() if want_h else scroll_area.verticalScrollBar()
        bar_fallback = scroll_area.verticalScrollBar() if want_h else scroll_area.horizontalScrollBar()

        def _usable(bar) -> bool:
            return bool(bar is not None and bar.maximum() > bar.minimum())

        if want_h and (not _usable(bar_primary)):
            return False
        if _usable(bar_primary):
            bar = bar_primary
        elif _usable(bar_fallback):
            bar = bar_fallback
        else:
            return False

        if bar.orientation() == Qt.Horizontal:
            # Most mouse wheels report vertical delta only; allow Shift+wheel to drive horizontal scroll.
            d = dx if dx != 0 else dy
        else:
            d = dy if dy != 0 else dx

        if d == 0:
            p = event.pixelDelta()
            px = int(p.x())
            py = int(p.y())
            if bar.orientation() == Qt.Horizontal:
                d = px if px != 0 else py
            else:
                d = py if py != 0 else px
        if d == 0:
            return False
        step = int(max(24, bar.singleStep(), bar.pageStep() // 8))
        # 120 wheel units ~= one notch.
        ticks = float(d) / 120.0
        delta_value = int(np.rint(ticks * step))
        if delta_value == 0:
            delta_value = 1 if d > 0 else -1
        owner = scroll_area.window()
        if owner is not None and hasattr(owner, "_queue_wheel_scroll_bar"):
            with contextlib.suppress(Exception):
                owner._queue_wheel_scroll_bar(bar, delta_value, scroll_area=scroll_area)
                return True
        bar.setValue(int(bar.value() - delta_value))
        return True

    def _queue_wheel_scroll_bar(self, bar, delta_value: int, scroll_area: QScrollArea | None = None) -> None:
        """Accumulate wheel-scroll steps and apply them once per short timer tick."""
        if bar is None:
            return
        key = id(bar)
        if scroll_area is getattr(self, "plot_scroll", None):
            pending = getattr(self, "_pending_wheel_scroll_steps", {})
            if isinstance(pending, dict) and key in pending:
                pending.pop(key, None)
            timer = getattr(self, "_wheel_scroll_timer", None)
            if timer is not None and (not pending):
                with contextlib.suppress(Exception):
                    timer.stop()
            self._begin_plot_scroll_burst()
            try:
                current = int(bar.value())
                minimum = int(bar.minimum())
                maximum = int(bar.maximum())
                target = int(np.clip(current - int(delta_value), minimum, maximum))
                if target != current:
                    bar.setValue(target)
            except Exception:
                pass
            return
        prev_bar, prev_delta = self._pending_wheel_scroll_steps.get(key, (bar, 0))
        total_delta = int(prev_delta) + int(delta_value)
        self._pending_wheel_scroll_steps[key] = (prev_bar, total_delta)
        timer = getattr(self, "_wheel_scroll_timer", None)
        if timer is not None:
            timer.start()
        else:
            self._flush_pending_wheel_scrolls()

    def _flush_pending_wheel_scrolls(self) -> None:
        """Apply coalesced wheel-scroll updates to their target scroll bars."""
        pending = dict(getattr(self, "_pending_wheel_scroll_steps", {}))
        self._pending_wheel_scroll_steps = {}
        for bar, delta_value in pending.values():
            try:
                current = int(bar.value())
                minimum = int(bar.minimum())
                maximum = int(bar.maximum())
                target = int(np.clip(current - int(delta_value), minimum, maximum))
                if target != current:
                    bar.setValue(target)
            except Exception:
                continue

    @staticmethod
    def _is_modifier_key_event(event) -> bool:
        """Return whether a Qt key event is specifically a modifier-key transition."""
        if event is None:
            return False
        with contextlib.suppress(Exception):
            return int(event.key()) in {
                int(Qt.Key_Control),
                int(Qt.Key_Shift),
                int(Qt.Key_Alt),
                int(Qt.Key_Meta),
            }
        return False

    def eventFilter(self, obj, event):  # noqa: N802 (Qt override)
        """Global wheel routing for scroll areas so scrolling works without grabbing sliders."""
        splitter_handle = getattr(self, "_settings_splitter_handle", None)
        if splitter_handle is not None and obj is splitter_handle and event is not None:
            if event.type() == QEvent.Type.MouseButtonPress:
                self._set_settings_splitter_drag_active(True)
                with contextlib.suppress(Exception):
                    self._update_settings_splitter_rubber_band(event.globalPosition())
            elif event.type() == QEvent.Type.MouseMove and getattr(self, "_settings_splitter_drag_active", False):
                with contextlib.suppress(Exception):
                    self._update_settings_splitter_rubber_band(event.globalPosition())
            elif event.type() in (QEvent.Type.MouseButtonRelease, QEvent.Type.Leave):
                with contextlib.suppress(Exception):
                    self.plot_settings_splitter.setRubberBand(-1)
                self._set_settings_splitter_drag_active(False)
        if event is not None and event.type() in (QEvent.Type.ApplicationDeactivate, QEvent.Type.WindowDeactivate):
            with contextlib.suppress(Exception):
                self._force_toolbar_idle()
        if event is not None and event.type() in (
            QEvent.Type.ApplicationActivate,
            QEvent.Type.WindowActivate,
            QEvent.Type.FocusIn,
            QEvent.Type.Enter,
        ):
            in_plot_context = bool(
                obj in (self, getattr(self, "canvas", None), getattr(self, "toolbar", None))
                or self._object_is_in_plot_region(obj)
            )
            if in_plot_context:
                with contextlib.suppress(Exception):
                    self._schedule_toolbar_interaction_sync()
        if event is not None and event.type() == QEvent.Type.KeyPress:
            if (
                event.key() == Qt.Key_Tab
                and not event.isAutoRepeat()
                and event.modifiers() == Qt.NoModifier
                and QApplication.activePopupWidget() is None
            ):
                focus_widget = QApplication.focusWidget()
                if self._focus_widget_is_plot_region(focus_widget):
                    self._toggle_settings_panel_from_shortcut()
                    return True
        if event is not None and bool(getattr(self, "_plot_scroll_preview_active", False)):
            if event.type() == QEvent.Type.MouseMove:
                try:
                    buttons = event.buttons()
                except Exception:
                    buttons = Qt.NoButton
                quiet_s = max(float(PLOT_SCROLL_PREVIEW_MOUSE_RESTORE_GRACE_MS), 0.0) / 1000.0
                last_wheel_ts = float(getattr(self, "_plot_scroll_preview_last_wheel_ts", 0.0))
                if buttons == Qt.NoButton and (time.monotonic() - last_wheel_ts) >= quiet_s:
                    with contextlib.suppress(Exception):
                        self._end_plot_scroll_burst()
            elif event.type() in (
                QEvent.Type.MouseButtonPress,
                QEvent.Type.MouseButtonRelease,
                QEvent.Type.MouseButtonDblClick,
            ) and self._object_is_in_plot_canvas_region(obj):
                forwarded = False
                with contextlib.suppress(Exception):
                    forwarded = self._queue_mouse_event_for_plot_canvas(event, obj)
                with contextlib.suppress(Exception):
                    self._end_plot_scroll_burst()
                if forwarded:
                    return True
            elif event.type() == QEvent.Type.MouseButtonPress:
                if self._object_is_in_plot_region(obj):
                    self._schedule_end_plot_scroll_burst()
            elif event.type() == QEvent.Type.KeyPress and (not self._is_modifier_key_event(event)):
                focus_widget = QApplication.focusWidget()
                if self._focus_widget_is_plot_region(focus_widget):
                    self._schedule_end_plot_scroll_burst()
        if event is not None and event.type() in (QEvent.Type.KeyPress, QEvent.Type.KeyRelease) and self._is_modifier_key_event(event):
            with contextlib.suppress(Exception):
                self._sync_ion_hist_modifier_guard(event.modifiers())
                self._update_ion_hist_span_selector_state()
        if event is not None and event.type() in (QEvent.Type.MouseButtonPress, QEvent.Type.MouseButtonRelease):
            with contextlib.suppress(Exception):
                if event.type() == QEvent.Type.MouseButtonPress:
                    mods = event.modifiers()
                else:
                    mods = QApplication.keyboardModifiers()
                needs_guard_sync = bool(mods & (Qt.ControlModifier | Qt.ShiftModifier))
                needs_guard_sync = needs_guard_sync or bool(getattr(self, "_ion_hist_modifier_guard_active", False))
                needs_guard_sync = needs_guard_sync or bool(getattr(self, "_ion_hist_span_pause_until_release", False))
                if needs_guard_sync:
                    self._sync_ion_hist_modifier_guard(mods)
                if needs_guard_sync or self._toolbar_mode_active():
                    self._update_ion_hist_span_selector_state()
        if event is not None and event.type() == QEvent.Type.Wheel:
            if QApplication.activePopupWidget() is not None:
                return super().eventFilter(obj, event)
            prefer_horizontal = bool(event.modifiers() & Qt.ShiftModifier)
            control_scroll = self._current_control_scroll_area()
            plot_scroll = getattr(self, "plot_scroll", None)

            in_control_region = self._is_descendant_object(obj, control_scroll) or self._is_descendant_object(
                obj,
                getattr(self, "settings_panel", None),
            )
            if in_control_region:
                if self._apply_wheel_to_scroll_area(control_scroll, event, prefer_horizontal):
                    return True

            in_plot_region = self._object_is_in_plot_region(obj)
            if in_plot_region:
                if self._apply_wheel_to_scroll_area(plot_scroll, event, prefer_horizontal):
                    return True
        return super().eventFilter(obj, event)

    def _wire_toolbar_navigation_hooks(self) -> None:
        """Hook Home/Back/Forward to keep ion-hist view consistent with coarse ROI."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return
        actions = getattr(tb, "_actions", {})
        if not isinstance(actions, dict):
            return
        for key in ("home", "back", "forward"):
            action = actions.get(key)
            if action is None:
                continue
            with contextlib.suppress(Exception):
                action.triggered.connect(lambda _checked=False, kind=key: self._on_toolbar_nav_action(kind))
        for key in ("pan", "zoom"):
            action = actions.get(key)
            if action is None:
                continue
            with contextlib.suppress(Exception):
                action.toggled.connect(lambda _checked=False: self._schedule_toolbar_interaction_sync())
            with contextlib.suppress(Exception):
                action.triggered.connect(lambda _checked=False: self._schedule_toolbar_interaction_sync())
        self._schedule_toolbar_interaction_sync()

    def _on_toolbar_nav_action(self, kind: str) -> None:
        """Post-process toolbar nav action so custom overlays follow restored views."""
        QTimer.singleShot(0, lambda nav_kind=kind: self._postprocess_toolbar_navigation(nav_kind))

    def _postprocess_toolbar_navigation(self, kind: str | None = None) -> None:
        """After toolbar Home/Back/Forward, redraw custom overlays on the restored view."""
        nav_kind = str(kind).lower() if isinstance(kind, str) else ""
        if not self._has_restorable_plot_state():
            self._draw_placeholder()
            if nav_kind == "home":
                self._reset_ion_hist_navigation_history()
            return
        self._enforce_ion_hist_coarse_roi_after_nav(kind)
        with contextlib.suppress(Exception):
            self._draw_canvas_without_overlay_draw_event_sync()
        self._axis_last_blit_extents = {}
        self._capture_blit_background_from_current_canvas()
        self._update_circle_overlay_only(enforce_axis=False, fast_drag=True)
        self._update_ion_overlay_only(enforce_axis=False, fast_drag=True)
        if nav_kind == "home":
            self._reset_ion_hist_navigation_history()

    def _sync_toolbar_current_view_for_axis(self, ax) -> None:
        """Overwrite the current toolbar-history entry for one axes after manual limit edits."""
        tb = getattr(self, "toolbar", None)
        if tb is None or ax is None:
            return
        nav_stack = getattr(tb, "_nav_stack", None)
        if nav_stack is None or not callable(nav_stack):
            return
        current = nav_stack()
        if current is None:
            return
        with contextlib.suppress(Exception):
            current[ax] = (
                ax._get_view(),
                (
                    ax.get_position(True).frozen(),
                    ax.get_position().frozen(),
                ),
            )
            tb.set_history_buttons()

    def _sync_toolbar_current_view_for_figure(self) -> None:
        """Overwrite the current toolbar-history entry with the figure's current axes/layout state."""
        tb = getattr(self, "toolbar", None)
        if tb is None or not hasattr(self, "figure"):
            return
        nav_stack = getattr(tb, "_nav_stack", None)
        if nav_stack is None or not callable(nav_stack):
            return
        current = nav_stack()
        if current is None:
            return
        with contextlib.suppress(Exception):
            if hasattr(current, "clear"):
                current.clear()
            for ax in list(getattr(self.figure, "axes", [])):
                if ax is None:
                    continue
                current[ax] = (
                    ax._get_view(),
                    (
                        ax.get_position(True).frozen(),
                        ax.get_position().frozen(),
                    ),
                )
            tb.set_history_buttons()

    @staticmethod
    def _capture_axis_view_state(ax) -> tuple[float, float, float, float] | None:
        """Capture one axis view as `(x0, x1, y0, y1)` when valid."""
        if ax is None:
            return None
        try:
            x0, x1 = ax.get_xlim()
            y0, y1 = ax.get_ylim()
        except Exception:
            return None
        vals = np.array([x0, x1, y0, y1], dtype=np.float64)
        if (not np.isfinite(vals).all()) or abs(float(x1) - float(x0)) <= 1e-12 or abs(float(y1) - float(y0)) <= 1e-12:
            return None
        return float(x0), float(x1), float(y0), float(y1)

    def _restore_axis_view_state(self, ax, view: tuple[float, float, float, float] | None, *, keep_square: bool) -> bool:
        """Restore one axis view from `_capture_axis_view_state` output."""
        if ax is None or view is None:
            return False
        try:
            x0, x1, y0, y1 = [float(v) for v in view]
        except Exception:
            return False
        vals = np.array([x0, x1, y0, y1], dtype=np.float64)
        if (not np.isfinite(vals).all()) or abs(x1 - x0) <= 1e-12 or abs(y1 - y0) <= 1e-12:
            return False
        try:
            ax.set_xlim(x0, x1, auto=False)
            ax.set_ylim(y0, y1, auto=False)
            if keep_square:
                self._lock_equal_xy_limits(ax)
            else:
                ax.set_autoscalex_on(False)
                ax.set_autoscaley_on(False)
            self._sync_toolbar_current_view_for_axis(ax)
            return True
        except Exception:
            return False

    def _restore_axis_view_state_clamped(self, ax, view: tuple[float, float, float, float] | None, *, keep_square: bool) -> bool:
        """Restore one axis view while clamping it to the axis' current finite bounds."""
        if ax is None or view is None:
            return False
        current = self._capture_axis_view_state(ax)
        if current is None:
            return False
        try:
            vx0, vx1, vy0, vy1 = [float(v) for v in view]
            cx0, cx1, cy0, cy1 = [float(v) for v in current]
        except Exception:
            return False

        def clamp_pair(v0: float, v1: float, b0: float, b1: float) -> tuple[float, float] | None:
            rev = bool(v1 < v0)
            lo = max(min(v0, v1), min(b0, b1))
            hi = min(max(v0, v1), max(b0, b1))
            if (not np.isfinite([lo, hi]).all()) or abs(hi - lo) <= 1e-12:
                return None
            return (hi, lo) if rev else (lo, hi)

        x_pair = clamp_pair(vx0, vx1, cx0, cx1)
        y_pair = clamp_pair(vy0, vy1, cy0, cy1)
        if x_pair is None or y_pair is None:
            return False
        return self._restore_axis_view_state(ax, (x_pair[0], x_pair[1], y_pair[0], y_pair[1]), keep_square=keep_square)

    def _ensure_ion_hist_log_ylim_consistent(self) -> bool:
        """Ensure ion-hist y-limits stay valid when axis scale is log."""
        if str(self.ax_hist_ion.get_yscale()) != "log":
            return False
        y0, y1 = self.ax_hist_ion.get_ylim()
        if np.isfinite([y0, y1]).all() and float(y0) > 0.0 and float(y1) > float(y0):
            return False
        counts = self._ion_hist_counts_for_display(self._ion_hist_cache_counts)
        pos = counts[np.isfinite(counts) & (counts > 0.0)]
        if pos.size > 0:
            ymin = max(1e-3, float(np.min(pos)) * 0.8)
            ymax = max(float(np.max(pos)) * 1.15, ymin * 10.0)
        else:
            ymin, ymax = 0.8, 1.2
        self.ax_hist_ion.set_ylim(float(ymin), float(ymax), auto=False)
        return True

    def _enforce_ion_hist_coarse_roi_after_nav(self, kind: str | None = None) -> None:
        """After Home/Back/Forward, enforce ROI-bounded x-limits and valid log y-limits."""
        changed = False
        if self.ion_hist_x_roi is not None:
            mode, ref = self._ion_axis_mode_and_ref(show_dialog=False, strict=False)
            roi_x = self._ion_time_range_to_axis_range(self.ion_hist_x_roi, mode, ref)
            if roi_x is None:
                roi_x = (float(self.ion_hist_x_roi[0]), float(self.ion_hist_x_roi[1]))
            lo = float(min(roi_x[0], roi_x[1]))
            hi = float(max(roi_x[0], roi_x[1]))
            if np.isfinite([lo, hi]).all() and abs(hi - lo) > 1e-12:
                x0, x1 = self.ax_hist_ion.get_xlim()
                if not np.isfinite([x0, x1]).all():
                    self.ax_hist_ion.set_xlim(lo, hi, auto=False)
                    changed = True
                else:
                    left = float(min(x0, x1))
                    right = float(max(x0, x1))
                    if isinstance(kind, str) and kind.lower() == "home":
                        if (abs(left - lo) > 1e-10) or (abs(right - hi) > 1e-10):
                            self.ax_hist_ion.set_xlim(lo, hi, auto=False)
                            changed = True
                    else:
                        clamped_left = max(left, lo)
                        clamped_right = min(right, hi)
                        if (clamped_right - clamped_left) <= 1e-12:
                            clamped_left, clamped_right = lo, hi
                        if (abs(clamped_left - left) > 1e-10) or (abs(clamped_right - right) > 1e-10):
                            self.ax_hist_ion.set_xlim(clamped_left, clamped_right, auto=False)
                            changed = True
        if self._ensure_ion_hist_log_ylim_consistent():
            changed = True
        if changed:
            self._sync_toolbar_current_view_for_axis(self.ax_hist_ion)
            self.canvas.draw_idle()

    def _configure_plot_canvas_size(self) -> None:
        """Size the plot canvas without forcing an oversized main-window minimum."""
        dpi = float(self.figure.get_dpi())
        scale = float(PLOT_CANVAS_DISPLAY_SCALE)
        preferred_w = max(int(round(self.figure.get_figwidth() * dpi * scale)), 1480)
        preferred_h = max(int(round(self.figure.get_figheight() * dpi * scale)), 700)
        self.canvas.resize(preferred_w, preferred_h)

        min_w = 1080
        min_h = 500
        screen = QApplication.primaryScreen()
        if screen is not None:
            geom = screen.availableGeometry()
            min_w = min(min_w, max(760, int(geom.width()) - 260))
            min_h = min(min_h, max(400, int(geom.height()) - 300))
        self.canvas.setMinimumSize(max(min_w, 1), max(min_h, 1))
        self._sync_plot_canvas_host_size()

    def _sync_plot_canvas_host_size(self) -> None:
        """Keep the scroll host/preview exactly aligned to the live matplotlib canvas size.

        The canvas follows the plot-scroll viewport, so full-screen and normal
        windows show identical subplot content (no fixed-size canvas + scrollbar
        cropping that made full-screen look different).
        """
        host = getattr(self, "plot_canvas_host", None)
        preview = getattr(self, "plot_scroll_preview_label", None)
        if host is None or preview is None or not hasattr(self, "canvas"):
            return
        # Canvas keeps a stable working size so subplot geometry never
        # re-lays-out when the settings tray toggles or the window resizes.
        # Only an explicit _configure_plot_canvas_size() (window-mode change)
        # re-targets the canvas; tray toggles and scrolls leave it untouched.
        size = self.canvas.size()
        width = max(int(size.width()), int(self.canvas.minimumWidth()), 1)
        height = max(int(size.height()), int(self.canvas.minimumHeight()), 1)
        host.resize(width, height)
        host.setMinimumSize(width, height)
        preview.resize(width, height)
        preview.setMinimumSize(width, height)
        cached = getattr(self, "_plot_scroll_preview_pixmap", QPixmap())
        cached_width = 0
        cached_height = 0
        if not cached.isNull():
            try:
                logical = cached.deviceIndependentSize()
                cached_width = int(round(float(logical.width())))
                cached_height = int(round(float(logical.height())))
            except Exception:
                cached_width = int(cached.width())
                cached_height = int(cached.height())
        if (not cached.isNull()) and (cached_width != width or cached_height != height):
            self._plot_scroll_preview_pixmap = QPixmap()

    def _normalize_plot_scroll_preview_pixmap(self, pixmap: QPixmap | None) -> QPixmap:
        """Force one cached scroll-preview pixmap to match the canvas logical size."""
        """Force one cached scroll-preview pixmap to match the canvas logical size."""
        if pixmap is None or pixmap.isNull():
            return QPixmap()
        canvas = getattr(self, "canvas", None)
        if canvas is None:
            return QPixmap(pixmap)
        logical_w = max(int(canvas.width()), int(canvas.minimumWidth()), 1)
        logical_h = max(int(canvas.height()), int(canvas.minimumHeight()), 1)
        image = pixmap.toImage()
        if image.isNull():
            out = QPixmap(pixmap)
        else:
            if int(image.width()) != logical_w or int(image.height()) != logical_h:
                image = image.scaled(logical_w, logical_h, Qt.IgnoreAspectRatio, Qt.FastTransformation)
            out = QPixmap.fromImage(image)
        with contextlib.suppress(Exception):
            out.setDevicePixelRatio(1.0)
        return out

    def _capture_plot_scroll_preview_pixmap(self) -> QPixmap:
        """Build the scroll-preview pixmap from the Agg canvas buffer when possible."""
        canvas = getattr(self, "canvas", None)
        if canvas is None:
            return QPixmap()
        self._sync_plot_canvas_host_size()
        try:
            rgba = np.asarray(canvas.buffer_rgba(), dtype=np.uint8)
            if rgba.ndim == 3 and rgba.shape[2] >= 4:
                height = int(rgba.shape[0])
                width = int(rgba.shape[1])
                stride = int(rgba.strides[0])
                image = QImage(rgba.data, width, height, stride, QImage.Format.Format_RGBA8888).copy()
                logical_w = max(int(canvas.width()), 1)
                logical_h = max(int(canvas.height()), 1)
                if int(image.width()) != logical_w or int(image.height()) != logical_h:
                    image = image.scaled(logical_w, logical_h, Qt.IgnoreAspectRatio, Qt.FastTransformation)
                pixmap = QPixmap.fromImage(image)
                with contextlib.suppress(Exception):
                    pixmap.setDevicePixelRatio(1.0)
                pixmap = self._normalize_plot_scroll_preview_pixmap(pixmap)
                if not pixmap.isNull():
                    return pixmap
        except Exception:
            pass
        try:
            return self._normalize_plot_scroll_preview_pixmap(canvas.grab())
        except Exception:
            return QPixmap()

    def _on_canvas_draw_event(self, _event) -> None:
        """Refresh the cached scroll-preview pixmap shortly after a real canvas draw."""
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            return
        if bool(getattr(self, "_suspend_overlay_draw_event_sync", False)):
            return
        timer = getattr(self, "_plot_scroll_preview_capture_timer", None)
        if timer is not None:
            timer.start()
        with contextlib.suppress(Exception):
            self._capture_blit_background_from_current_canvas()
        if not self._use_safe_circle_overlay_redraw():
            with contextlib.suppress(Exception):
                self._update_circle_overlay_only(enforce_axis=False, fast_drag=True)
        if not self._use_safe_ion_overlay_redraw():
            with contextlib.suppress(Exception):
                self._update_ion_overlay_only(enforce_axis=False, fast_drag=True)

    def _refresh_plot_scroll_preview_cache(self) -> None:
        """Capture a cached pixmap for fast plot scrolling without blocking the wheel path."""
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            return
        pixmap = self._capture_plot_scroll_preview_pixmap()
        if not pixmap.isNull():
            self._plot_scroll_preview_pixmap = pixmap

    def _mark_plot_scroll_preview_cache_dirty(self, *, refresh_soon: bool = True) -> None:
        """Invalidate the scroll-preview snapshot after canvas content changes."""
        self._plot_scroll_preview_pixmap = QPixmap()
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            return
        if not refresh_soon:
            return
        timer = getattr(self, "_plot_scroll_preview_capture_timer", None)
        if timer is not None:
            with contextlib.suppress(Exception):
                timer.start()

    def _begin_plot_scroll_burst(self) -> None:
        """Overlay a cached canvas snapshot so wheel bursts scroll a cheap pixmap."""
        label = getattr(self, "plot_scroll_preview_label", None)
        canvas = getattr(self, "canvas", None)
        stack = getattr(self, "plot_canvas_stack", None)
        timer = getattr(self, "_plot_scroll_preview_idle_timer", None)
        if label is None or canvas is None or stack is None:
            return
        self._plot_scroll_preview_last_wheel_ts = time.monotonic()
        self._plot_scroll_preview_restore_queued = False
        if timer is not None:
            with contextlib.suppress(Exception):
                timer.stop()
                timer.start()
        self._sync_plot_canvas_host_size()
        if not bool(getattr(self, "_plot_scroll_preview_active", False)):
            pixmap = getattr(self, "_plot_scroll_preview_pixmap", QPixmap())
            if pixmap.isNull():
                pixmap = self._capture_plot_scroll_preview_pixmap()
                if not pixmap.isNull():
                    self._plot_scroll_preview_pixmap = pixmap
            pixmap = self._normalize_plot_scroll_preview_pixmap(pixmap)
            if not pixmap.isNull():
                self._plot_scroll_preview_pixmap = pixmap
                target_w = max(int(label.width()), 1)
                target_h = max(int(label.height()), 1)
                if target_w > 0 and target_h > 0:
                    pixmap = pixmap.scaled(target_w, target_h, Qt.IgnoreAspectRatio, Qt.FastTransformation)
                    with contextlib.suppress(Exception):
                        pixmap.setDevicePixelRatio(1.0)
            if not pixmap.isNull():
                label.setPixmap(pixmap)
            else:
                label.clear()
            label.show()
            stack.setCurrentWidget(label)
            with contextlib.suppress(Exception):
                canvas.setUpdatesEnabled(False)
            self._plot_scroll_preview_active = True

    def _end_plot_scroll_burst(self) -> None:
        """Restore the live matplotlib canvas after wheel scrolling settles."""
        if not bool(getattr(self, "_plot_scroll_preview_active", False)):
            return
        timer = getattr(self, "_plot_scroll_preview_idle_timer", None)
        if timer is not None:
            with contextlib.suppress(Exception):
                timer.stop()
        self._plot_scroll_preview_last_wheel_ts = 0.0
        self._plot_scroll_preview_restore_queued = False
        stack = getattr(self, "plot_canvas_stack", None)
        label = getattr(self, "plot_scroll_preview_label", None)
        canvas = getattr(self, "canvas", None)
        if canvas is not None:
            with contextlib.suppress(Exception):
                canvas.setUpdatesEnabled(True)
        if stack is not None and canvas is not None:
            with contextlib.suppress(Exception):
                stack.setCurrentWidget(canvas)
        if label is not None:
            with contextlib.suppress(Exception):
                pixmap = label.pixmap()
                if pixmap is not None and (not pixmap.isNull()):
                    self._plot_scroll_preview_pixmap = self._normalize_plot_scroll_preview_pixmap(QPixmap(pixmap))
            label.hide()
            label.clear()
        self._plot_scroll_preview_active = False

    def _schedule_end_plot_scroll_burst(self) -> None:
        """Defer preview teardown so non-plot actions can start without blocking on canvas restore."""
        if not bool(getattr(self, "_plot_scroll_preview_active", False)):
            return
        if bool(getattr(self, "_plot_scroll_preview_restore_queued", False)):
            return
        self._plot_scroll_preview_restore_queued = True
        QTimer.singleShot(0, self._flush_deferred_plot_scroll_restore)

    def _flush_deferred_plot_scroll_restore(self) -> None:
        """Execute a previously queued preview teardown if scrolling preview is still active."""
        self._plot_scroll_preview_restore_queued = False
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            self._end_plot_scroll_burst()

    def _current_window_mode(self) -> str:
        """Return one of: `fullscreen`, `maximized`, `normal`."""
        if self.isFullScreen():
            return "fullscreen"
        if self.isMaximized():
            return "maximized"
        return "normal"

    def _capture_window_mode_snapshot(self) -> tuple[str, QByteArray]:
        """Capture the current window mode together with normal-mode geometry."""
        mode = self._current_window_mode()
        geom = QByteArray()
        if mode == "normal":
            with contextlib.suppress(Exception):
                geom = QByteArray(self.saveGeometry())
        return mode, geom

    def _restore_window_mode_snapshot(self, snapshot: tuple[str, QByteArray] | None) -> None:
        """Restore a previously captured window-mode snapshot."""
        if not (isinstance(snapshot, tuple) and len(snapshot) == 2):
            return
        if self.isMinimized():
            return
        mode_raw, geom_raw = snapshot
        mode = str(mode_raw).strip().lower()
        if mode not in {"fullscreen", "maximized", "normal"}:
            mode = "normal"
        geom = geom_raw if isinstance(geom_raw, QByteArray) else QByteArray()
        current = self._current_window_mode()
        if current == mode:
            if mode == "normal" and isinstance(geom, QByteArray) and (not geom.isEmpty()):
                with contextlib.suppress(Exception):
                    self.restoreGeometry(geom)
                    self._normal_window_geometry = QByteArray(geom)
            self._window_mode_lock = mode
            return
        self._window_mode_guard_active = True
        try:
            if mode == "fullscreen":
                self.showFullScreen()
            elif mode == "maximized":
                self.showMaximized()
            else:
                self.showNormal()
                if isinstance(geom, QByteArray) and (not geom.isEmpty()):
                    with contextlib.suppress(Exception):
                        self.restoreGeometry(geom)
        finally:
            self._window_mode_guard_active = False
        self._window_mode_lock = mode
        if mode == "normal" and isinstance(geom, QByteArray) and (not geom.isEmpty()):
            self._normal_window_geometry = QByteArray(geom)

    def _capture_window_mode_lock(self) -> None:
        """Remember current window mode/geometry so app-switch cannot alter it unexpectedly."""
        if self.isMinimized():
            return
        mode, geom = self._capture_window_mode_snapshot()
        self._window_mode_lock = mode
        if mode == "normal":
            self._normal_window_geometry = QByteArray(geom)

    def _enforce_window_mode_lock(self) -> None:
        """Restore the locked mode after activation if platform/window manager changed it."""
        if self.isMinimized() or self._window_mode_guard_active:
            return
        target = str(getattr(self, "_window_mode_lock", "normal"))
        current = self._current_window_mode()
        if target == current:
            return
        self._window_mode_guard_active = True
        try:
            if target == "fullscreen":
                self.showFullScreen()
            elif target == "maximized":
                self.showMaximized()
            else:
                self.showNormal()
                geom = getattr(self, "_normal_window_geometry", QByteArray())
                if isinstance(geom, QByteArray) and (not geom.isEmpty()):
                    with contextlib.suppress(Exception):
                        self.restoreGeometry(geom)
        finally:
            self._window_mode_guard_active = False

    def _on_application_state_changed(self, state) -> None:
        """Capture user-selected mode on deactivate without forcing restores on re-activate."""
        try:
            inactive = (state == Qt.ApplicationState.ApplicationInactive)
        except Exception:
            inactive = False
        if inactive:
            self._capture_window_mode_lock()

    def changeEvent(self, event):  # noqa: N802 (Qt override)
        """Track mode transitions so user-chosen full-screen/maximized state is respected."""
        if event is not None and event.type() == QEvent.Type.WindowStateChange:
            QTimer.singleShot(0, self._capture_window_mode_lock)
        return super().changeEvent(event)

    def _add_subplot_save_markers(self) -> None:
        """Attach small clickable [copy]/[raw] controls to every subplot.

        Marker placement adapts to each subplot width to prevent overlap while
        keeping the controls at the top-right above most plotted content.
        """
        specs: tuple[tuple[str, str, str, dict[str, object]], ...] = (
            ("copy", "[copy]", "#2f4f6f", {"boxstyle": "round,pad=0.12", "facecolor": "#eaf4ff", "alpha": 0.9, "edgecolor": "#9ab9d6"}),
            ("raw", "[raw]", "#2f5f2f", {"boxstyle": "round,pad=0.12", "facecolor": "#ebf8eb", "alpha": 0.9, "edgecolor": "#9fc39f"}),
        )
        cache = self._subplot_action_markers if isinstance(getattr(self, "_subplot_action_markers", None), dict) else {}
        self._subplot_action_markers = cache
        renderer = None
        with contextlib.suppress(Exception):
            renderer = self.canvas.get_renderer()
        active_keys = {str(k) for k in self.subplot_axes.keys()}
        for stale_key in list(cache.keys()):
            if stale_key in active_keys:
                continue
            for txt in list(cache.get(stale_key, {}).values()):
                with contextlib.suppress(Exception):
                    txt.remove()
            cache.pop(stale_key, None)

        for key, ax in self.subplot_axes.items():
            key_s = str(key)
            per_axis = cache.setdefault(key_s, {})
            keep: set[object] = set()
            for action, label, color, bbox_style in specs:
                txt = per_axis.get(action)
                is_valid = bool(
                    txt is not None
                    and getattr(txt, "axes", None) is ax
                    and txt in getattr(ax, "texts", [])
                )
                if not is_valid:
                    with contextlib.suppress(Exception):
                        if txt is not None:
                            txt.remove()
                    txt = ax.text(
                        0.99,
                        0.985,
                        label,
                        transform=ax.transAxes,
                        ha="right",
                        va="top",
                        fontsize=7,
                        color=color,
                        bbox=bbox_style,
                        clip_on=False,
                        picker=True,
                        zorder=50,
                    )
                    txt.set_gid(f"subplot_action::{action}::{key_s}")
                    per_axis[action] = txt
                else:
                    with contextlib.suppress(Exception):
                        txt.set_visible(True)
                        txt.set_transform(ax.transAxes)
                        txt.set_ha("right")
                        txt.set_va("top")
                        txt.set_color(color)
                        txt.set_fontsize(7)
                        txt.set_clip_on(False)
                        txt.set_zorder(50)
                keep.add(per_axis[action])

            if renderer is not None:
                with contextlib.suppress(Exception):
                    ax_box = ax.get_window_extent(renderer)
                    ax_w_px = max(float(ax_box.width), 1.0)
                    right_pad_px = max(4.0, min(10.0, ax_w_px * 0.012))
                    gap_px = max(4.0, min(14.0, ax_w_px * 0.022))

                    widths_px: list[float] = []
                    for action, _, _, _ in specs:
                        txt = per_axis.get(action)
                        if txt is None:
                            continue
                        widths_px.append(max(float(txt.get_window_extent(renderer).width), 1.0))

                    if widths_px:
                        total_w_px = float(sum(widths_px) + gap_px * max(0, len(widths_px) - 1) + right_pad_px + 4.0)
                        use_vertical = total_w_px > (ax_w_px * 0.95)
                        if use_vertical:
                            base_y = 0.985
                            step_y = -0.080
                            for idx, (action, _, _, _) in enumerate(specs):
                                txt = per_axis.get(action)
                                if txt is None:
                                    continue
                                txt.set_position((0.99, base_y + step_y * float(idx)))
                        else:
                            cursor_right_px = float(ax_box.x1 - right_pad_px)
                            for action, _, _, _ in specs:
                                txt = per_axis.get(action)
                                if txt is None:
                                    continue
                                txt_w_px = max(float(txt.get_window_extent(renderer).width), 1.0)
                                x_frac = float(np.clip((cursor_right_px - float(ax_box.x0)) / ax_w_px, 0.02, 0.995))
                                txt.set_position((x_frac, 0.985))
                                cursor_right_px -= (txt_w_px + gap_px)

            # Remove stale subplot-action texts left on this axes (e.g., after logic changes).
            for txt in list(ax.texts):
                gid = txt.get_gid() if hasattr(txt, "get_gid") else None
                if not (isinstance(gid, str) and gid.startswith("subplot_action::")):
                    continue
                if txt in keep:
                    continue
                with contextlib.suppress(Exception):
                    txt.remove()

            for action in list(per_axis.keys()):
                if action not in {"copy", "raw"}:
                    with contextlib.suppress(Exception):
                        per_axis[action].remove()
                    per_axis.pop(action, None)

    def _hide_subplot_action_markers(self, ax) -> list[tuple[object, bool]]:
        """Hide clickable subplot [copy]/[raw] markers on one axis and return visibility."""
        states: list[tuple[object, bool]] = []
        found = False
        cache = self._subplot_action_markers if isinstance(getattr(self, "_subplot_action_markers", None), dict) else {}
        key_for_axis = next((str(k) for k, a in getattr(self, "subplot_axes", {}).items() if a is ax), None)
        if key_for_axis is not None:
            per_axis = cache.get(key_for_axis, {})
            for txt in list(per_axis.values()):
                if getattr(txt, "axes", None) is not ax:
                    continue
                with contextlib.suppress(Exception):
                    was_visible = bool(txt.get_visible())
                    txt.set_visible(False)
                    states.append((txt, was_visible))
                    found = True
        if not found:
            for txt in list(ax.texts):
                gid = txt.get_gid() if hasattr(txt, "get_gid") else None
                if not (isinstance(gid, str) and gid.startswith("subplot_action::")):
                    continue
                with contextlib.suppress(Exception):
                    was_visible = bool(txt.get_visible())
                    txt.set_visible(False)
                    states.append((txt, was_visible))
        return states

    def _restore_subplot_action_markers(self, states: list[tuple[object, bool]]) -> None:
        """Restore visibility of previously hidden subplot [copy]/[raw] markers."""
        for txt, was_visible in states:
            with contextlib.suppress(Exception):
                txt.set_visible(bool(was_visible))

    @staticmethod
    def _hide_axis_export_artists(
        ax,
        *,
        hide_texts: bool = False,
        hide_lines: bool = False,
        hide_axis: bool = False,
    ) -> dict[str, object]:
        """Temporarily hide in-axis artists so image-only exports stay clean."""
        states: dict[str, object] = {
            "texts": [],
            "lines": [],
            "axis_on": bool(getattr(ax, "axison", True)),
        }
        if hide_texts:
            text_states: list[tuple[object, bool]] = []
            for txt in list(ax.texts):
                with contextlib.suppress(Exception):
                    was_visible = bool(txt.get_visible())
                    txt.set_visible(False)
                    text_states.append((txt, was_visible))
            states["texts"] = text_states
        if hide_lines:
            line_states: list[tuple[object, bool]] = []
            for line in list(ax.lines):
                with contextlib.suppress(Exception):
                    was_visible = bool(line.get_visible())
                    line.set_visible(False)
                    line_states.append((line, was_visible))
            states["lines"] = line_states
        if hide_axis:
            with contextlib.suppress(Exception):
                ax.set_axis_off()
        return states

    @staticmethod
    def _restore_axis_export_artists(ax, states: dict[str, object]) -> None:
        """Restore artists hidden by `_hide_axis_export_artists()`."""
        for txt, was_visible in states.get("texts", []):
            with contextlib.suppress(Exception):
                txt.set_visible(bool(was_visible))
        for line, was_visible in states.get("lines", []):
            with contextlib.suppress(Exception):
                line.set_visible(bool(was_visible))
        with contextlib.suppress(Exception):
            if bool(states.get("axis_on", True)):
                ax.set_axis_on()
            else:
                ax.set_axis_off()

    def _save_subplot_by_key(self, key: str) -> None:
        """Legacy save action now merged into raw-data export."""
        self._save_subplot_raw_data_by_key(key)

    def _copy_subplot_by_key(self, key: str) -> None:
        """Copy subplot image to system clipboard.

        Copy current subplot rendering (image + x/y axes), excluding subplot action markers.
        """
        ax = self.subplot_axes.get(key)
        if ax is None:
            return
        try:
            marker_states = self._hide_subplot_action_markers(ax)
            export_states: dict[str, object] | None = None
            try:
                if key == "centered_bin":
                    export_states = self._hide_axis_export_artists(
                        ax,
                        hide_texts=True,
                        hide_lines=True,
                        hide_axis=True,
                    )
                self.canvas.draw()
                renderer = self.canvas.get_renderer()
                extra_axes = []
                if key == "rbasex_radial_profile":
                    secondary_x = getattr(self, "rbasex_profile_secondary_xaxis", None)
                    secondary_y = getattr(self, "rbasex_profile_secondary_yaxis", None)
                    if secondary_x is not None:
                        extra_axes.append(secondary_x)
                    if secondary_y is not None:
                        extra_axes.append(secondary_y)
                if key == "centered_bin":
                    bbox = ax.bbox
                elif extra_axes:
                    bboxes = [ax.get_tightbbox(renderer)]
                    for extra_ax in extra_axes:
                        with contextlib.suppress(Exception):
                            extra_bbox = extra_ax.get_tightbbox(renderer)
                            if extra_bbox is not None:
                                bboxes.append(extra_bbox)
                    bbox = matplotlib.transforms.Bbox.union([b for b in bboxes if b is not None]).expanded(1.03, 1.08)
                else:
                    bbox = ax.get_tightbbox(renderer).expanded(1.03, 1.08)
                canvas_w = int(getattr(renderer, "width", 0))
                canvas_h = int(getattr(renderer, "height", 0))
                if canvas_w <= 1 or canvas_h <= 1:
                    raise RuntimeError("Renderer size is invalid.")

                x0 = max(0, int(np.floor(float(bbox.x0))))
                y0 = max(0, int(np.floor(float(bbox.y0))))
                x1 = min(canvas_w, int(np.ceil(float(bbox.x1))))
                y1 = min(canvas_h, int(np.ceil(float(bbox.y1))))
                if x1 <= x0 or y1 <= y0:
                    ax_bbox = ax.bbox
                    x0 = max(0, int(np.floor(float(ax_bbox.x0))))
                    y0 = max(0, int(np.floor(float(ax_bbox.y0))))
                    x1 = min(canvas_w, int(np.ceil(float(ax_bbox.x1))))
                    y1 = min(canvas_h, int(np.ceil(float(ax_bbox.y1))))
                if x1 <= x0 or y1 <= y0:
                    raise RuntimeError("Subplot bounding box is invalid.")

                rgba = np.asarray(self.canvas.buffer_rgba())
                if rgba.ndim != 3 or rgba.shape[2] != 4:
                    raise RuntimeError("Canvas RGBA buffer is unavailable.")
                h, w = int(rgba.shape[0]), int(rgba.shape[1])
                if h <= 1 or w <= 1:
                    raise RuntimeError("Canvas RGBA buffer is empty.")

                row0 = max(0, h - y1)
                row1 = min(h, h - y0)
                col0 = max(0, x0)
                col1 = min(w, x1)
                crop = rgba[row0:row1, col0:col1, :]
                if crop.size == 0:
                    raise RuntimeError("Subplot crop is empty.")

                crop_c = np.ascontiguousarray(crop)
                crop_h, crop_w = int(crop_c.shape[0]), int(crop_c.shape[1])
                bytes_per_line = int(crop_c.strides[0])
                crop_bytes = crop_c.tobytes(order="C")
                img = QImage(crop_bytes, crop_w, crop_h, bytes_per_line, QImage.Format_RGBA8888).copy()
                if img.isNull():
                    raise RuntimeError("Clipboard image creation failed.")
            finally:
                if export_states is not None:
                    self._restore_axis_export_artists(ax, export_states)
                self._restore_subplot_action_markers(marker_states)
                if marker_states or export_states is not None:
                    self.canvas.draw_idle()

            # Keep clipboard payload bounded to avoid Qt allocation failures.
            max_side = 2800
            max_pixels = 8_000_000
            pixel_n = int(img.width() * img.height())
            if img.width() > max_side or img.height() > max_side or pixel_n > max_pixels:
                sx = max_side / max(1, img.width())
                sy = max_side / max(1, img.height())
                sp = np.sqrt(max_pixels / max(1, pixel_n))
                scale = min(sx, sy, sp)
                new_w = max(1, int(np.floor(img.width() * scale)))
                new_h = max(1, int(np.floor(img.height() * scale)))
                img = img.scaled(new_w, new_h, Qt.KeepAspectRatio, Qt.SmoothTransformation)

            self._set_image_on_clipboard(img)
            self._set_status(f"Copied subplot '{key}' to clipboard.")
        except Exception as exc:
            QMessageBox.critical(self, "Copy failed", f"Failed to copy subplot:\n{exc}")
            self._set_status("Subplot copy failed.")

    @staticmethod
    def _coerce_array_for_npz(value, default_dtype=np.float64) -> np.ndarray:
        """Convert value to a saveable numpy array for raw subplot export."""
        arr = np.asarray(value)
        if arr.dtype == np.dtype("O"):
            with contextlib.suppress(Exception):
                arr = arr.astype(default_dtype)
        if arr.dtype == np.dtype("O"):
            arr = np.asarray(arr, dtype=str)
        return arr

    @staticmethod
    def _log10_display_export_values(values: np.ndarray) -> np.ndarray:
        """Convert positive values to their displayed log10-axis positions for export."""
        arr = np.asarray(values, dtype=np.float64).reshape(-1)
        out = np.full(arr.shape, np.nan, dtype=np.float64)
        valid = np.isfinite(arr) & (arr > 0.0)
        if np.any(valid):
            out[valid] = np.log10(arr[valid])
        return out

    def _transform_subplot_export_values(
        self,
        key: str,
        axis_name: str,
        values: np.ndarray,
        *,
        ax,
    ) -> np.ndarray:
        """Convert exported subplot arrays to the same value space shown on screen."""
        arr = np.asarray(values, dtype=np.float64).reshape(-1)
        if str(key) != "ion_histogram" or str(axis_name).lower() != "y":
            return arr
        if str(ax.get_yscale()).lower() != "log":
            return arr
        return self._log10_display_export_values(arr)

    def _collect_subplot_raw_payload(self, key: str, ax) -> tuple[dict[str, np.ndarray], dict[str, object]]:
        """Collect currently plotted raw arrays and metadata from one subplot."""
        export_y_transform = "identity"
        if str(key) == "ion_histogram":
            export_y_transform = "log10" if str(ax.get_yscale()).lower() == "log" else "identity"
        arrays: dict[str, np.ndarray] = {}
        meta: dict[str, object] = {
            "subplot_key": str(key),
            "title": str(ax.get_title()),
            "xlabel": str(ax.get_xlabel()),
            "ylabel": str(ax.get_ylabel()),
            "xscale": str(ax.get_xscale()),
            "yscale": str(ax.get_yscale()),
            "xlim": [float(v) for v in ax.get_xlim()],
            "ylim": [float(v) for v in ax.get_ylim()],
            "lines": [],
            "scatters": [],
            "quadmeshes": [],
            "collections": [],
            "patches": [],
            "images": [],
            "y_export_space": "display_axis_values" if str(key) == "ion_histogram" else "data_values",
            "y_export_transform": export_y_transform,
        }
        arrays["axis_xlim"] = np.asarray(ax.get_xlim(), dtype=np.float64)
        arrays["axis_ylim"] = np.asarray(ax.get_ylim(), dtype=np.float64)
        if str(key) == "ion_histogram":
            arrays["axis_ylim"] = self._transform_subplot_export_values(key, "y", arrays["axis_ylim"], ax=ax)
            meta["ion_hist_display_normalized"] = bool(self._ion_hist_normalize_to_peak_enabled())
            meta["ion_hist_display_log_scale"] = bool(str(ax.get_yscale()).lower() == "log")
        if str(key) == "rbasex_radial_profile" and self._radial_profile_is_angular_integrated():
            result = self.rbasex_recon_result if isinstance(self.rbasex_recon_result, dict) else {}
            r_vals = np.asarray(result.get("r", np.zeros(0)), dtype=np.float64).reshape(-1)
            i_vals = np.asarray(result.get("i", np.zeros(0)), dtype=np.float64).reshape(-1)
            beta_vals = np.asarray(result.get("beta", np.zeros_like(i_vals)), dtype=np.float64).reshape(-1)
            n_direct = min(r_vals.size, i_vals.size, beta_vals.size)
            arrays = {}
            if n_direct > 0:
                arrays["direct_rbasex_r"] = np.asarray(r_vals[:n_direct], dtype=np.float64)
                arrays["direct_rbasex_i"] = np.asarray(i_vals[:n_direct], dtype=np.float64)
                arrays["direct_rbasex_beta"] = np.asarray(beta_vals[:n_direct], dtype=np.float64)
                meta["rbasex_profile_mode"] = "direct_integrated_r_i_beta"
                meta["raw_columns"] = ["direct_rbasex_r", "direct_rbasex_i", "direct_rbasex_beta"]
            else:
                meta["rbasex_profile_mode"] = "direct_integrated_missing"
            return arrays, meta
        elif str(key) == "rbasex_radial_profile":
            meta["rbasex_profile_mode"] = "angle_resolved_reintegrated_image"

        export_filtered_ion_scatter_only = bool(
            str(key) == "ion_scatter"
            and getattr(self, "ion_filter_enable_checkbox", None) is not None
            and self.ion_filter_enable_checkbox.isChecked()
        )

        line_idx = 0
        for line in list(ax.lines):
            gid = line.get_gid() if hasattr(line, "get_gid") else None
            if isinstance(gid, str) and gid.startswith("subplot_action::"):
                continue
            try:
                x = self._coerce_array_for_npz(line.get_xdata(), default_dtype=np.float64).reshape(-1)
                y = self._coerce_array_for_npz(line.get_ydata(), default_dtype=np.float64).reshape(-1)
                y = self._transform_subplot_export_values(key, "y", y, ax=ax)
            except Exception:
                continue
            arrays[f"line_{line_idx}_x"] = x
            arrays[f"line_{line_idx}_y"] = y
            meta["lines"].append(
                {
                    "index": int(line_idx),
                    "label": str(line.get_label()),
                    "gid": (None if gid is None else str(gid)),
                    "visible": bool(line.get_visible()),
                }
            )
            line_idx += 1

        scatter_idx = 0
        quad_idx = 0
        coll_idx = 0
        for coll in list(ax.collections):
            try:
                gid = coll.get_gid() if hasattr(coll, "get_gid") else None
                if isinstance(coll, PathCollection):
                    if export_filtered_ion_scatter_only and str(gid) == "ion_scatter_context":
                        continue
                    offsets = self._coerce_array_for_npz(coll.get_offsets(), default_dtype=np.float64)
                    if offsets.ndim == 2 and offsets.shape[1] >= 2:
                        arrays[f"scatter_{scatter_idx}_xy"] = np.asarray(offsets[:, :2], dtype=np.float64)
                    cvals = coll.get_array()
                    if cvals is not None:
                        arrays[f"scatter_{scatter_idx}_c"] = self._coerce_array_for_npz(cvals, default_dtype=np.float64).reshape(-1)
                    meta["scatters"].append(
                        {
                            "index": int(scatter_idx),
                            "visible": bool(coll.get_visible()),
                            "label": str(coll.get_label()),
                            "gid": (None if gid is None else str(gid)),
                        }
                    )
                    scatter_idx += 1
                    continue

                if isinstance(coll, QuadMesh):
                    qarr = coll.get_array()
                    if qarr is not None:
                        arrays[f"quadmesh_{quad_idx}_values"] = self._coerce_array_for_npz(qarr, default_dtype=np.float64)
                    if hasattr(coll, "get_coordinates"):
                        with contextlib.suppress(Exception):
                            coords = self._coerce_array_for_npz(coll.get_coordinates(), default_dtype=np.float64)
                            if coords.size > 0:
                                arrays[f"quadmesh_{quad_idx}_coords"] = coords
                    meta["quadmeshes"].append(
                        {
                            "index": int(quad_idx),
                            "visible": bool(coll.get_visible()),
                            "label": str(coll.get_label()),
                            "gid": (None if gid is None else str(gid)),
                        }
                    )
                    quad_idx += 1
                    continue

                carr = coll.get_array() if hasattr(coll, "get_array") else None
                entry: dict[str, object] = {
                    "index": int(coll_idx),
                    "visible": bool(coll.get_visible()),
                    "label": str(coll.get_label()),
                    "gid": (None if gid is None else str(gid)),
                    "class": str(type(coll).__name__),
                }
                if carr is not None:
                    arrays[f"collection_{coll_idx}_array"] = self._coerce_array_for_npz(carr, default_dtype=np.float64)
                    entry["has_array"] = True
                else:
                    entry["has_array"] = False
                meta["collections"].append(entry)
                coll_idx += 1
            except Exception:
                continue

        patch_idx = 0
        for patch in list(getattr(ax, "patches", [])):
            gid = patch.get_gid() if hasattr(patch, "get_gid") else None
            try:
                entry: dict[str, object] = {
                    "index": int(patch_idx),
                    "visible": bool(patch.get_visible()),
                    "label": str(patch.get_label()),
                    "gid": (None if gid is None else str(gid)),
                    "class": str(type(patch).__name__),
                }
                if str(type(patch).__name__) == "StepPatch" and hasattr(patch, "get_data"):
                    stair = patch.get_data()
                    values = self._coerce_array_for_npz(getattr(stair, "values", np.zeros(0, dtype=np.float64)), default_dtype=np.float64).reshape(-1)
                    edges = self._coerce_array_for_npz(getattr(stair, "edges", np.zeros(0, dtype=np.float64)), default_dtype=np.float64).reshape(-1)
                    baseline = self._coerce_array_for_npz(getattr(stair, "baseline", np.array([0.0], dtype=np.float64)), default_dtype=np.float64).reshape(-1)
                    values = self._transform_subplot_export_values(key, "y", values, ax=ax)
                    baseline = self._transform_subplot_export_values(key, "y", baseline, ax=ax)
                    arrays[f"patch_{patch_idx}_values"] = values
                    arrays[f"patch_{patch_idx}_edges"] = edges
                    arrays[f"patch_{patch_idx}_baseline"] = baseline
                    entry["kind"] = "stairs"
                meta["patches"].append(entry)
                patch_idx += 1
            except Exception:
                continue

        image_idx = 0
        for img in list(ax.images):
            try:
                gid = img.get_gid() if hasattr(img, "get_gid") else None
                if export_filtered_ion_scatter_only and str(gid) == "ion_scatter_context":
                    continue
                arr = self._coerce_array_for_npz(img.get_array(), default_dtype=np.float64)
                arrays[f"image_{image_idx}"] = arr
                arrays[f"image_{image_idx}_extent"] = np.asarray(img.get_extent(), dtype=np.float64)
                meta["images"].append(
                    {
                        "index": int(image_idx),
                        "shape": [int(v) for v in arr.shape],
                        "origin": str(img.origin),
                        "visible": bool(img.get_visible()),
                        "gid": (None if gid is None else str(gid)),
                    }
                )
                image_idx += 1
            except Exception:
                continue

        return arrays, meta

    def _save_subplot_raw_data_by_key(self, key: str) -> None:
        """Save plotted raw data for one subplot as a portable raw-data bundle."""
        ax = self.subplot_axes.get(key)
        if ax is None:
            return
        tag = self._default_session_tag()
        default_name = f"{tag}_{key}_raw.npz"
        default_dir = os.path.join(os.getcwd(), SESSION_OUTPUT_DIRNAME)
        os.makedirs(default_dir, exist_ok=True)
        default_path = os.path.join(default_dir, default_name)
        out_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save subplot raw data bundle",
            default_path,
            "NumPy archive (*.npz)",
        )
        if not out_path:
            return
        if not out_path.lower().endswith(".npz"):
            out_path = f"{out_path}.npz"
        try:
            out_dir = os.path.dirname(out_path)
            if out_dir:
                os.makedirs(out_dir, exist_ok=True)
            arrays, meta = self._collect_subplot_raw_payload(key, ax)
            meta_json = json.dumps(meta, ensure_ascii=False, indent=2)
            payload: dict[str, np.ndarray] = {"meta_json": np.array(meta_json)}
            payload.update(arrays)
            np.savez_compressed(out_path, **payload)
            meta_path = f"{os.path.splitext(out_path)[0]}.json"
            with open(meta_path, "w", encoding="utf-8") as fh:
                fh.write(meta_json)
            self._set_status(f"Saved raw subplot data '{key}': {out_path} (+ {meta_path})")
        except Exception as exc:
            QMessageBox.critical(self, "Raw export failed", f"Failed to save subplot raw data:\n{exc}")
            self._set_status("Subplot raw-data save failed.")

    @staticmethod
    def _try_set_image_on_clipboard_qt(img: QImage, *, attempts: int = 6) -> tuple[bool, str]:
        """Use Qt clipboard first, retrying around transient Windows clipboard locks."""
        pixmap = QPixmap.fromImage(img)
        if pixmap.isNull():
            return False, "Clipboard pixmap creation failed."
        clipboard = QApplication.clipboard()
        last_error = "Qt clipboard did not confirm the copied image."
        for attempt in range(max(1, int(attempts))):
            try:
                with contextlib.suppress(Exception):
                    clipboard.clear()
                QApplication.processEvents()
                clipboard.setPixmap(pixmap)
                QApplication.processEvents()
                mime = clipboard.mimeData()
                if mime is not None and mime.hasImage():
                    copied_pixmap = clipboard.pixmap()
                    if not copied_pixmap.isNull():
                        return True, ""
            except Exception as exc:
                last_error = str(exc)
            time.sleep(0.04 * float(attempt + 1))
        return False, last_error

    @staticmethod
    def _try_set_image_on_clipboard_windows(img: QImage, *, attempts: int = 8) -> tuple[bool, str]:
        """Windows-native clipboard fallback using CF_DIB data."""
        if not sys.platform.startswith("win"):
            return False, "Native Windows clipboard fallback is unavailable on this platform."
        try:
            import ctypes
            from ctypes import wintypes
        except Exception as exc:
            return False, str(exc)

        image = img.convertToFormat(QImage.Format_ARGB32)
        if image.isNull():
            return False, "Clipboard image conversion failed."

        payload = QByteArray()
        buffer = QBuffer(payload)
        if not buffer.open(QIODevice.WriteOnly):
            return False, "Could not open temporary clipboard buffer."
        try:
            if not image.save(buffer, "BMP"):
                return False, "Could not encode clipboard image as BMP."
        finally:
            buffer.close()
        bmp_bytes = bytes(payload)
        if len(bmp_bytes) <= 14:
            return False, "Encoded BMP payload is empty."
        dib_bytes = bmp_bytes[14:]

        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        user32.OpenClipboard.argtypes = [wintypes.HWND]
        user32.OpenClipboard.restype = wintypes.BOOL
        user32.CloseClipboard.argtypes = []
        user32.CloseClipboard.restype = wintypes.BOOL
        user32.EmptyClipboard.argtypes = []
        user32.EmptyClipboard.restype = wintypes.BOOL
        user32.SetClipboardData.argtypes = [wintypes.UINT, wintypes.HANDLE]
        user32.SetClipboardData.restype = wintypes.HANDLE
        kernel32.GlobalAlloc.argtypes = [wintypes.UINT, ctypes.c_size_t]
        kernel32.GlobalAlloc.restype = wintypes.HGLOBAL
        kernel32.GlobalLock.argtypes = [wintypes.HGLOBAL]
        kernel32.GlobalLock.restype = wintypes.LPVOID
        kernel32.GlobalUnlock.argtypes = [wintypes.HGLOBAL]
        kernel32.GlobalUnlock.restype = wintypes.BOOL
        kernel32.GlobalFree.argtypes = [wintypes.HGLOBAL]
        kernel32.GlobalFree.restype = wintypes.HGLOBAL
        cf_dib = 8
        gmem_moveable = 0x0002
        last_error = "Windows clipboard stayed busy."
        for attempt in range(max(1, int(attempts))):
            if not user32.OpenClipboard(None):
                last_error = f"OpenClipboard failed ({ctypes.GetLastError()})."
                time.sleep(0.04 * float(attempt + 1))
                continue
            handle = None
            try:
                if not user32.EmptyClipboard():
                    last_error = f"EmptyClipboard failed ({ctypes.GetLastError()})."
                    continue
                handle = kernel32.GlobalAlloc(gmem_moveable, len(dib_bytes))
                if not handle:
                    last_error = f"GlobalAlloc failed ({ctypes.GetLastError()})."
                    continue
                locked = kernel32.GlobalLock(handle)
                if not locked:
                    last_error = f"GlobalLock failed ({ctypes.GetLastError()})."
                    kernel32.GlobalFree(handle)
                    handle = None
                    continue
                try:
                    ctypes.memmove(locked, dib_bytes, len(dib_bytes))
                finally:
                    kernel32.GlobalUnlock(handle)
                if not user32.SetClipboardData(cf_dib, handle):
                    last_error = f"SetClipboardData failed ({ctypes.GetLastError()})."
                    kernel32.GlobalFree(handle)
                    handle = None
                    continue
                handle = None
                return True, ""
            finally:
                user32.CloseClipboard()
                if handle:
                    kernel32.GlobalFree(handle)
            time.sleep(0.04 * float(attempt + 1))
        return False, last_error

    def _set_image_on_clipboard(self, img: QImage) -> None:
        """Copy one rendered subplot image to the system clipboard as robustly as possible."""
        ok, qt_error = self._try_set_image_on_clipboard_qt(img)
        if ok:
            return
        native_error = ""
        if sys.platform.startswith("win"):
            ok, native_error = self._try_set_image_on_clipboard_windows(img)
            if ok:
                return
        detail = qt_error.strip() if qt_error else "Clipboard copy failed."
        if native_error:
            detail = f"{detail}\nNative fallback: {native_error}"
        raise RuntimeError(detail)

    def _has_valid_rbasex_image_for_centered_compare(self) -> bool:
        """Return True if rBasex has a usable 2D image+extent for centered compare overlay."""
        result = self.rbasex_recon_result
        if result is None or result.get("error"):
            return False
        img = np.asarray(result.get("image", np.zeros((0, 0))), dtype=np.float64)
        extent = np.asarray(result.get("extent", np.zeros(0)), dtype=np.float64).reshape(-1)
        if img.ndim != 2 or img.size == 0 or extent.size != 4:
            return False
        return bool(np.isfinite(extent).all())

    @staticmethod
    def _centered_compare_split_x_from_edges(xedges: np.ndarray) -> float | None:
        """Return the x-coordinate that separates left/right halves of the centered image."""
        arr = np.asarray(xedges, dtype=np.float64).reshape(-1)
        if arr.size < 2 or not np.isfinite(arr).all():
            return None
        lo = float(min(arr[0], arr[-1]))
        hi = float(max(arr[0], arr[-1]))
        if lo <= 0.0 <= hi:
            return 0.0
        return float(0.5 * (lo + hi))

    def _is_centered_right_half_click(self, x_value: float) -> bool:
        """Check whether a centered-bin click falls on the right half region."""
        if not np.isfinite(x_value):
            return False
        if self.centered_hist_data is not None:
            xedges = np.asarray(self.centered_hist_data.get("xedges", np.zeros(0)), dtype=np.float64).reshape(-1)
            split_x = self._centered_compare_split_x_from_edges(xedges)
            if split_x is not None:
                return bool(float(x_value) >= float(split_x))
        return bool(x_value >= 0.0)

    def _toggle_centered_right_half_compare(self) -> bool:
        """Toggle centered-bin right-half replacement with rBasex reconstruction."""
        if self.centered_hist_data is None:
            self._set_status("No centered image available. Click Apply Ring Selection and Bin first.")
            return False
        if (not self.centered_right_half_compare_enabled) and (not self._has_valid_rbasex_image_for_centered_compare()):
            self._set_status("No rBasex image available. Click Start Reconstruction first.")
            return False

        self.centered_right_half_compare_enabled = not self.centered_right_half_compare_enabled
        # 16i: the centered image is replaced (recon overlay on/off) — the
        # cached theta-guide backgrounds show the previous content.
        self._invalidate_theta_blit_backgrounds()
        self._refresh_reconstruction_panels_only()
        self._reset_toolbar_navigation_history()
        if self.centered_right_half_compare_enabled:
            self._set_status("Centered compare ON: left=projection, right=rBasex reconstruction.")
        else:
            self._set_status("Centered compare OFF: projection-only image restored.")
        return True

    def _build_centered_right_half_compare_data(
        self,
        xedges: np.ndarray,
        yedges: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray] | None:
        """Map rBasex image onto centered-bin grid and return (recon_on_centered, right_mask)."""
        if not self.centered_right_half_compare_enabled:
            return None
        if not self._has_valid_rbasex_image_for_centered_compare():
            return None

        result = self.rbasex_recon_result if self.rbasex_recon_result is not None else {}
        recon = np.nan_to_num(
            np.asarray(result.get("image", np.zeros((0, 0))), dtype=np.float64),
            nan=0.0,
            posinf=0.0,
            neginf=0.0,
        )
        extent = np.asarray(result.get("extent", np.zeros(0)), dtype=np.float64).reshape(-1)
        if recon.ndim != 2 or recon.size == 0 or extent.size != 4:
            return None

        x0, x1, y0, y1 = (float(extent[0]), float(extent[1]), float(extent[2]), float(extent[3]))
        if not np.isfinite([x0, x1, y0, y1]).all():
            return None
        if abs(x1 - x0) <= 1e-12 or abs(y1 - y0) <= 1e-12:
            return None
        if x1 < x0:
            recon = np.fliplr(recon)
            x0, x1 = x1, x0
        if y1 < y0:
            recon = np.flipud(recon)
            y0, y1 = y1, y0

        xcenters = 0.5 * (xedges[:-1] + xedges[1:])
        ycenters = 0.5 * (yedges[:-1] + yedges[1:])
        if xcenters.size == 0 or ycenters.size == 0:
            return None

        sx_edges = np.linspace(x0, x1, recon.shape[1] + 1, dtype=np.float64)
        sy_edges = np.linspace(y0, y1, recon.shape[0] + 1, dtype=np.float64)
        ix = np.searchsorted(sx_edges, xcenters, side="right") - 1
        iy = np.searchsorted(sy_edges, ycenters, side="right") - 1
        valid_x = (ix >= 0) & (ix < recon.shape[1])
        valid_y = (iy >= 0) & (iy < recon.shape[0])
        ix = np.clip(ix, 0, recon.shape[1] - 1)
        iy = np.clip(iy, 0, recon.shape[0] - 1)

        recon_on_centered = recon[np.ix_(iy, ix)]
        if not np.all(valid_x):
            recon_on_centered[:, ~valid_x] = 0.0
        if not np.all(valid_y):
            recon_on_centered[~valid_y, :] = 0.0
        recon_on_centered = np.clip(recon_on_centered, 0.0, None)

        split_x = self._centered_compare_split_x_from_edges(xedges)
        if split_x is None:
            return None
        right_mask = xcenters >= float(split_x)
        if not np.any(right_mask):
            mid = 0.5 * (float(xcenters[0]) + float(xcenters[-1]))
            right_mask = xcenters >= mid
        if not np.any(right_mask):
            return None

        return recon_on_centered, right_mask

    def align_ion_main_direction_once(self, _checked: bool = False) -> None:
        """One-shot action: align ion main-direction to horizontal and keep manual mode."""
        # This control behaves as an action, not a persistent mode.
        if not self._has_pairs():
            self._set_status("No paired ion data available for horizontal alignment.")
            return

        if not self.ion_dirline_btn.isChecked():
            self.ion_dirline_btn.setChecked(True)

        if self.ion_main_axis_angle_deg is None:
            self._refresh_scatter_panels_only(preserve_scatter_view=True)

        if self.ion_main_axis_angle_deg is None:
            self._set_status("Main-direction angle is unavailable for current ion data; alignment skipped.")
            return

        main_angle_now = float(self.ion_main_axis_angle_deg)
        target_offset = self._wrap_angle_deg(float(self.ion_user_rotation_deg) - main_angle_now)
        applied = self._apply_ion_rotation_deg(target_offset, announce=False)
        if applied:
            self._set_status(
                "Ion main direction aligned to horizontal once: "
                f"angle={main_angle_now:.6g} deg, rotation offset={target_offset:.6g} deg. "
                "Use Rotation offset for fine tuning."
            )

    def _on_ion_filter_toggled(self, checked: bool) -> None:
        """Refresh plot state when ion scatter filter is enabled/disabled."""
        had_projection_results = (
            self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        ion_mode = self._current_ion_filter_mode()
        self._clear_circle_result()
        if self._has_pairs():
            self._refresh_after_circle_clear(
                refresh_scatter=True,
                refresh_ion_scatter=True,
                preserve_scatter_view=True,
                refresh_projection_panels=had_projection_results,
            )
            mode_label = self._ion_filter_mode_label(ion_mode)
            self._set_status(
                f"Ion filter {'enabled' if checked else 'disabled'} ({mode_label} mode)."
            )
        else:
            self._update_ion_overlay_only()

    def _on_ion_filter_mode_changed(self, _index: int) -> None:
        """Switch ion filter mode between spatial, density, or combined behavior."""
        if not bool(self.ion_filter_enable_checkbox.isChecked()):
            if self._has_pairs():
                self._refresh_ion_scatter_panel_only(preserve_view=True)
            else:
                self._update_ion_overlay_only()
            mode_label = self._ion_filter_mode_label(self._current_ion_filter_mode())
            self._set_status(f"Ion filter mode set to {mode_label}.")
            return
        self._on_ion_filter_toggled(True)

    def _on_ion_density_filter_params_changed(self) -> None:
        """Apply edited ion density-filter settings."""
        if not self._ion_filter_mode_uses_density(self._current_ion_filter_mode()):
            return
        if bool(self.ion_filter_enable_checkbox.isChecked()):
            self._on_ion_filter_toggled(True)
        elif self._has_pairs():
            self._refresh_ion_scatter_panel_only(preserve_view=True)

    def _on_electron_filter_mode_changed(self, _index: int) -> None:
        """Switch electron pre-filter mode between spatial and point-density behavior."""
        had_projection_results = (
            self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        self._clear_circle_result()
        if self._has_pairs():
            self._refresh_after_circle_clear(
                refresh_scatter=True,
                refresh_ion_scatter=False,
                preserve_scatter_view=True,
                refresh_projection_panels=had_projection_results,
            )
        else:
            self._update_circle_overlay_only()
        mode_label = "point density" if self._current_electron_filter_mode() == "density" else "spatial distribution"
        self._set_status(f"Electron filter mode set to {mode_label}.")

    def _on_electron_density_filter_params_changed(self) -> None:
        """Apply edited electron density-filter settings."""
        if self._current_electron_filter_mode() != "density":
            return
        self._on_electron_filter_mode_changed(-1)

    def _on_outer_ring_filter_toggled(self, checked: bool) -> None:
        """Enable/disable outer-ring noise filter and refresh dependent views."""
        had_projection_results = (
            self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        self._clear_circle_result()
        if self._has_pairs():
            self._refresh_after_circle_clear(
                refresh_scatter=False,
                preserve_scatter_view=False,
                refresh_projection_panels=had_projection_results,
            )
        else:
            self._update_circle_overlay_only()
        self._set_status("Outer-ring noise filter enabled." if checked else "Outer-ring noise filter disabled.")

    def _refresh_scatter_display_from_controls(self) -> None:
        """Refresh scatter panels after non-filter display-control edits."""
        if self._has_pairs():
            self._refresh_scatter_panels_only(preserve_scatter_view=False)
        elif self._has_session_subplot_previews():
            self._refresh_plots()
        else:
            self._draw_placeholder()

    def _refresh_electron_scatter_panel_only(
        self,
        preserve_view: bool = True,
        *,
        force_full_draw: bool = False,
        draw_canvas: bool = True,
    ) -> None:
        """Refresh only electron scatter/polar panel for display-only control changes."""
        if not self._has_pairs():
            if self._has_session_subplot_previews():
                self._refresh_plots()
                return
            self._draw_placeholder()
            return

        e_view = self._capture_axis_view_state(self.ax_scatter_e) if preserve_view else None
        self._clear_circle_overlay_artists()

        display_data = self._current_scatter_display_data()
        electron_show = np.asarray(display_data.get("electron_show", np.empty((0, 3))), dtype=np.float64)
        plotted_e = self._plot_electron_scatter_from_display_data(display_data)

        if electron_show.shape[0] > plotted_e:
            self.ax_scatter_e.text(
                0.01,
                0.99,
                f"Plotted {plotted_e}/{electron_show.shape[0]}",
                transform=self.ax_scatter_e.transAxes,
                ha="left",
                va="top",
            )

        if preserve_view:
            self._restore_axis_view_state(self.ax_scatter_e, e_view, keep_square=False)

        self._add_subplot_save_markers()
        if draw_canvas:
            axes_to_draw = [self.ax_scatter_e]
            if self.electron_scatter_colorbar is not None:
                axes_to_draw.append(getattr(self.electron_scatter_colorbar, "ax", None))
            self._draw_axes_immediate(axes_to_draw, include_tight=True, force_full=force_full_draw)
            self._capture_scatter_blit_backgrounds(electron=True, ion=False)
            self._update_circle_overlay_only()

    def _refresh_ion_scatter_panel_only(
        self,
        preserve_view: bool = True,
        *,
        force_full_draw: bool = False,
    ) -> None:
        """Refresh only ion scatter panel for display-only control changes."""
        if not self._has_pairs():
            if self._has_session_subplot_previews():
                self._refresh_plots()
                return
            self._draw_placeholder()
            return

        i_view = self._capture_axis_view_state(self.ax_scatter_i) if preserve_view else None
        self._clear_ion_overlay_artists()

        display_data = self._current_scatter_display_data()
        ion_show = np.asarray(display_data.get("ion_show", np.empty((0, 3))), dtype=np.float64)
        ion_context = np.asarray(display_data.get("ion_context", np.empty((0, 3))), dtype=np.float64)
        ion_density_reference = np.asarray(
            display_data.get("ion_density_reference", np.empty((0, 3))),
            dtype=np.float64,
        )
        ion_density_selected_mask = np.asarray(
            display_data.get("ion_density_selected_mask", np.empty(0, dtype=bool)),
            dtype=bool,
        ).reshape(-1)

        plotted_i = self._plot_density_scatter(
            self.ax_scatter_i,
            ion_show,
            "Ion Scatter",
            cmap="inferno",
            density_bin_size=None,
            empty_text="No points",
            scale_mode=self._current_ion_scatter_scale(),
            show_colorbar=self.ion_scatter_colorbar_checkbox.isChecked(),
            context_points=ion_context,
            show_context_points=bool(display_data.get("ion_filter_on", False)),
            density_reference_points=ion_density_reference,
            density_selected_mask=ion_density_selected_mask,
        )

        if self.ion_dirline_btn.isChecked():
            lim_x = self.ax_scatter_i.get_xlim()
            lim_y = self.ax_scatter_i.get_ylim()
            self.ax_scatter_i.set_autoscalex_on(False)
            self.ax_scatter_i.set_autoscaley_on(False)
            self._draw_ion_main_direction_line(ion_show[:, :2] if ion_show.size else np.empty((0, 2)))
            self.ax_scatter_i.set_xlim(lim_x[0], lim_x[1], auto=False)
            self.ax_scatter_i.set_ylim(lim_y[0], lim_y[1], auto=False)
        else:
            self._draw_ion_main_direction_line(np.empty((0, 2)))

        if ion_show.shape[0] > plotted_i:
            self.ax_scatter_i.text(
                0.01,
                0.99,
                f"Plotted {plotted_i}/{ion_show.shape[0]}",
                transform=self.ax_scatter_i.transAxes,
                ha="left",
                va="top",
            )

        if preserve_view:
            self._restore_axis_view_state(self.ax_scatter_i, i_view, keep_square=False)

        safe_ion_overlay = self._prepare_ion_overlay_for_safe_redraw()
        self._add_subplot_save_markers()
        axes_to_draw = [self.ax_scatter_i]
        if self.ion_scatter_colorbar is not None:
            axes_to_draw.append(getattr(self.ion_scatter_colorbar, "ax", None))
        self._draw_axes_immediate(axes_to_draw, include_tight=True, force_full=force_full_draw)
        self._capture_scatter_blit_backgrounds(electron=False, ion=True)
        if not safe_ion_overlay:
            self._update_ion_overlay_only()

    def _refresh_after_circle_clear(
        self,
        *,
        refresh_scatter: bool,
        refresh_ion_scatter: bool = True,
        refresh_ion_tof_map: bool = False,
        preserve_scatter_view: bool,
        refresh_projection_panels: bool = True,
        extra_axes_to_draw: list | tuple | None = None,
    ) -> None:
        """Refresh only panels affected after clearing centered/reconstruction results."""
        if not self._has_pairs():
            if self._has_session_subplot_previews():
                self._refresh_plots()
                return
            self._draw_placeholder()
            return

        e_view = self._capture_axis_view_state(self.ax_scatter_e) if preserve_scatter_view else None
        i_view = self._capture_axis_view_state(self.ax_scatter_i) if preserve_scatter_view else None
        axes_to_draw = []
        safe_ion_overlay = False
        if refresh_projection_panels:
            axes_to_draw.extend(
                [
                    self.ax_centered_bin,
                    self.ax_centered_theta_profile,
                    self.ax_reserved_top,
                    self.ax_rbasex_profile,
                ]
            )

        display_data = self._current_scatter_display_data()
        if refresh_ion_tof_map:
            coarse_mask = self._coarse_ion_roi_mask()
            if self._ion_tof_bg_subtraction_enabled():
                bg_keep = self._current_ion_tof_bg_keep_mask(show_dialog=False)
                if bg_keep.shape[0] == coarse_mask.shape[0]:
                    coarse_mask &= bg_keep
            _electron_coarse, ion_now_raw_coarse = self._paired_points(coarse_mask)
            if ion_now_raw_coarse.size:
                ion_xy_coarse = self._transform_ion_xy(ion_now_raw_coarse[:, :2], ion_now_raw_coarse[:, 2])
                ion_t_coarse = ion_now_raw_coarse[:, 2]
            else:
                ion_xy_coarse = np.empty((0, 2), dtype=np.float64)
                ion_t_coarse = np.zeros(0, dtype=np.float64)
            self._plot_ion_tof_xy_map(self.ax_ion_tof_xy, ion_xy_coarse, ion_t_coarse)
            axes_to_draw.append(self.ax_ion_tof_xy)
            if self.ion_tof_xy_colorbar is not None:
                axes_to_draw.append(getattr(self.ion_tof_xy_colorbar, "ax", None))

        if refresh_scatter:
            self._clear_circle_overlay_artists()
            electron_show = np.asarray(display_data.get("electron_show", np.empty((0, 3))), dtype=np.float64)

            plotted_e = self._plot_electron_scatter_from_display_data(display_data)

            if electron_show.shape[0] > plotted_e:
                self.ax_scatter_e.text(
                    0.01,
                    0.99,
                    f"Plotted {plotted_e}/{electron_show.shape[0]}",
                    transform=self.ax_scatter_e.transAxes,
                    ha="left",
                    va="top",
                )

            if preserve_scatter_view:
                self._restore_axis_view_state(self.ax_scatter_e, e_view, keep_square=False)

            axes_to_draw.append(self.ax_scatter_e)
            if self.electron_scatter_colorbar is not None:
                axes_to_draw.append(getattr(self.electron_scatter_colorbar, "ax", None))

            if refresh_ion_scatter:
                self._clear_ion_overlay_artists()
                ion_show = np.asarray(display_data.get("ion_show", np.empty((0, 3))), dtype=np.float64)
                ion_context = np.asarray(display_data.get("ion_context", np.empty((0, 3))), dtype=np.float64)
                ion_density_reference = np.asarray(
                    display_data.get("ion_density_reference", np.empty((0, 3))),
                    dtype=np.float64,
                )
                ion_density_selected_mask = np.asarray(
                    display_data.get("ion_density_selected_mask", np.empty(0, dtype=bool)),
                    dtype=bool,
                ).reshape(-1)
                plotted_i = self._plot_density_scatter(
                    self.ax_scatter_i,
                    ion_show,
                    "Ion Scatter",
                    cmap="inferno",
                    density_bin_size=None,
                    empty_text="No points",
                    scale_mode=self._current_ion_scatter_scale(),
                    show_colorbar=self.ion_scatter_colorbar_checkbox.isChecked(),
                    context_points=ion_context,
                    density_reference_points=ion_density_reference,
                    density_selected_mask=ion_density_selected_mask,
                )
                if self.ion_dirline_btn.isChecked():
                    lim_x = self.ax_scatter_i.get_xlim()
                    lim_y = self.ax_scatter_i.get_ylim()
                    self.ax_scatter_i.set_autoscalex_on(False)
                    self.ax_scatter_i.set_autoscaley_on(False)
                    self._draw_ion_main_direction_line(ion_show[:, :2] if ion_show.size else np.empty((0, 2)))
                    self.ax_scatter_i.set_xlim(lim_x[0], lim_x[1], auto=False)
                    self.ax_scatter_i.set_ylim(lim_y[0], lim_y[1], auto=False)
                else:
                    self._draw_ion_main_direction_line(np.empty((0, 2)))
                if ion_show.shape[0] > plotted_i:
                    self.ax_scatter_i.text(
                        0.01,
                        0.99,
                        f"Plotted {plotted_i}/{ion_show.shape[0]}",
                        transform=self.ax_scatter_i.transAxes,
                        ha="left",
                        va="top",
                    )
                if preserve_scatter_view:
                    self._restore_axis_view_state(self.ax_scatter_i, i_view, keep_square=False)
                safe_ion_overlay = self._prepare_ion_overlay_for_safe_redraw()
                axes_to_draw.append(self.ax_scatter_i)
                if self.ion_scatter_colorbar is not None:
                    axes_to_draw.append(getattr(self.ion_scatter_colorbar, "ax", None))

        if refresh_projection_panels:
            centered_bin_size = self._parse_center_bin_size(show_dialog=False)
            if centered_bin_size is None:
                centered_bin_size = DEFAULT_CENTER_BIN_SIZE
            self._plot_centered_bin_image(self.ax_centered_bin, self.centered_hist_data, centered_bin_size)
            self._plot_theta_radial_profile_panel(self.ax_centered_theta_profile, self.centered_hist_data, centered_bin_size)
            self._plot_reconstruction_panel(self.ax_reserved_top, "rBasex Recon", self.rbasex_recon_result)
            self._plot_rbasex_radial_profile(self.ax_rbasex_profile, self.rbasex_recon_result)
            if self.centered_bin_colorbar is not None:
                axes_to_draw.append(getattr(self.centered_bin_colorbar, "ax", None))
            if self.centered_bin_compare_colorbar is not None:
                axes_to_draw.append(getattr(self.centered_bin_compare_colorbar, "ax", None))

        self._add_subplot_save_markers()
        if refresh_projection_panels:
            # Placeholder <-> populated projection panels change layout enough
            # that partial blits can leave stale axis/tick pixels behind.
            self._force_full_canvas_redraw_for_layout_change(
                refresh_circle_overlay=True,
                refresh_ion_overlay=bool(refresh_ion_scatter),
            )
        else:
            if isinstance(extra_axes_to_draw, (list, tuple)):
                for ax_extra in extra_axes_to_draw:
                    if ax_extra is not None:
                        axes_to_draw.append(ax_extra)
            self._draw_axes_immediate(axes_to_draw, include_tight=True)
            if refresh_scatter:
                self._capture_scatter_blit_backgrounds(
                    electron=True,
                    ion=bool(refresh_ion_scatter),
                )
                self._update_circle_overlay_only()
                if refresh_ion_scatter and not safe_ion_overlay:
                    self._update_ion_overlay_only()

    def _current_electron_scatter_scale(self) -> str:
        """Return electron-scatter color scale mode."""
        mode = (
            self.electron_scatter_scale_combo.currentData()
            if hasattr(self, "electron_scatter_scale_combo")
            else "linear"
        )
        if isinstance(mode, str):
            return mode
        return "linear"

    def _current_electron_filter_mode(self) -> str:
        """Return electron pre-filter mode: `spatial` or `density`."""
        mode = (
            self.electron_filter_mode_combo.currentData()
            if hasattr(self, "electron_filter_mode_combo")
            else "spatial"
        )
        if isinstance(mode, str) and mode == "density":
            return "density"
        return "spatial"

    def _current_ion_filter_mode(self) -> str:
        """Return ion scatter-filter mode: `spatial`, `density`, or `both`."""
        mode = self.ion_filter_mode_combo.currentData() if hasattr(self, "ion_filter_mode_combo") else "spatial"
        if isinstance(mode, str) and mode in {"density", "both"}:
            return str(mode)
        return "spatial"

    @staticmethod
    def _ion_filter_mode_uses_spatial(mode: str) -> bool:
        """Return whether one ion-filter mode includes the spatial rectangle stage."""
        return str(mode).lower() in {"spatial", "both"}

    @staticmethod
    def _ion_filter_mode_uses_density(mode: str) -> bool:
        """Return whether one ion-filter mode includes the point-density stage."""
        return str(mode).lower() in {"density", "both"}

    @staticmethod
    def _ion_filter_mode_label(mode: str) -> str:
        """Return one user-facing label for the active ion-filter mode."""
        mode_key = str(mode).lower()
        if mode_key == "density":
            return "point density"
        if mode_key == "both":
            return "point density -> spatial"
        return "spatial distribution"

    def _parse_density_keep_percent(
        self,
        edit: QLineEdit,
        *,
        label: str,
        show_dialog: bool,
        default_percent: float = 100.0,
    ) -> tuple[bool, float]:
        """Parse density keep percent in [0, 100] from one line edit."""
        text = edit.text().strip() if edit is not None else ""
        if text == "":
            return True, float(default_percent)
        try:
            value = float(text)
            if (not np.isfinite(value)) or value < 0.0 or value > 100.0:
                raise ValueError
            return True, float(value)
        except Exception:
            if show_dialog:
                QMessageBox.warning(
                    self,
                    f"Invalid {label}",
                    f"{label} must be a number in [0, 100].",
                )
                return False, float(default_percent)
            return False, float(default_percent)

    def _parse_density_bin_size(
        self,
        edit: QLineEdit,
        *,
        label: str,
        show_dialog: bool,
    ) -> tuple[bool, float | None]:
        """Parse optional positive density-bin size from one line edit."""
        text = edit.text().strip() if edit is not None else ""
        if text == "":
            return True, None
        try:
            value = float(text)
            if (not np.isfinite(value)) or value <= 0.0:
                raise ValueError
            return True, float(value)
        except Exception:
            if show_dialog:
                QMessageBox.warning(
                    self,
                    f"Invalid {label}",
                    f"{label} must be a positive number or blank (auto).",
                )
                return False, None
            return False, None

    def _parse_density_remove_count(
        self,
        edit: QLineEdit,
        *,
        label: str,
        show_dialog: bool,
    ) -> tuple[bool, int]:
        """Parse optional non-negative integer count of lowest-density points to remove."""
        text = edit.text().strip() if edit is not None else ""
        if text == "":
            return True, 0
        try:
            value = float(text)
            if (not np.isfinite(value)) or value < 0.0 or abs(value - round(value)) > 1e-9:
                raise ValueError
            return True, max(int(round(value)), 0)
        except Exception:
            if show_dialog:
                QMessageBox.warning(
                    self,
                    f"Invalid {label}",
                    f"{label} must be a non-negative integer or blank.",
                )
                return False, 0
            return False, 0

    @staticmethod
    def _density_top_keep_mask(density: np.ndarray, keep_percent: float) -> np.ndarray:
        """Return mask keeping top `keep_percent` points by per-point density score."""
        dens = np.asarray(density, dtype=np.float64).reshape(-1)
        n = dens.size
        if n == 0:
            return np.zeros(0, dtype=bool)
        if keep_percent >= 100.0:
            return np.ones(n, dtype=bool)
        if keep_percent <= 0.0:
            return np.zeros(n, dtype=bool)
        n_keep = int(np.ceil((float(keep_percent) / 100.0) * n))
        n_keep = max(1, min(n, n_keep))
        order = np.argsort(dens, kind="stable")
        mask = np.zeros(n, dtype=bool)
        mask[order[-n_keep:]] = True
        return mask

    @staticmethod
    def _density_remove_low_mask(density: np.ndarray, remove_count: int) -> np.ndarray:
        """Return mask removing exactly `remove_count` lowest-density points."""
        dens = np.asarray(density, dtype=np.float64).reshape(-1)
        n = dens.size
        if n == 0:
            return np.zeros(0, dtype=bool)
        if remove_count <= 0:
            return np.ones(n, dtype=bool)
        if remove_count >= n:
            return np.zeros(n, dtype=bool)
        order = np.argsort(dens, kind="stable")
        mask = np.ones(n, dtype=bool)
        mask[order[: int(remove_count)]] = False
        return mask

    def _density_filter_mask(
        self,
        points_xy: np.ndarray,
        *,
        keep_percent: float,
        bin_size: float | None,
        remove_low_count: int = 0,
    ) -> np.ndarray:
        """Compute per-point keep mask using local 2D density."""
        pts = np.asarray(points_xy, dtype=np.float64)
        if pts.ndim != 2 or pts.shape[0] == 0 or pts.shape[1] < 2:
            return np.zeros(0, dtype=bool)
        x = np.asarray(pts[:, 0], dtype=np.float64).reshape(-1)
        y = np.asarray(pts[:, 1], dtype=np.float64).reshape(-1)
        finite = np.isfinite(x) & np.isfinite(y)
        if not np.any(finite):
            return np.zeros(pts.shape[0], dtype=bool)
        density = density_counts_from_bins(
            x[finite].astype(np.float32, copy=False),
            y[finite].astype(np.float32, copy=False),
            bin_size=bin_size,
        )
        keep_local = self._density_top_keep_mask(density, keep_percent)
        if int(remove_low_count) > 0:
            keep_local &= self._density_remove_low_mask(density, int(remove_low_count))
        keep = np.zeros(pts.shape[0], dtype=bool)
        keep[np.flatnonzero(finite)] = keep_local
        return keep

    def _ion_density_filter_settings(self, *, show_dialog: bool) -> tuple[bool, float, float | None, int]:
        """Return `(ok, keep_percent, bin_size, remove_count)` for ion density filtering."""
        keep_ok, keep_percent = self._parse_density_keep_percent(
            getattr(self, "ion_density_keep_edit", None),
            label="Ion density keep (%)",
            show_dialog=show_dialog,
        )
        bin_ok, bin_size = self._parse_density_bin_size(
            getattr(self, "ion_density_bin_edit", None),
            label="Ion density bin",
            show_dialog=show_dialog,
        )
        remove_ok, remove_count = self._parse_density_remove_count(
            getattr(self, "ion_density_remove_edit", None),
            label="Ion density remove M",
            show_dialog=show_dialog,
        )
        return bool(keep_ok and bin_ok and remove_ok), float(keep_percent), bin_size, int(remove_count)

    def _ion_density_keep_mask_for_points(self, points_xy: np.ndarray, *, show_dialog: bool) -> np.ndarray | None:
        """Return the current ion point-density keep mask for one set of view-space points."""
        ok_density, keep_percent, bin_size, remove_count = self._ion_density_filter_settings(show_dialog=show_dialog)
        if not ok_density:
            return None
        return self._density_filter_mask(
            np.asarray(points_xy, dtype=np.float64),
            keep_percent=keep_percent,
            bin_size=bin_size,
            remove_low_count=remove_count,
        )

    def _electron_density_filter_settings(self, *, show_dialog: bool) -> tuple[bool, float, float | None]:
        """Return `(ok, keep_percent, bin_size)` for electron density filtering."""
        keep_ok, keep_percent = self._parse_density_keep_percent(
            getattr(self, "electron_density_keep_edit", None),
            label="Electron density keep (%)",
            show_dialog=show_dialog,
        )
        bin_ok, bin_size = self._parse_density_bin_size(
            getattr(self, "electron_density_bin_edit", None),
            label="Electron density bin",
            show_dialog=show_dialog,
        )
        return bool(keep_ok and bin_ok), float(keep_percent), bin_size

    def _scatter_display_row_indices(self, selected_mask: np.ndarray) -> tuple[np.ndarray, int]:
        """Return sampled paired-row indices for fast scatter display refreshes."""
        mask = np.asarray(selected_mask, dtype=bool).reshape(-1)
        selected_count = int(mask.sum())
        if selected_count <= 0:
            return np.zeros(0, dtype=np.int64), 0
        if selected_count == mask.size:
            rows = self._uniform_subsample_indices(selected_count, MAX_SCATTER_SOURCE_POINTS)
            return rows, selected_count
        selected_rows = np.flatnonzero(mask)
        if selected_rows.size <= MAX_SCATTER_SOURCE_POINTS:
            return selected_rows.astype(np.int64, copy=False), selected_count
        sample_pos = self._uniform_subsample_indices(selected_rows.size, MAX_SCATTER_SOURCE_POINTS)
        return selected_rows[sample_pos].astype(np.int64, copy=False), selected_count

    def _exact_ion_filter_display_sample(
        self,
        selected_mask: np.ndarray,
        *,
        ion_filter_mode: str,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray] | None:
        """Sample scatter-display rows only after the full ion filter has been evaluated.

        Density-mode ion filtering depends on the full point cloud. Sampling first
        and filtering later can show the wrong kept/context points in the ion
        scatter panel compared with the actual ion filter used elsewhere.
        """
        if self.cache is None:
            return None
        mask = np.asarray(selected_mask, dtype=bool).reshape(-1)
        paired_n = self._paired_count()
        if mask.size != paired_n or paired_n <= 0 or (not np.any(mask)):
            return None
        selected_lookup_e_idx_full = np.asarray(self.paired_lookup_e_idx[mask], dtype=np.int64).reshape(-1)
        selected_lookup_i_idx_full = np.asarray(self.paired_lookup_i_idx[mask], dtype=np.int64).reshape(-1)
        if selected_lookup_e_idx_full.size <= 0 or selected_lookup_e_idx_full.size != selected_lookup_i_idx_full.size:
            return None
        ion_full_raw = np.asarray(self.cache.ion_points[selected_lookup_i_idx_full], dtype=np.float64)
        ion_keep_full = self._compute_ion_filter_keep_mask(
            ion_full_raw,
            ion_filter_mode=ion_filter_mode,
            show_dialog=False,
        )
        if ion_keep_full is None:
            return None
        ion_keep_full = np.asarray(ion_keep_full, dtype=bool).reshape(-1)
        if ion_keep_full.size != ion_full_raw.shape[0]:
            return None
        full_count = int(selected_lookup_i_idx_full.size)
        if full_count > MAX_SCATTER_SOURCE_POINTS:
            sample_rows = self._uniform_subsample_indices(full_count, MAX_SCATTER_SOURCE_POINTS)
        else:
            sample_rows = np.arange(full_count, dtype=np.int64)
        sample_rows = np.asarray(sample_rows, dtype=np.int64).reshape(-1)
        electron_sample = np.asarray(self.cache.electron_points[selected_lookup_e_idx_full[sample_rows]], dtype=np.float64)
        ion_sample_raw = np.asarray(ion_full_raw[sample_rows], dtype=np.float64)
        lookup_i_sample = np.asarray(selected_lookup_i_idx_full[sample_rows], dtype=np.int64)
        ion_keep_sample = np.asarray(ion_keep_full[sample_rows], dtype=bool)
        return electron_sample, ion_sample_raw, lookup_i_sample, ion_keep_sample

    def _selected_pairs_version_key(
        self,
        *,
        show_dialog: bool,
        fallback_to_unfiltered_on_invalid: bool,
    ) -> tuple[object, ...]:
        """Version tuple covering every input of `_selected_pairs_after_optional_ion_filter`.

        Mirrors the `_current_scatter_display_data` key (data version, pair
        identity, ROIs, ion/electron filter state, BG keep state, TOF
        transform terms) plus the parse/fallback flags; the full-selection
        path reads the same controls but no display subsample size.
        """
        roi_coarse = None
        if self.ion_hist_x_roi is not None:
            roi_coarse = (float(self.ion_hist_x_roi[0]), float(self.ion_hist_x_roi[1]))
        roi_fine = None
        if self.ion_range is not None:
            roi_fine = (float(self.ion_range[0]), float(self.ion_range[1]))
        ion_filter_on = bool(getattr(self, "ion_filter_enable_checkbox", None) and self.ion_filter_enable_checkbox.isChecked())
        ion_filter_mode = self._current_ion_filter_mode()
        electron_filter_mode = self._current_electron_filter_mode()
        ion_filter_key = None
        if ion_filter_on:
            if self._ion_filter_mode_uses_density(ion_filter_mode):
                ion_filter_key = (
                    ion_filter_mode,
                    self.ion_density_keep_edit.text().strip() if hasattr(self, "ion_density_keep_edit") else "",
                    self.ion_density_bin_edit.text().strip() if hasattr(self, "ion_density_bin_edit") else "",
                    self.ion_density_remove_edit.text().strip() if hasattr(self, "ion_density_remove_edit") else "",
                )
            if self._ion_filter_mode_uses_spatial(ion_filter_mode):
                spatial_key = (
                    self.ion_filter_cx_edit.text().strip(),
                    self.ion_filter_cy_edit.text().strip(),
                    self.ion_filter_w_edit.text().strip(),
                    self.ion_filter_h_edit.text().strip(),
                )
                if ion_filter_key is None:
                    ion_filter_key = ("spatial",) + spatial_key
                else:
                    ion_filter_key = tuple(ion_filter_key) + spatial_key
            elif ion_filter_key is None:
                ion_filter_key = (
                    "spatial",
                    self.ion_filter_cx_edit.text().strip(),
                    self.ion_filter_cy_edit.text().strip(),
                    self.ion_filter_w_edit.text().strip(),
                    self.ion_filter_h_edit.text().strip(),
                )
        electron_filter_key = (
            electron_filter_mode,
            self.electron_density_keep_edit.text().strip() if hasattr(self, "electron_density_keep_edit") else "",
            self.electron_density_bin_edit.text().strip() if hasattr(self, "electron_density_bin_edit") else "",
        )
        ion_line_on = bool(getattr(self, "ion_dirline_btn", None) and self.ion_dirline_btn.isChecked())
        rot_center_key = (
            self.ion_rot_cx_edit.text().strip() if hasattr(self, "ion_rot_cx_edit") else "",
            self.ion_rot_cy_edit.text().strip() if hasattr(self, "ion_rot_cy_edit") else "",
        )
        ion_tof_bg_key = (
            bool(self._ion_tof_bg_subtraction_enabled()),
            self._ion_tof_bg_box_state_key(),
            self._ion_tof_bg_model_cache_key,
        )
        shift_xy = np.asarray(getattr(self, "ion_peak_shift_xy", np.array([0.0, 0.0], dtype=np.float64)), dtype=np.float64).reshape(-1)
        shift_key = (
            float(shift_xy[0]) if shift_xy.size > 0 and np.isfinite(shift_xy[0]) else 0.0,
            float(shift_xy[1]) if shift_xy.size > 1 and np.isfinite(shift_xy[1]) else 0.0,
        )
        return (
            int(self._ion_hist_data_version),
            id(self.cache.ion_points) if self.cache is not None else 0,
            id(self.paired_lookup_i_idx),
            int(self._paired_count()),
            roi_coarse,
            roi_fine,
            ion_filter_on,
            ion_filter_mode,
            electron_filter_mode,
            ion_filter_key,
            electron_filter_key,
            ion_line_on,
            ion_tof_bg_key,
            float(self.ion_user_rotation_deg),
            rot_center_key,
            shift_key,
            self._ion_tof_alignment_cache_key(),
            self._ion_scatter_tof_center_cache_key(),
            bool(show_dialog),
            bool(fallback_to_unfiltered_on_invalid),
        )

    def _selected_pairs_after_optional_ion_filter(
        self,
        *,
        show_dialog: bool,
        fallback_to_unfiltered_on_invalid: bool,
    ) -> dict[str, object] | None:
        """Return current ion-hist selection with optional ion/electron scatter filtering applied.

        Memoized on `_selected_pairs_version_key`: repeated calls with
        unchanged selection/filters/data reuse the previous result instead of
        re-running the full filtering pass. Only successful results are
        cached, so failed parses keep raising their dialogs on every attempt.
        """
        cache_key = self._selected_pairs_version_key(
            show_dialog=show_dialog,
            fallback_to_unfiltered_on_invalid=fallback_to_unfiltered_on_invalid,
        )
        if cache_key == self._selected_pairs_cache_key and isinstance(self._selected_pairs_cache_data, dict):
            return self._selected_pairs_cache_data

        selected = self._compute_selected_pairs_after_optional_ion_filter(
            show_dialog=show_dialog,
            fallback_to_unfiltered_on_invalid=fallback_to_unfiltered_on_invalid,
        )
        if selected is not None:
            self._selected_pairs_cache_key = cache_key
            self._selected_pairs_cache_data = selected
        return selected

    def _compute_selected_pairs_after_optional_ion_filter(
        self,
        *,
        show_dialog: bool,
        fallback_to_unfiltered_on_invalid: bool,
    ) -> dict[str, object] | None:
        """Compute the ion-hist selection with optional ion/electron scatter filtering."""
        selected_mask_raw = self._selected_mask()
        selected_mask = np.asarray(selected_mask_raw, dtype=bool).copy()
        selected_count_raw = int(selected_mask.sum())
        bg_subtraction_on = self._ion_tof_bg_subtraction_enabled()
        bg_removed_count = 0
        if bg_subtraction_on:
            selected_mask, bg_removed_count = self._apply_optional_bg_keep_to_mask(
                selected_mask,
                show_dialog=show_dialog,
            )
        selected_lookup_i_idx = self.paired_lookup_i_idx[selected_mask]
        selected_count = int(selected_mask.sum())
        electron_base, ion_base_raw = self._paired_points(selected_mask)
        ion_filter_on = bool(self.ion_filter_enable_checkbox.isChecked())
        ion_filter_mode = self._current_ion_filter_mode()
        electron_filter_mode = self._current_electron_filter_mode()

        if electron_base.shape[0] == 0:
            ion_inside = np.zeros(0, dtype=bool)
        elif ion_filter_on:
            ion_inside = self._compute_ion_filter_keep_mask(
                ion_base_raw,
                ion_filter_mode=ion_filter_mode,
                show_dialog=show_dialog,
            )
            if ion_inside is None:
                if not fallback_to_unfiltered_on_invalid:
                    return None
                self._update_ion_rotation_from_points(ion_base_raw[:, :2])
                ion_inside = np.ones(electron_base.shape[0], dtype=bool)
            else:
                ion_inside = np.asarray(ion_inside, dtype=bool).reshape(-1)
        else:
            self._update_ion_rotation_from_points(ion_base_raw[:, :2])
            ion_inside = np.ones(electron_base.shape[0], dtype=bool)

        ion_inside = np.asarray(ion_inside, dtype=bool).reshape(-1)
        if ion_inside.size != electron_base.shape[0]:
            ion_inside = np.zeros(electron_base.shape[0], dtype=bool)

        electron_after_ion = electron_base[ion_inside]
        ion_after_ion_raw = ion_base_raw[ion_inside]
        lookup_i_idx_after_ion = selected_lookup_i_idx[ion_inside]

        electron_density_on = electron_filter_mode == "density"
        electron_inside = np.ones(electron_after_ion.shape[0], dtype=bool)
        if electron_density_on and electron_after_ion.shape[0] > 0:
            ok_density, keep_percent, bin_size = self._electron_density_filter_settings(show_dialog=show_dialog)
            if not ok_density:
                if not fallback_to_unfiltered_on_invalid:
                    return None
                electron_inside = np.ones(electron_after_ion.shape[0], dtype=bool)
            else:
                electron_inside = self._density_filter_mask(
                    electron_after_ion[:, :2],
                    keep_percent=keep_percent,
                    bin_size=bin_size,
                )
            electron_inside = np.asarray(electron_inside, dtype=bool).reshape(-1)
            if electron_inside.size != electron_after_ion.shape[0]:
                electron_inside = np.zeros(electron_after_ion.shape[0], dtype=bool)

        return {
            "selected_mask_raw": selected_mask_raw,
            "selected_mask": selected_mask,
            "selected_lookup_i_idx": selected_lookup_i_idx,
            "selected_count": selected_count,
            "selected_count_raw": int(selected_count_raw),
            "bg_removed_count": int(bg_removed_count),
            "bg_subtraction_on": bool(bg_subtraction_on),
            "electron_base": electron_base,
            "ion_base_raw": ion_base_raw,
            "ion_filter_on": ion_filter_on,
            "ion_filter_mode": ion_filter_mode,
            "electron_filter_mode": electron_filter_mode,
            "electron_density_on": bool(electron_density_on),
            "ion_inside_mask": ion_inside,
            "electron_inside_mask": electron_inside,
            "electron_ion_filtered": electron_after_ion,
            "ion_ion_filtered_raw": ion_after_ion_raw,
            "lookup_i_idx_ion_filtered": lookup_i_idx_after_ion,
            "electron_filtered": electron_after_ion[electron_inside],
            "ion_filtered_raw": ion_after_ion_raw[electron_inside],
            "lookup_i_idx_filtered": lookup_i_idx_after_ion[electron_inside],
        }

    def _current_scatter_display_data(self) -> dict[str, object]:
        """Collect lightweight scatter-panel point sets for fast redraws."""
        roi_coarse = None
        if self.ion_hist_x_roi is not None:
            roi_coarse = (float(self.ion_hist_x_roi[0]), float(self.ion_hist_x_roi[1]))
        roi_fine = None
        if self.ion_range is not None:
            roi_fine = (float(self.ion_range[0]), float(self.ion_range[1]))
        ion_filter_on = bool(getattr(self, "ion_filter_enable_checkbox", None) and self.ion_filter_enable_checkbox.isChecked())
        ion_filter_mode = self._current_ion_filter_mode()
        electron_filter_mode = self._current_electron_filter_mode()
        ion_filter_key = None
        if ion_filter_on:
            if self._ion_filter_mode_uses_density(ion_filter_mode):
                ion_filter_key = (
                    ion_filter_mode,
                    self.ion_density_keep_edit.text().strip() if hasattr(self, "ion_density_keep_edit") else "",
                    self.ion_density_bin_edit.text().strip() if hasattr(self, "ion_density_bin_edit") else "",
                    self.ion_density_remove_edit.text().strip() if hasattr(self, "ion_density_remove_edit") else "",
                )
            if self._ion_filter_mode_uses_spatial(ion_filter_mode):
                spatial_key = (
                    self.ion_filter_cx_edit.text().strip(),
                    self.ion_filter_cy_edit.text().strip(),
                    self.ion_filter_w_edit.text().strip(),
                    self.ion_filter_h_edit.text().strip(),
                )
                if ion_filter_key is None:
                    ion_filter_key = ("spatial",) + spatial_key
                else:
                    ion_filter_key = tuple(ion_filter_key) + spatial_key
            elif ion_filter_key is None:
                ion_filter_key = (
                    "spatial",
                    self.ion_filter_cx_edit.text().strip(),
                    self.ion_filter_cy_edit.text().strip(),
                    self.ion_filter_w_edit.text().strip(),
                    self.ion_filter_h_edit.text().strip(),
                )
        electron_filter_key = (
            electron_filter_mode,
            self.electron_density_keep_edit.text().strip() if hasattr(self, "electron_density_keep_edit") else "",
            self.electron_density_bin_edit.text().strip() if hasattr(self, "electron_density_bin_edit") else "",
        )
        ion_line_on = bool(getattr(self, "ion_dirline_btn", None) and self.ion_dirline_btn.isChecked())
        rot_center_key = (
            self.ion_rot_cx_edit.text().strip() if hasattr(self, "ion_rot_cx_edit") else "",
            self.ion_rot_cy_edit.text().strip() if hasattr(self, "ion_rot_cy_edit") else "",
        )
        ion_tof_bg_key = (
            bool(self._ion_tof_bg_subtraction_enabled()),
            self._ion_tof_bg_box_state_key(),
            self._ion_tof_bg_model_cache_key,
        )
        shift_xy = np.asarray(getattr(self, "ion_peak_shift_xy", np.array([0.0, 0.0], dtype=np.float64)), dtype=np.float64).reshape(-1)
        shift_key = (
            float(shift_xy[0]) if shift_xy.size > 0 and np.isfinite(shift_xy[0]) else 0.0,
            float(shift_xy[1]) if shift_xy.size > 1 and np.isfinite(shift_xy[1]) else 0.0,
        )
        tof_align_key = self._ion_tof_alignment_cache_key()
        scatter_tof_center_key = self._ion_scatter_tof_center_cache_key()
        cache_key = (
            int(self._ion_hist_data_version),
            int(self._paired_count()),
            roi_coarse,
            roi_fine,
            ion_filter_on,
            ion_filter_mode,
            ion_filter_key,
            electron_filter_key,
            ion_line_on,
            ion_tof_bg_key,
            float(self.ion_user_rotation_deg),
            rot_center_key,
            shift_key,
            tof_align_key,
            scatter_tof_center_key,
            int(MAX_SCATTER_SOURCE_POINTS),
        )
        if cache_key == self._scatter_display_cache_key and isinstance(self._scatter_display_cache_data, dict):
            return self._scatter_display_cache_data

        selected_mask_raw = self._selected_mask()
        selected_mask = np.asarray(selected_mask_raw, dtype=bool).copy()
        selected_count_raw = int(np.count_nonzero(selected_mask))
        bg_subtraction_on = self._ion_tof_bg_subtraction_enabled()
        bg_removed_count = 0
        if bg_subtraction_on:
            selected_mask, bg_removed_count = self._apply_optional_bg_keep_to_mask(
                selected_mask,
                show_dialog=False,
            )
        display_rows, selected_count = self._scatter_display_row_indices(selected_mask)
        electron_base = np.empty((0, 3), dtype=np.float64)
        ion_base_raw = np.empty((0, 3), dtype=np.float64)
        display_lookup_i_idx = np.empty(0, dtype=np.int64)
        exact_ion_inside = None
        if (
            selected_count > 0
            and ion_filter_on
            and self._ion_filter_mode_uses_density(ion_filter_mode)
        ):
            exact_display_sample = self._exact_ion_filter_display_sample(
                selected_mask,
                ion_filter_mode=ion_filter_mode,
            )
            if exact_display_sample is not None:
                electron_base, ion_base_raw, display_lookup_i_idx, exact_ion_inside = exact_display_sample
        if (
            electron_base.shape[0] <= 0
            and selected_count > 0
            and display_rows.size > 0
            and self.cache is not None
            and display_rows.size <= self.paired_lookup_i_idx.shape[0]
            and display_rows.size <= self.paired_lookup_e_idx.shape[0]
        ):
            display_lookup_e_idx = np.asarray(self.paired_lookup_e_idx[display_rows], dtype=np.int64).reshape(-1)
            display_lookup_i_idx = np.asarray(self.paired_lookup_i_idx[display_rows], dtype=np.int64).reshape(-1)
            electron_base = np.asarray(self.cache.electron_points[display_lookup_e_idx], dtype=np.float64)
            ion_base_raw = np.asarray(self.cache.ion_points[display_lookup_i_idx], dtype=np.float64)

        base_count = int(electron_base.shape[0])
        electron_density_on = bool(electron_filter_mode == "density")
        ion_inside = np.ones(base_count, dtype=bool)
        if base_count > 0 and ion_filter_on:
            if exact_ion_inside is not None:
                ion_inside = np.asarray(exact_ion_inside, dtype=bool).reshape(-1)
                self._update_ion_rotation_from_points(ion_base_raw[:, :2])
            else:
                ion_mask = self._compute_ion_filter_keep_mask(
                    ion_base_raw,
                    ion_filter_mode=ion_filter_mode,
                    show_dialog=False,
                )
                if ion_mask is None:
                    self._update_ion_rotation_from_points(ion_base_raw[:, :2])
                    ion_inside = np.ones(base_count, dtype=bool)
                else:
                    ion_inside = np.asarray(ion_mask, dtype=bool).reshape(-1)
        elif base_count > 0:
            self._update_ion_rotation_from_points(ion_base_raw[:, :2])
        ion_inside = np.asarray(ion_inside, dtype=bool).reshape(-1)
        if ion_inside.size != base_count:
            ion_inside = np.zeros(base_count, dtype=bool)

        electron_after_ion = electron_base[ion_inside]
        ion_after_ion_raw = ion_base_raw[ion_inside]
        lookup_i_idx_after_ion = display_lookup_i_idx[ion_inside] if display_lookup_i_idx.shape[0] == base_count else np.empty(0, dtype=np.int64)

        electron_inside = np.ones(electron_after_ion.shape[0], dtype=bool)
        if electron_density_on and electron_after_ion.shape[0] > 0:
            ok_density, keep_percent, bin_size = self._electron_density_filter_settings(show_dialog=False)
            if ok_density:
                electron_inside = self._density_filter_mask(
                    electron_after_ion[:, :2],
                    keep_percent=keep_percent,
                    bin_size=bin_size,
                )
        electron_inside = np.asarray(electron_inside, dtype=bool).reshape(-1)
        if electron_inside.size != electron_after_ion.shape[0]:
            electron_inside = np.zeros(electron_after_ion.shape[0], dtype=bool)

        electron_show = electron_base
        electron_context = np.empty((0, 3), dtype=np.float64)
        electron_selected_mask = np.ones(base_count, dtype=bool)
        if ion_filter_on or electron_density_on:
            electron_selected_mask = np.zeros(base_count, dtype=bool)
            ion_keep_idx = np.flatnonzero(ion_inside)
            if ion_keep_idx.size > 0:
                if electron_density_on:
                    electron_selected_mask[ion_keep_idx[electron_inside]] = True
                else:
                    electron_selected_mask[ion_keep_idx] = True
            electron_show = electron_base[electron_selected_mask]
            electron_context = electron_base[~electron_selected_mask]
        electron_density_reference = electron_base
        electron_density_selected_mask = electron_selected_mask.copy()
        if electron_density_on:
            electron_density_reference = electron_after_ion
            electron_density_selected_mask = electron_inside.copy()

        ion_selected_mask = np.ones(base_count, dtype=bool)
        ion_selected_raw = ion_base_raw
        ion_context_raw = np.empty((0, 3), dtype=np.float64)
        lookup_i_idx_filtered = display_lookup_i_idx
        if ion_filter_on:
            ion_selected_mask = ion_inside.copy()
            ion_selected_raw = ion_base_raw[ion_selected_mask]
            ion_context_raw = ion_base_raw[~ion_selected_mask]
            lookup_i_idx_filtered = lookup_i_idx_after_ion

        ion_show = ion_selected_raw.copy()
        if ion_show.size:
            ion_show[:, :2] = self._transform_ion_xy_for_scatter(ion_selected_raw[:, :2], ion_selected_raw[:, 2])
            ion_t_show = ion_selected_raw[:, 2]
        else:
            ion_t_show = np.zeros(0, dtype=np.float64)
        ion_context = ion_context_raw.copy()
        if ion_context.size:
            ion_context[:, :2] = self._transform_ion_xy_for_scatter(ion_context_raw[:, :2], ion_context_raw[:, 2])
        ion_density_reference = ion_base_raw.copy()
        if ion_density_reference.size:
            ion_density_reference[:, :2] = self._transform_ion_xy_for_scatter(ion_base_raw[:, :2], ion_base_raw[:, 2])

        display_data = {
            "selected_count": int(selected_count),
            "selected_count_raw": int(selected_count_raw),
            "bg_removed_count": int(bg_removed_count),
            "bg_subtraction_on": bool(bg_subtraction_on),
            "display_sample_count": int(base_count),
            "electron_show": electron_show,
            "electron_context": electron_context,
            "electron_selected": electron_show,
            "electron_filter_active": bool(ion_filter_on or electron_density_on),
            "electron_density_reference": electron_density_reference,
            "electron_density_selected_mask": electron_density_selected_mask,
            "ion_show_raw": ion_selected_raw,
            "ion_show": ion_show,
            "ion_context_raw": ion_context_raw,
            "ion_context": ion_context,
            "ion_t_show": ion_t_show,
            "ion_selected_raw": ion_selected_raw,
            "ion_selected": ion_show,
            "ion_filter_on": ion_filter_on,
            "ion_filter_mode": ion_filter_mode,
            "electron_density_on": bool(electron_density_on),
            "ion_density_reference": ion_density_reference,
            "ion_density_selected_mask": ion_selected_mask.copy(),
            "lookup_i_idx_filtered": lookup_i_idx_filtered,
        }
        self._scatter_display_cache_key = cache_key
        self._scatter_display_cache_data = display_data
        return display_data

    def _plot_electron_scatter_from_display_data(self, display_data: dict[str, object]) -> int:
        """Draw the electron scatter/polar panel from precomputed display data."""
        electron_show = np.asarray(display_data.get("electron_show", np.empty((0, 3))), dtype=np.float64)
        electron_context = np.asarray(display_data.get("electron_context", np.empty((0, 3))), dtype=np.float64)
        electron_density_reference = np.asarray(
            display_data.get("electron_density_reference", np.empty((0, 3))),
            dtype=np.float64,
        )
        electron_density_selected_mask = np.asarray(
            display_data.get("electron_density_selected_mask", np.empty(0, dtype=bool)),
            dtype=bool,
        ).reshape(-1)
        title_xy = "Electron Scatter"
        title_polar = "Electron Scatter (polar matrix)"
        if self._electron_scatter_polar_mode_enabled():
            return self._plot_electron_polar_matrix(
                self.ax_scatter_e,
                electron_show[:, :2] if electron_show.size else np.empty((0, 2), dtype=np.float64),
                title=title_polar,
                scale_mode=self._current_electron_scatter_scale(),
                show_colorbar=self.electron_scatter_colorbar_checkbox.isChecked(),
                empty_text="No points",
                source_note=None,
            )
        plotted = self._plot_density_scatter(
            self.ax_scatter_e,
            electron_show,
            title_xy,
            cmap="inferno",
            density_bin_size=None,
            empty_text="No points",
            scale_mode=self._current_electron_scatter_scale(),
            show_colorbar=self.electron_scatter_colorbar_checkbox.isChecked(),
            context_points=electron_context,
            density_reference_points=electron_density_reference,
            density_selected_mask=electron_density_selected_mask,
        )
        return plotted

    def _electron_scatter_polar_mode_enabled(self) -> bool:
        """Return whether the electron panel is showing the polar (theta,r) matrix."""
        return bool(
            hasattr(self, "electron_scatter_polar_toggle_btn")
            and self.electron_scatter_polar_toggle_btn.isChecked()
        )

    def _sync_electron_scatter_polar_toggle_text(self) -> None:
        """Keep the polar-view toggle text aligned with its checked state."""
        if not hasattr(self, "electron_scatter_polar_toggle_btn"):
            return
        checked = bool(self.electron_scatter_polar_toggle_btn.isChecked())
        self.electron_scatter_polar_toggle_btn.setText("Show XY Scatter" if checked else "Show Polar Matrix")

    def _on_electron_scatter_polar_toggled(self, checked: bool) -> None:
        """Switch the electron scatter panel between XY and polar-matrix views."""
        self.dragging_circle = False
        self.preview_circle_center = None
        self.pending_drag_center = None
        self._sync_electron_scatter_polar_toggle_text()
        has_pairs = self._has_pairs()
        if has_pairs:
            self._refresh_electron_scatter_panel_only(preserve_view=False, draw_canvas=False)
        elif self._has_session_subplot_previews():
            self._refresh_plots()
        else:
            self._draw_placeholder()
        self._reset_toolbar_navigation_history()
        if has_pairs:
            QTimer.singleShot(
                0,
                lambda: self._force_full_canvas_redraw_for_layout_change(
                    refresh_circle_overlay=True,
                    refresh_ion_overlay=False,
                ),
            )
        self._set_status(
            "Electron scatter view switched to polar matrix (theta vs r). Left-drag vertically in the plot to create or adjust the Polar ROI."
            if checked
            else "Electron scatter view switched back to XY scatter."
        )

    def _on_center_mode_changed(self, _index: int) -> None:
        """Refresh electron scatter preview when center estimator mode changes."""
        if self._has_pairs():
            self._refresh_electron_scatter_panel_only(preserve_view=True)
        elif self._has_session_subplot_previews():
            self._refresh_plots()
        mode = self._current_center_mode()
        if mode == "polar_outermost":
            if self._electron_scatter_polar_mode_enabled():
                self._set_status(
                    "Center estimator set to polar outermost ring line (ROI-only fitting; peak curve shown in polar matrix)."
                )
            else:
                self._set_status(
                    "Center estimator set to polar outermost ring line (ROI-only fitting). "
                    "Peak curve is shown in Polar Matrix view; click 'Show Polar Matrix'."
                )
            return
        self._set_status(f"Center estimator set to {self.center_mode_combo.currentText()}.")

    def _current_ion_scatter_scale(self) -> str:
        """Return ion-scatter color scale mode."""
        mode = self.ion_scatter_scale_combo.currentData() if hasattr(self, "ion_scatter_scale_combo") else "linear"
        if isinstance(mode, str):
            return mode
        return "linear"

    def _on_electron_scatter_colorbar_toggled(self, checked: bool) -> None:
        """Show/hide electron-scatter colorbar."""
        self._refresh_electron_scatter_panel_only(preserve_view=True)
        self._set_status("Electron scatter colorbar shown." if checked else "Electron scatter colorbar hidden.")

    def _on_ion_scatter_colorbar_toggled(self, checked: bool) -> None:
        """Show/hide ion-scatter colorbar."""
        self._refresh_ion_scatter_panel_only(preserve_view=True)
        self._set_status("Ion scatter colorbar shown." if checked else "Ion scatter colorbar hidden.")

    def _on_electron_scatter_scale_changed(self, _index: int) -> None:
        """Re-render electron scatter when color scale mode changes."""
        self._refresh_electron_scatter_panel_only(preserve_view=True)
        self._set_status(f"Electron scatter scale set to {self._current_electron_scatter_scale()}.")

    def _current_polar_target_band(self) -> tuple[float | None, float | None, float | None, float | None]:
        """Return `(target_radius, target_window, r_min, r_max)` for the polar ROI."""
        if not hasattr(self, "polar_roi_rmin_edit") or not hasattr(self, "polar_roi_rmax_edit"):
            return None, None, None, None
        text_min = self.polar_roi_rmin_edit.text().strip()
        text_max = self.polar_roi_rmax_edit.text().strip()
        if text_min == "" and text_max == "":
            return None, None, None, None
        try:
            r_min = float(text_min)
            r_max = float(text_max)
        except Exception:
            return None, None, None, None
        if (not np.isfinite(r_min)) or (not np.isfinite(r_max)):
            return None, None, None, None
        lo = max(0.0, float(min(r_min, r_max)))
        hi = max(0.0, float(max(r_min, r_max)))
        if hi <= lo:
            return None, None, None, None
        target_radius = 0.5 * (lo + hi)
        target_window = max(0.5 * (hi - lo), 1e-6)
        return float(target_radius), float(target_window), float(lo), float(hi)

    def _on_polar_roi_changed(self) -> None:
        """Update manual polar ROI and refresh the electron scatter panel."""
        target_r, target_window, r_min, r_max = self._current_polar_target_band()
        if target_r is None or target_window is None or r_min is None or r_max is None:
            if hasattr(self, "polar_roi_rmin_edit") and hasattr(self, "polar_roi_rmax_edit"):
                text_min = self.polar_roi_rmin_edit.text().strip()
                text_max = self.polar_roi_rmax_edit.text().strip()
                if text_min == "" and text_max == "":
                    self._refresh_electron_scatter_panel_only(preserve_view=True)
                    self._set_status("Polar ROI reset to auto.")
                    return
            self._refresh_electron_scatter_panel_only(preserve_view=True)
            self._set_status("Polar ROI ignored until both r min and r max are valid.")
            return
        self._set_line_edit_numeric(self.polar_roi_rmin_edit, r_min, ".6g")
        self._set_line_edit_numeric(self.polar_roi_rmax_edit, r_max, ".6g")
        self._refresh_electron_scatter_panel_only(preserve_view=True)
        self._set_status(f"Polar ROI set to r=[{r_min:.6g}, {r_max:.6g}].")

    def _set_polar_roi_inputs(self, r_min: float | None, r_max: float | None) -> None:
        """Write polar ROI inputs without triggering recursive refresh loops."""
        if not hasattr(self, "polar_roi_rmin_edit") or not hasattr(self, "polar_roi_rmax_edit"):
            return
        if r_min is None or r_max is None:
            self._set_line_edit_text_silent(self.polar_roi_rmin_edit, "")
            self._set_line_edit_text_silent(self.polar_roi_rmax_edit, "")
            return
        lo = float(min(r_min, r_max))
        hi = float(max(r_min, r_max))
        self._set_line_edit_numeric(self.polar_roi_rmin_edit, lo, ".6g")
        self._set_line_edit_numeric(self.polar_roi_rmax_edit, hi, ".6g")

    def _flush_polar_roi_preview(self) -> None:
        """Apply the latest pending polar ROI drag preview overlay only."""
        if self.pending_polar_roi_band is None:
            return
        r_min, r_max = self.pending_polar_roi_band
        self.pending_polar_roi_band = None
        self._set_polar_roi_inputs(r_min, r_max)
        # Axes limits/aspect cannot change during the band drag, so the fast
        # blit path is valid mid-drag; the release path re-renders normally.
        self._update_circle_overlay_only(enforce_axis=False, fast_drag=True)

    def _on_ion_scatter_scale_changed(self, _index: int) -> None:
        """Re-render ion scatter when color scale mode changes."""
        self._refresh_ion_scatter_panel_only(preserve_view=True)
        self._set_status(f"Ion scatter scale set to {self._current_ion_scatter_scale()}.")

    def _on_centered_bin_colorbar_toggled(self, checked: bool) -> None:
        """Toggle colorbar visibility for centered electron bin image."""
        self._refresh_centered_theta_panels_only()
        self._reset_toolbar_navigation_history()
        self._set_status("Centered-bin colorbar shown." if checked else "Centered-bin colorbar hidden.")

    def _current_centered_bin_scale(self) -> str:
        """Return current display scale for centered electron bin image."""
        mode = self.centered_bin_scale_combo.currentData() if hasattr(self, "centered_bin_scale_combo") else "linear"
        if isinstance(mode, str):
            return mode
        return "linear"

    def _refresh_centered_theta_panels_only(
        self,
        *,
        force_full_draw: bool = False,
        draw_canvas: bool = True,
    ) -> None:
        """Refresh centered-bin image and centered theta-profile panels only."""
        centered_bin_size = self._parse_center_bin_size(show_dialog=False)
        if centered_bin_size is None:
            centered_bin_size = DEFAULT_CENTER_BIN_SIZE
        self._plot_centered_bin_image(self.ax_centered_bin, self.centered_hist_data, centered_bin_size)
        self._plot_theta_radial_profile_panel(self.ax_centered_theta_profile, self.centered_hist_data, centered_bin_size)
        self._add_subplot_save_markers()
        if draw_canvas:
            axes_to_draw = [self.ax_centered_bin, self.ax_centered_theta_profile]
            if self.centered_bin_colorbar is not None:
                axes_to_draw.append(getattr(self.centered_bin_colorbar, "ax", None))
            if self.centered_bin_compare_colorbar is not None:
                axes_to_draw.append(getattr(self.centered_bin_compare_colorbar, "ax", None))
            self._draw_axes_immediate(axes_to_draw, include_tight=True, force_full=force_full_draw)
            self._capture_theta_line_blit_background()
            if not self._radial_profile_is_angular_integrated():
                self._blit_theta_guides("centered")

    def _refresh_rbasex_profile_panels_only(self, *, draw_canvas: bool = True) -> None:
        """Refresh rBasex reconstruction-image panel and its radial-profile panel only."""
        self._plot_reconstruction_panel(self.ax_reserved_top, "rBasex Recon", self.rbasex_recon_result)
        self._plot_rbasex_radial_profile(self.ax_rbasex_profile, self.rbasex_recon_result)
        self._add_subplot_save_markers()
        if draw_canvas:
            axes_to_draw = [self.ax_reserved_top, self.ax_rbasex_profile]
            secondary_axis = getattr(self, "rbasex_profile_secondary_xaxis", None)
            if secondary_axis is not None:
                axes_to_draw.append(secondary_axis)
            secondary_yaxis = getattr(self, "rbasex_profile_secondary_yaxis", None)
            if secondary_yaxis is not None:
                axes_to_draw.append(secondary_yaxis)
            self._draw_axes_immediate(axes_to_draw, include_tight=True)
            self._capture_theta_line_blit_background()
            if not self._radial_profile_is_angular_integrated():
                self._blit_theta_guides("rbasex")

    def _refresh_radial_profile_axes_only(self, *, draw_canvas: bool = True) -> None:
        """Refresh only the two radial-profile curve panels."""
        centered_bin_size = self._parse_center_bin_size(show_dialog=False)
        if centered_bin_size is None:
            centered_bin_size = DEFAULT_CENTER_BIN_SIZE
        self._plot_theta_radial_profile_panel(self.ax_centered_theta_profile, self.centered_hist_data, centered_bin_size)
        self._plot_rbasex_radial_profile(self.ax_rbasex_profile, self.rbasex_recon_result)
        self._add_subplot_save_markers()
        if draw_canvas:
            axes_to_draw = [self.ax_centered_theta_profile, self.ax_rbasex_profile]
            secondary_xaxis = getattr(self, "rbasex_profile_secondary_xaxis", None)
            if secondary_xaxis is not None:
                axes_to_draw.append(secondary_xaxis)
            secondary_yaxis = getattr(self, "rbasex_profile_secondary_yaxis", None)
            if secondary_yaxis is not None:
                axes_to_draw.append(secondary_yaxis)
            self._draw_axes_immediate(axes_to_draw, include_tight=True)

    def _on_centered_bin_scale_changed(self, _index: int) -> None:
        """Re-render centered electron bin image when scale mode changes."""
        self._refresh_centered_theta_panels_only()
        self._set_status(f"Centered-bin scale set to {self._current_centered_bin_scale()}.")

    def _on_theta_profile_controls_changed(self) -> None:
        """Re-render centered-image theta profile when theta controls change."""
        theta_deg, _ = self._get_theta_profile_params()
        self._set_line_edit_numeric(self.theta_profile_theta_edit, theta_deg, ".0f")
        self._refresh_theta_profile_panels(announce=True, fast_drag=False)

    def _refresh_theta_profile_panels(self, announce: bool, fast_drag: bool = False) -> None:
        """Refresh centered image + its angle-resolved radial profile."""
        theta_deg, dtheta_deg = self._get_theta_profile_params()
        integrated = self._radial_profile_is_angular_integrated()
        _ = fast_drag
        self._refresh_centered_theta_panels_only()
        if announce:
            if integrated:
                self._set_status("Theta radial profile updated: angular integrated mode.")
            else:
                self._set_status(f"Theta radial profile updated: theta={theta_deg:.6g} deg, dTheta={dtheta_deg:.6g} deg.")

    def _on_rbasex_profile_controls_changed(self) -> None:
        """Re-render rBasex angle-resolved radial profile when theta controls change."""
        theta_deg, _ = self._get_rbasex_profile_params()
        self._set_line_edit_numeric(self.rbasex_profile_theta_edit, theta_deg, ".0f")
        self._refresh_rbasex_profile_panels(announce=True, fast_drag=False)

    def _current_rbasex_profile_x_mode(self) -> str:
        """Return the selected rBasex radial-profile x-axis mode."""
        mode = (
            self.rbasex_profile_xmode_combo.currentData()
            if hasattr(self, "rbasex_profile_xmode_combo")
            else "r"
        )
        return str(mode) if isinstance(mode, str) else "r"

    def _rbasex_profile_dual_axis_swap_enabled(self) -> bool:
        """Return whether the dual-energy axes should swap top/bottom placement."""
        return bool(
            hasattr(self, "rbasex_profile_dual_axis_swap_checkbox")
            and self.rbasex_profile_dual_axis_swap_checkbox.isChecked()
        )

    def _rbasex_profile_primary_x_mode(self, mode: str | None = None) -> str:
        """Return the bottom-axis mode used to position the rBasex radial profile curve."""
        mode_now = self._current_rbasex_profile_x_mode() if mode is None else str(mode)
        if mode_now == "both":
            return "ke" if self._rbasex_profile_dual_axis_swap_enabled() else "be"
        if mode_now in {"r", "ke", "be"}:
            return mode_now
        return "r"

    def _rbasex_profile_secondary_x_mode(self, mode: str | None = None) -> str | None:
        """Return the top-axis mode for dual-energy display, if enabled."""
        mode_now = self._current_rbasex_profile_x_mode() if mode is None else str(mode)
        if mode_now != "both":
            return None
        return "be" if self._rbasex_profile_primary_x_mode(mode_now) == "ke" else "ke"

    def _rbasex_profile_x_axis_label(self, mode: str | None = None) -> str:
        """Return the visible x-axis label for the rBasex radial profile."""
        mode_now = self._current_rbasex_profile_x_mode() if mode is None else str(mode)
        if mode_now == "both":
            mode_now = self._rbasex_profile_primary_x_mode(mode_now)
        if mode_now == "ke":
            return "Kinetic Energy (eV)"
        if mode_now == "be":
            return "Binding Energy (eV)"
        return "Radial Position (mm)"

    def _update_rbasex_profile_dual_axis_swap_affordance(self) -> None:
        """Enable the top/bottom swap checkbox only when dual-energy mode is active."""
        checkbox = getattr(self, "rbasex_profile_dual_axis_swap_checkbox", None)
        if checkbox is None:
            return
        enabled = self._current_rbasex_profile_x_mode() == "both"
        checkbox.setEnabled(enabled)
        checkbox.setToolTip(
            "Swap which energy axis is shown on the bottom."
            if enabled
            else "Available only when X axis mode is Both."
        )

    @staticmethod
    def _format_rbasex_profile_formula_text(mode: str, c: float, b: float, hv: float | None = None) -> str:
        """Format the active rBasex radial-profile energy formula for status text."""
        if str(mode) == "be":
            hv_text = "hv" if hv is None else f"{float(hv):.6g}"
            return f"BE={hv_text} - ({float(c):.6g})*r^2 - ({float(b):.6g})"
        return f"KE=({float(c):.6g})*r^2 + ({float(b):.6g})"

    def _get_rbasex_profile_dual_axis_params(
        self,
        show_dialog: bool = False,
    ) -> tuple[float, float, float] | None:
        """Return shared parameters for the dual-energy x-axis mode."""
        ke_params = self._get_rbasex_profile_ke_params(show_dialog=show_dialog)
        if ke_params is None:
            return None
        be_params = self._get_rbasex_profile_be_params(show_dialog=show_dialog)
        if be_params is None:
            return None
        hv, _, _ = be_params
        c, b = ke_params
        return float(hv), float(c), float(b)

    def _format_rbasex_profile_dual_axis_text(self, hv: float, c: float, b: float) -> str:
        """Describe the dual-energy axis arrangement for the status bar."""
        bottom_mode = self._rbasex_profile_primary_x_mode("both")
        top_mode = self._rbasex_profile_secondary_x_mode("both")
        top_label = self._rbasex_profile_x_axis_label(top_mode if top_mode is not None else "ke")
        return (
            f"bottom {self._rbasex_profile_x_axis_label(bottom_mode)}, top {top_label} "
            f"({self._format_rbasex_profile_formula_text('ke', c, b)}; "
            f"{self._format_rbasex_profile_formula_text('be', c, b, hv)})"
        )

    def _rbasex_profile_normalize_max_enabled(self) -> bool:
        """Return whether the rBasex radial profile should be normalized to max=1."""
        return bool(
            hasattr(self, "rbasex_profile_normmax_checkbox")
            and self.rbasex_profile_normmax_checkbox.isChecked()
        )

    def _get_rbasex_profile_top_space_multiplier(self, show_dialog: bool = False) -> float | None:
        """Return rBasex radial-profile top-space multiplier (>=1), with safe fallback."""
        text = (
            self.rbasex_profile_top_space_edit.text().strip()
            if hasattr(self, "rbasex_profile_top_space_edit")
            else ""
        )
        if text == "":
            self.rbasex_profile_top_space_multiplier = 1.1
            return 1.1
        val = self._try_parse_float_text(text)
        if val is None or (not np.isfinite(val)) or float(val) < 1.0:
            if show_dialog:
                QMessageBox.warning(
                    self,
                    "Invalid top space",
                    "Top space x must be a numeric value >= 1.0.",
                )
                return None
            cached = float(getattr(self, "rbasex_profile_top_space_multiplier", 1.1))
            if (not np.isfinite(cached)) or cached < 1.0:
                cached = 1.1
            return cached
        out = float(val)
        self.rbasex_profile_top_space_multiplier = out
        return out

    def _get_rbasex_profile_energy_coeffs(self, show_dialog: bool = False) -> tuple[float, float] | None:
        """Parse the shared radial-energy coefficients `c` and `b`."""
        c_text = self.rbasex_profile_ke_c_edit.text().strip() if hasattr(self, "rbasex_profile_ke_c_edit") else ""
        b_text = self.rbasex_profile_ke_b_edit.text().strip() if hasattr(self, "rbasex_profile_ke_b_edit") else ""
        c_val = self._try_parse_float_text(c_text)
        b_val = self._try_parse_float_text(b_text)
        if c_val is None or b_val is None or (not np.isfinite([c_val, b_val]).all()):
            if show_dialog:
                QMessageBox.warning(
                    self,
                    "Invalid energy conversion",
                    "rBasex energy conversion needs numeric c and b values.",
                )
            return None
        return float(c_val), float(b_val)

    def _get_rbasex_profile_ke_params(self, show_dialog: bool = False) -> tuple[float, float] | None:
        """Parse the KE conversion formula `KE = c*r^2 + b`."""
        coeffs = self._get_rbasex_profile_energy_coeffs(show_dialog=show_dialog)
        if coeffs is None:
            return None
        c, b = coeffs
        if c <= 0.0:
            if show_dialog:
                QMessageBox.warning(
                    self,
                    "Invalid KE conversion",
                    "For a stable KE axis, use c > 0 in KE = c*r^2 + b.",
                )
            return None
        return c, b

    def _get_rbasex_profile_be_params(self, show_dialog: bool = False) -> tuple[float, float, float] | None:
        """Parse the BE conversion formula `BE = hv - c*r^2 - b`."""
        coeffs = self._get_rbasex_profile_energy_coeffs(show_dialog=show_dialog)
        if coeffs is None:
            return None
        hv_text = self.rbasex_profile_hv_edit.text().strip() if hasattr(self, "rbasex_profile_hv_edit") else ""
        hv_val = self._try_parse_float_text(hv_text)
        if hv_val is None or (not np.isfinite(hv_val)):
            if show_dialog:
                QMessageBox.warning(
                    self,
                    "Invalid binding-energy conversion",
                    "Binding Energy mode needs numeric photon hv plus numeric c and b values in BE = hv - c*r^2 - b.",
                )
            return None
        c, b = coeffs
        if abs(float(c)) <= 1e-15:
            if show_dialog:
                QMessageBox.warning(
                    self,
                    "Invalid binding-energy conversion",
                    "Binding Energy mode needs c != 0 in BE = hv - c*r^2 - b.",
                )
            return None
        return float(hv_val), float(c), float(b)

    def _rbasex_profile_radius_to_display_x(
        self,
        radius_values: np.ndarray | list[float] | float,
        *,
        show_dialog: bool = False,
    ) -> np.ndarray:
        """Convert raw radius values to the currently displayed rBasex x-axis values."""
        arr = np.asarray(radius_values, dtype=np.float64)
        if arr.size == 0:
            return arr.astype(np.float64, copy=True)
        mode = self._rbasex_profile_primary_x_mode()
        if mode == "r":
            return np.array(arr, dtype=np.float64, copy=True)
        if mode == "ke":
            params = self._get_rbasex_profile_ke_params(show_dialog=show_dialog)
            if params is None:
                return np.array(arr, dtype=np.float64, copy=True)
            c, b = params
            return c * np.square(np.clip(arr, 0.0, None)) + b
        if mode == "be":
            params = self._get_rbasex_profile_be_params(show_dialog=show_dialog)
            if params is None:
                return np.array(arr, dtype=np.float64, copy=True)
            hv, c, b = params
            return hv - (c * np.square(np.clip(arr, 0.0, None))) - b
        return np.array(arr, dtype=np.float64, copy=True)

    def _rbasex_profile_xrange_inputs_present(self) -> bool:
        """Return whether user entered any manual x-range bound for the rBasex profile."""
        txt_min = self.rbasex_profile_xmin_edit.text().strip() if hasattr(self, "rbasex_profile_xmin_edit") else ""
        txt_max = self.rbasex_profile_xmax_edit.text().strip() if hasattr(self, "rbasex_profile_xmax_edit") else ""
        return bool(txt_min or txt_max)

    def _get_rbasex_profile_xrange_override(
        self,
        *,
        show_dialog: bool = False,
    ) -> tuple[float | None, float | None] | None:
        """Parse manual x-range override for rBasex profile in current x-axis units."""
        txt_min = self.rbasex_profile_xmin_edit.text().strip() if hasattr(self, "rbasex_profile_xmin_edit") else ""
        txt_max = self.rbasex_profile_xmax_edit.text().strip() if hasattr(self, "rbasex_profile_xmax_edit") else ""
        if txt_min == "" and txt_max == "":
            return None

        xmin: float | None = None
        xmax: float | None = None
        if txt_min != "":
            v = self._try_parse_float_text(txt_min)
            if v is None or not np.isfinite(v):
                if show_dialog:
                    QMessageBox.warning(self, "Invalid x range", "rBasex Profile x min must be a valid number.")
                return None
            xmin = float(v)
        if txt_max != "":
            v = self._try_parse_float_text(txt_max)
            if v is None or not np.isfinite(v):
                if show_dialog:
                    QMessageBox.warning(self, "Invalid x range", "rBasex Profile x max must be a valid number.")
                return None
            xmax = float(v)
        if xmin is not None and xmax is not None and xmax <= xmin:
            if show_dialog:
                QMessageBox.warning(self, "Invalid x range", "rBasex Profile requires x max > x min.")
            return None
        return xmin, xmax

    def _apply_rbasex_profile_xlim(
        self,
        ax,
        x_display: np.ndarray,
        *,
        fallback_half_span: float,
    ) -> None:
        """Set rBasex profile x-limits with optional user override."""
        x_arr = np.asarray(x_display, dtype=np.float64).reshape(-1)
        x_arr = x_arr[np.isfinite(x_arr)]
        if x_arr.size == 0:
            return

        auto_lo = float(np.min(x_arr))
        auto_hi = float(np.max(x_arr))
        if abs(auto_hi - auto_lo) <= 1e-12:
            half = max(float(fallback_half_span), abs(auto_lo) * 0.02, 1e-9)
            auto_lo = float(auto_lo - half)
            auto_hi = float(auto_hi + half)

        override = self._get_rbasex_profile_xrange_override(show_dialog=False)
        if override is None:
            ax.set_xlim(auto_lo, auto_hi)
            return

        x_user_min, x_user_max = override
        lo = auto_lo if x_user_min is None else float(x_user_min)
        hi = auto_hi if x_user_max is None else float(x_user_max)
        if (not np.isfinite([lo, hi]).all()) or hi <= lo:
            ax.set_xlim(auto_lo, auto_hi)
            return
        ax.set_xlim(lo, hi)

    @staticmethod
    def _configure_rbasex_profile_xaxis(ax) -> None:
        """Keep the rBasex radial-profile x-axis readable after mode/unit changes."""
        if ax is None:
            return
        with contextlib.suppress(Exception):
            ax.xaxis.set_major_locator(MaxNLocator(nbins=6, min_n_ticks=4, prune="both"))
            ax.xaxis.set_minor_locator(AutoMinorLocator())
            ax.xaxis.labelpad = 2
            ax.tick_params(axis="x", which="major", pad=2)
            ax.tick_params(axis="x", which="minor", pad=2)

    def _clear_rbasex_profile_secondary_xaxis(self) -> None:
        """Remove any existing secondary top x-axis from the rBasex radial profile."""
        secondary_axis = getattr(self, "rbasex_profile_secondary_xaxis", None)
        if secondary_axis is None:
            return
        with contextlib.suppress(Exception):
            secondary_axis.remove()
        self.rbasex_profile_secondary_xaxis = None

    def _clear_rbasex_profile_secondary_yaxis(self) -> None:
        """Remove any existing secondary right y-axis from the rBasex radial profile."""
        secondary_axis = getattr(self, "rbasex_profile_secondary_yaxis", None)
        if secondary_axis is None:
            return
        with contextlib.suppress(Exception):
            secondary_axis.remove()
        self.rbasex_profile_secondary_yaxis = None

    def _plot_rbasex_beta_overlay(
        self,
        ax,
        x_display: np.ndarray,
        beta_values: np.ndarray,
    ):
        """Render beta(r) on a secondary right y-axis for direct integrated rBasex output."""
        self._clear_rbasex_profile_secondary_yaxis()
        x_arr = np.asarray(x_display, dtype=np.float64).reshape(-1)
        beta_arr = np.asarray(beta_values, dtype=np.float64).reshape(-1)
        valid = np.isfinite(x_arr) & np.isfinite(beta_arr)
        if not np.any(valid):
            return None
        x_arr = x_arr[valid]
        beta_arr = np.clip(beta_arr[valid], -2.0, 2.0)
        if x_arr.size <= 0:
            return None
        beta_ax = ax.twinx()
        beta_ax.set_ylabel("beta")
        beta_ax.set_ylim(-2.1, 2.1)
        beta_ax.set_yticks(np.linspace(-2.0, 2.0, 5, dtype=np.float64))
        beta_ax.yaxis.set_minor_locator(AutoMinorLocator())
        beta_ax.grid(False)
        beta_ax.patch.set_alpha(0.0)
        beta_ax.plot(x_arr, beta_arr, color="#d62728", linewidth=1.2, alpha=0.9, linestyle="--", label="beta(r)")
        self.rbasex_profile_secondary_yaxis = beta_ax
        return beta_ax

    def _rbasex_profile_active_xrange(self) -> tuple[float, float] | None:
        """Return preview or committed rBasex radial-profile x-range selection."""
        if self.dragging_rbasex_profile_range and self.pending_rbasex_profile_xrange is not None:
            return self.pending_rbasex_profile_xrange
        return self.rbasex_profile_selected_xrange

    def _rbasex_profile_range_pick_enabled(self) -> bool:
        """Return whether plot-driven rBasex range picking is currently armed."""
        btn = getattr(self, "rbasex_profile_range_pick_btn", None)
        return bool(isinstance(btn, QPushButton) and btn.isCheckable() and btn.isChecked())

    def _set_rbasex_profile_range_pick_enabled(self, enabled: bool, *, announce: bool = False) -> None:
        """Set the rBasex profile range-pick toggle without leaving stale preview state behind."""
        btn = getattr(self, "rbasex_profile_range_pick_btn", None)
        if isinstance(btn, QPushButton) and btn.isCheckable():
            was = btn.blockSignals(True)
            btn.setChecked(bool(enabled))
            btn.blockSignals(was)
        if not enabled:
            self.dragging_rbasex_profile_range = False
            self.rbasex_profile_range_drag_anchor_x = None
            self.pending_rbasex_profile_xrange = None
            if hasattr(self, "rbasex_profile_range_preview_timer") and self.rbasex_profile_range_preview_timer.isActive():
                self.rbasex_profile_range_preview_timer.stop()
        self._sync_rbasex_profile_range_label()
        if hasattr(self, "ax_rbasex_profile"):
            self._draw_rbasex_profile_range_overlay(self.ax_rbasex_profile)
            with contextlib.suppress(Exception):
                self.canvas.draw_idle()
        if announce:
            if enabled:
                self._set_status("Drag on the rBasex radial profile to select the integration range.")
            else:
                self._set_status("rBasex radial-profile range picking turned off.")

    def _on_rbasex_profile_range_pick_toggled(self, checked: bool) -> None:
        """Arm or disarm plot-driven rBasex radial-profile range picking."""
        if checked and self.rbasex_recon_result is None:
            self._set_rbasex_profile_range_pick_enabled(False, announce=False)
            self._set_status("Run Start Reconstruction first, then use 'Pick Range on Plot'.")
            return
        self._set_rbasex_profile_range_pick_enabled(bool(checked), announce=True)

    @staticmethod
    def _normalize_axis_range(x0: float, x1: float) -> tuple[float, float] | None:
        """Return sorted finite axis range, or None if it collapses."""
        vals = np.asarray([x0, x1], dtype=np.float64).reshape(-1)
        if vals.size != 2 or (not np.isfinite(vals).all()):
            return None
        low = float(min(vals[0], vals[1]))
        high = float(max(vals[0], vals[1]))
        if abs(high - low) <= 1e-12:
            return None
        return low, high

    @staticmethod
    def _centers_to_display_edges(x_centers: np.ndarray) -> np.ndarray:
        """Infer display-bin edges from sorted display-bin centers."""
        x = np.asarray(x_centers, dtype=np.float64).reshape(-1)
        if x.size <= 0:
            return np.zeros(0, dtype=np.float64)
        if x.size == 1:
            dx = max(abs(float(x[0])) * 1e-6, 1e-9)
            return np.array([float(x[0] - 0.5 * dx), float(x[0] + 0.5 * dx)], dtype=np.float64)
        mids = 0.5 * (x[:-1] + x[1:])
        edges = np.empty(x.size + 1, dtype=np.float64)
        edges[1:-1] = mids
        edges[0] = float(x[0] - (mids[0] - x[0]))
        edges[-1] = float(x[-1] + (x[-1] - mids[-1]))
        return edges

    def _snap_rbasex_profile_point_to_curve_bin(
        self,
        ax,
        *,
        x_value: float | None = None,
        pixel_xy: tuple[float, float] | None = None,
    ) -> tuple[float, int] | None:
        """Snap one profile-pick point to the nearest rendered rBasex curve bin."""
        x_disp = np.asarray(self.rbasex_profile_last_x_display, dtype=np.float64).reshape(-1)
        y_plot = np.asarray(self.rbasex_profile_last_y_plot, dtype=np.float64).reshape(-1)
        n = int(min(x_disp.size, y_plot.size))
        if n > 0:
            x_disp = x_disp[:n]
            y_plot = y_plot[:n]
            valid = np.isfinite(x_disp) & np.isfinite(y_plot)
            if np.any(valid):
                x_curve = x_disp[valid]
                y_curve = y_plot[valid]
                if (
                    ax is not None
                    and isinstance(pixel_xy, tuple)
                    and len(pixel_xy) == 2
                    and np.isfinite([pixel_xy[0], pixel_xy[1]]).all()
                ):
                    curve_px = np.zeros((0, 2), dtype=np.float64)
                    with contextlib.suppress(Exception):
                        curve_px = np.asarray(
                            ax.transData.transform(np.column_stack((x_curve, y_curve))),
                            dtype=np.float64,
                        ).reshape(-1, 2)
                    if curve_px.size > 0:
                        valid_px = np.isfinite(curve_px[:, 0]) & np.isfinite(curve_px[:, 1])
                        if np.any(valid_px):
                            x_curve = x_curve[valid_px]
                            curve_px = curve_px[valid_px]
                            dx = curve_px[:, 0] - float(pixel_xy[0])
                            dy = curve_px[:, 1] - float(pixel_xy[1])
                            idx = int(np.argmin((dx * dx) + (dy * dy)))
                            return float(x_curve[idx]), idx
                if x_value is not None and np.isfinite(float(x_value)):
                    idx = int(np.argmin(np.abs(x_curve - float(x_value))))
                    return float(x_curve[idx]), idx
        x_disp = np.asarray(self.rbasex_profile_last_x_display, dtype=np.float64).reshape(-1)
        valid_x = np.isfinite(x_disp)
        if not np.any(valid_x) or x_value is None or (not np.isfinite(float(x_value))):
            return None
        x_curve = x_disp[valid_x]
        idx = int(np.argmin(np.abs(x_curve - float(x_value))))
        return float(x_curve[idx]), idx

    def _snap_rbasex_profile_xrange_to_bins(
        self,
        x0: float,
        x1: float,
    ) -> tuple[tuple[float, float], tuple[int, int]] | None:
        """Snap one selected display-x range to the nearest plotted radial-profile bins."""
        x_disp = np.asarray(self.rbasex_profile_last_x_display, dtype=np.float64).reshape(-1)
        valid = np.isfinite(x_disp)
        if int(np.count_nonzero(valid)) <= 0:
            return None
        x_disp = x_disp[valid]
        if x_disp.size <= 0 or (not np.isfinite([x0, x1]).all()):
            return None
        idx0 = int(np.argmin(np.abs(x_disp - float(x0))))
        idx1 = int(np.argmin(np.abs(x_disp - float(x1))))
        lo_idx = int(min(idx0, idx1))
        hi_idx = int(max(idx0, idx1))
        edges = self._centers_to_display_edges(x_disp)
        if edges.size != x_disp.size + 1:
            return None
        return (float(edges[lo_idx]), float(edges[hi_idx + 1])), (lo_idx, hi_idx)

    def _compute_rbasex_profile_range_stats(
        self,
        x_range: tuple[float, float] | None,
    ) -> dict[str, float | int | tuple[float, float]] | None:
        """Compute integration stats for one selected rBasex radial-profile range."""
        if x_range is None:
            return None
        norm_range = self._normalize_axis_range(float(x_range[0]), float(x_range[1]))
        if norm_range is None:
            return None
        x_disp = np.asarray(self.rbasex_profile_last_x_display, dtype=np.float64).reshape(-1)
        y_raw = np.asarray(getattr(self, "rbasex_profile_last_y_raw", np.zeros(0, dtype=np.float64))).reshape(-1)
        if y_raw.size <= 0:
            y_raw = np.asarray(getattr(self, "rbasex_profile_last_y_measure", np.zeros(0, dtype=np.float64))).reshape(-1)
        n = int(min(x_disp.size, y_raw.size))
        if n <= 0:
            return None
        x_disp = x_disp[:n]
        y_raw = y_raw[:n]
        valid = np.isfinite(x_disp) & np.isfinite(y_raw)
        if np.count_nonzero(valid) <= 0:
            return None
        x_disp = x_disp[valid]
        y_raw = y_raw[valid]
        edges = self._centers_to_display_edges(x_disp)
        if edges.size != x_disp.size + 1:
            return None
        low_req, high_req = norm_range
        lo_idx = int(np.searchsorted(edges, float(low_req), side="right") - 1)
        hi_idx = int(np.searchsorted(edges, float(high_req), side="left") - 1)
        lo_idx = max(0, min(lo_idx, x_disp.size - 1))
        hi_idx = max(0, min(hi_idx, x_disp.size - 1))
        if hi_idx < lo_idx:
            lo_idx, hi_idx = hi_idx, lo_idx
        x_sel = x_disp[lo_idx : hi_idx + 1]
        y_sel_raw = np.asarray(y_raw[lo_idx : hi_idx + 1], dtype=np.float64).reshape(-1)
        raw_sum = float(np.sum(y_sel_raw, dtype=np.float64))
        return {
            "x_range": (float(edges[lo_idx]), float(edges[hi_idx + 1])),
            "bin_count": int(x_sel.size),
            "curve_sum": raw_sum,
            "raw_sum": raw_sum,
        }

    def _sync_rbasex_profile_range_label(self) -> None:
        """Refresh the range-integration summary shown in the controls."""
        label = getattr(self, "rbasex_profile_range_label", None)
        if label is None:
            return
        stats = self.rbasex_profile_selected_stats if isinstance(self.rbasex_profile_selected_stats, dict) else None
        axis_label = str(getattr(self, "rbasex_profile_last_axis_label", "x") or "x")
        if not isinstance(stats, dict):
            if self._rbasex_profile_range_pick_enabled():
                label.setText("Drag on the radial profile\nto integrate the highlighted bins.")
            else:
                label.setText("Use 'Pick Range on Plot', then drag on the radial profile.\nSelection snaps to displayed bins.")
            return
        x_range = stats.get("x_range")
        if not (isinstance(x_range, (list, tuple)) and len(x_range) == 2):
            if self._rbasex_profile_range_pick_enabled():
                label.setText("Drag on the radial profile\nto integrate the highlighted bins.")
            else:
                label.setText("Use 'Pick Range on Plot', then drag on the radial profile.\nSelection snaps to displayed bins.")
            return
        raw_sum = float(stats.get("raw_sum", stats.get("curve_sum", 0.0)))
        label.setText(
            f"{axis_label} [{float(x_range[0]):.6g}, {float(x_range[1]):.6g}]\n"
            f"raw sum={raw_sum:.6g}, bins={int(stats.get('bin_count', 0))}"
        )

    def _clear_rbasex_profile_range_selection(self) -> None:
        """Clear the current rBasex radial-profile range selection."""
        self.dragging_rbasex_profile_range = False
        self.rbasex_profile_range_drag_anchor_x = None
        self.pending_rbasex_profile_xrange = None
        if hasattr(self, "rbasex_profile_range_preview_timer") and self.rbasex_profile_range_preview_timer.isActive():
            self.rbasex_profile_range_preview_timer.stop()
        self.rbasex_profile_selected_xrange = None
        self.rbasex_profile_selected_stats = None
        self._sync_rbasex_profile_range_label()
        if self.rbasex_recon_result is not None and hasattr(self, "ax_rbasex_profile"):
            self._plot_rbasex_radial_profile(self.ax_rbasex_profile, self.rbasex_recon_result)
            self._add_subplot_save_markers()
            self.canvas.draw_idle()
        self._set_status("rBasex radial-profile range selection cleared.")

    def _draw_rbasex_profile_range_overlay(self, ax) -> None:
        """Draw preview/committed range selection on the rBasex radial profile."""
        if ax is None:
            return
        remove_gids = {"rbasex_profile_range_span", "rbasex_profile_range_text"}
        for artist in list(getattr(ax, "patches", [])):
            if getattr(artist, "get_gid", lambda: None)() in remove_gids:
                with contextlib.suppress(Exception):
                    artist.remove()
        for artist in list(getattr(ax, "texts", [])):
            if getattr(artist, "get_gid", lambda: None)() in remove_gids:
                with contextlib.suppress(Exception):
                    artist.remove()

        active_range = self._rbasex_profile_active_xrange()
        norm_range = None if active_range is None else self._normalize_axis_range(float(active_range[0]), float(active_range[1]))
        if norm_range is None:
            return
        stats = self._compute_rbasex_profile_range_stats(norm_range)
        if not isinstance(stats, dict):
            return
        x_range = stats.get("x_range")
        if not (isinstance(x_range, (list, tuple)) and len(x_range) == 2):
            return
        low = float(x_range[0])
        high = float(x_range[1])
        span = ax.axvspan(low, high, color="#ffd166", alpha=0.18, zorder=3.8)
        span.set_gid("rbasex_profile_range_span")
        axis_label = str(getattr(self, "rbasex_profile_last_axis_label", "x") or "x")
        raw_sum = float(stats.get("raw_sum", stats.get("curve_sum", 0.0)))
        txt = self._add_axes_overlay_text(
            ax,
            0.02,
            0.98,
            (
                f"{axis_label}[{low:.6g}, {high:.6g}]\n"
                f"raw sum={raw_sum:.6g}\n"
                f"bins={int(stats.get('bin_count', 0))}"
            ),
            ha="left",
            va="top",
            fontsize=8,
            color="white",
            bbox={"boxstyle": "round", "facecolor": "black", "alpha": 0.28},
        )
        txt.set_gid("rbasex_profile_range_text")

    def _configure_rbasex_profile_secondary_xaxis(self, ax, *, hv: float, mode: str) -> None:
        """Create the synchronized top energy axis for dual-mode rBasex display."""
        self._clear_rbasex_profile_secondary_xaxis()
        if ax is None or mode not in {"ke", "be"} or not np.isfinite(hv):
            return

        def _convert(values):
            arr = np.asarray(values, dtype=np.float64)
            converted = float(hv) - arr
            if np.ndim(converted) == 0:
                return float(converted)
            return converted

        secondary_axis = ax.secondary_xaxis("top", functions=(_convert, _convert))
        secondary_axis.set_xlabel(self._rbasex_profile_x_axis_label(mode), labelpad=2)
        with contextlib.suppress(Exception):
            secondary_axis.xaxis.set_major_locator(MaxNLocator(nbins=6, min_n_ticks=4, prune="both"))
            secondary_axis.xaxis.set_minor_locator(AutoMinorLocator())
            secondary_axis.xaxis.labelpad = 2
            secondary_axis.tick_params(axis="x", which="major", pad=2)
            secondary_axis.tick_params(axis="x", which="minor", pad=2)
        self.rbasex_profile_secondary_xaxis = secondary_axis

    def _refresh_rbasex_profile_display_settings(self, status_text: str | None = None) -> None:
        """Refresh the rBasex profile after display-only controls change."""
        has_any_plot_data = (
            self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        if has_any_plot_data:
            self._refresh_rbasex_profile_panels_only(draw_canvas=False)
            self._force_full_canvas_redraw_for_layout_change()
            self._reset_toolbar_navigation_history()
        else:
            self._draw_placeholder()
        if status_text:
            self._set_status(status_text)

    def _on_rbasex_profile_xmode_changed(self, _index: int) -> None:
        """Switch the rBasex radial-profile x-axis between radial and energy modes."""
        mode = self._current_rbasex_profile_x_mode()
        self._update_rbasex_profile_dual_axis_swap_affordance()
        if mode == "ke":
            params = self._get_rbasex_profile_ke_params(show_dialog=False)
            if params is None and self._get_rbasex_profile_ke_params(show_dialog=True) is None:
                widget = getattr(self, "rbasex_profile_xmode_combo", None)
                if widget is not None:
                    was = widget.blockSignals(True)
                    idx = widget.findData("r")
                    if idx >= 0:
                        widget.setCurrentIndex(idx)
                    widget.blockSignals(was)
                self._refresh_rbasex_profile_display_settings(
                    "rBasex radial x-axis kept in radial position because KE calibration is invalid."
                )
                return
            if params is not None:
                c, b = params
                self._refresh_rbasex_profile_display_settings(
                    "rBasex radial x-axis: "
                    f"{self._rbasex_profile_x_axis_label(mode)}, "
                    f"{self._format_rbasex_profile_formula_text(mode, c, b)}."
                )
                return
        if mode == "both":
            params = self._get_rbasex_profile_dual_axis_params(show_dialog=False)
            if params is None and self._get_rbasex_profile_dual_axis_params(show_dialog=True) is None:
                widget = getattr(self, "rbasex_profile_xmode_combo", None)
                if widget is not None:
                    was = widget.blockSignals(True)
                    idx = widget.findData("r")
                    if idx >= 0:
                        widget.setCurrentIndex(idx)
                    widget.blockSignals(was)
                self._update_rbasex_profile_dual_axis_swap_affordance()
                self._refresh_rbasex_profile_display_settings(
                    "rBasex radial x-axis kept in radial position because dual-energy calibration is invalid."
                )
                return
            if params is not None:
                hv, c, b = params
                self._refresh_rbasex_profile_display_settings(
                    "rBasex radial x-axis: "
                    f"{self._format_rbasex_profile_dual_axis_text(hv, c, b)}."
                )
                return
        if mode == "be":
            params = self._get_rbasex_profile_be_params(show_dialog=False)
            if params is None and self._get_rbasex_profile_be_params(show_dialog=True) is None:
                widget = getattr(self, "rbasex_profile_xmode_combo", None)
                if widget is not None:
                    was = widget.blockSignals(True)
                    idx = widget.findData("r")
                    if idx >= 0:
                        widget.setCurrentIndex(idx)
                    widget.blockSignals(was)
                self._refresh_rbasex_profile_display_settings(
                    "rBasex radial x-axis kept in radial position because Binding Energy calibration is invalid."
                )
                return
            if params is not None:
                hv, c, b = params
                self._refresh_rbasex_profile_display_settings(
                    "rBasex radial x-axis: "
                    f"{self._rbasex_profile_x_axis_label(mode)}, "
                    f"{self._format_rbasex_profile_formula_text(mode, c, b, hv)}."
                )
                return
        self._refresh_rbasex_profile_display_settings("rBasex radial x-axis: Radial Position (mm).")

    def _on_rbasex_profile_ke_formula_changed(self) -> None:
        """Apply updated radial-energy formula when the rBasex profile uses an energy axis."""
        mode = self._current_rbasex_profile_x_mode()
        params = None
        if mode == "ke":
            params = self._get_rbasex_profile_ke_params(show_dialog=True)
        elif mode == "both":
            params = self._get_rbasex_profile_dual_axis_params(show_dialog=True)
        elif mode == "be":
            params = self._get_rbasex_profile_be_params(show_dialog=True)
        coincidence_uses_ke = self._current_ion_tof_pos_axis() == "ke"
        if mode == "ke":
            if params is None:
                if coincidence_uses_ke:
                    self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=True)
                return
            c, b = params
            self._refresh_rbasex_profile_display_settings(
                "Updated rBasex radial x-axis: "
                f"{self._rbasex_profile_x_axis_label(mode)}, "
                f"{self._format_rbasex_profile_formula_text(mode, c, b)}."
            )
            if coincidence_uses_ke:
                self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=True)
            return
        if mode == "both":
            if params is None:
                if coincidence_uses_ke:
                    self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=True)
                return
            hv, c, b = params
            self._refresh_rbasex_profile_display_settings(
                "Updated rBasex radial x-axis: "
                f"{self._format_rbasex_profile_dual_axis_text(hv, c, b)}."
            )
            if coincidence_uses_ke:
                self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=True)
            return
        if mode == "be":
            if params is None:
                if coincidence_uses_ke:
                    self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=True)
                return
            hv, c, b = params
            self._refresh_rbasex_profile_display_settings(
                "Updated rBasex radial x-axis: "
                f"{self._rbasex_profile_x_axis_label(mode)}, "
                f"{self._format_rbasex_profile_formula_text(mode, c, b, hv)}."
            )
            if coincidence_uses_ke:
                self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=True)
            return
        if coincidence_uses_ke:
            self._refresh_ion_tof_pos_panel_only(draw_canvas=True, force_full_draw=True)
        self._set_status(
            "rBasex radial energy calibration updated. Choose Radial Position, Kinetic Energy, Binding Energy, or Both for the x-axis."
        )

    def _on_rbasex_profile_convert_clicked(self) -> None:
        """Apply the currently selected rBasex radial-profile x-axis mode."""
        widget = getattr(self, "rbasex_profile_xmode_combo", None)
        if widget is None:
            return
        self._on_rbasex_profile_xmode_changed(int(widget.currentIndex()))

    def _on_rbasex_profile_dual_axis_swap_toggled(self, _checked: bool) -> None:
        """Swap the top/bottom placement of the dual-energy rBasex x-axis labels."""
        self._update_rbasex_profile_dual_axis_swap_affordance()
        if self._current_rbasex_profile_x_mode() != "both":
            return
        params = self._get_rbasex_profile_dual_axis_params(show_dialog=False)
        if params is None:
            return
        hv, c, b = params
        self._refresh_rbasex_profile_display_settings(
            "rBasex radial x-axis: "
            f"{self._format_rbasex_profile_dual_axis_text(hv, c, b)}."
        )

    def _on_rbasex_profile_normalize_toggled(self, checked: bool) -> None:
        """Toggle max-normalized display for the rBasex radial profile."""
        if checked:
            self._refresh_rbasex_profile_display_settings("rBasex radial profile normalization: max=1.")
        else:
            self._refresh_rbasex_profile_display_settings("rBasex radial profile normalization: raw intensity.")

    def _on_rbasex_profile_xrange_changed(self) -> None:
        """Apply manual x-range override for the rBasex radial profile."""
        override = self._get_rbasex_profile_xrange_override(show_dialog=True)
        if override is None and self._rbasex_profile_xrange_inputs_present():
            return
        if override is None:
            self._refresh_rbasex_profile_display_settings("rBasex radial profile x-range: auto.")
            return
        x_min, x_max = override
        x_min_text = f"{x_min:.6g}" if x_min is not None else "auto"
        x_max_text = f"{x_max:.6g}" if x_max is not None else "auto"
        self._refresh_rbasex_profile_display_settings(
            f"rBasex radial profile x-range: [{x_min_text}, {x_max_text}]"
        )

    def _on_rbasex_profile_top_space_changed(self) -> None:
        """Apply top empty-space multiplier for rBasex radial profile y-axis."""
        mult = self._get_rbasex_profile_top_space_multiplier(show_dialog=True)
        if mult is None:
            return
        self._refresh_rbasex_profile_display_settings(
            f"rBasex radial profile top space: x{mult:.6g}"
        )

    def _on_profile_radial_bin_changed(self) -> None:
        """Re-render radial profile panels when user edits radial-bin size override."""
        text = self.profile_radial_bin_edit.text().strip() if hasattr(self, "profile_radial_bin_edit") else ""
        override = self._get_profile_radial_bin_size_override(show_dialog=True)
        if override is None and text not in {"", "auto", "AUTO", "Auto"}:
            return
        has_any_plot_data = (
            self._has_pairs()
            or self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        if has_any_plot_data:
            self._refresh_radial_profile_axes_only()
        else:
            self._draw_placeholder()
        if override is None:
            self._set_status("Radial profile bin size: auto")
        else:
            self._set_status(f"Radial profile bin size: {override:.6g}")

    def _current_radial_profile_mode(self) -> str:
        """Return selected radial profile mode key."""
        mode = (
            self.radial_profile_mode_combo.currentData()
            if hasattr(self, "radial_profile_mode_combo")
            else "raw"
        )
        return str(mode) if isinstance(mode, str) else "raw"

    def _radial_profile_is_angular_integrated(self) -> bool:
        """Return whether radial profile uses full-angle (2π) integration."""
        return self._current_radial_profile_mode() == "angular_integrated"

    def _sync_radial_profile_mode_controls(self) -> None:
        """Enable/disable theta controls based on current radial profile mode."""
        enable_theta = not self._radial_profile_is_angular_integrated()
        for name in (
            "theta_profile_theta_edit",
            "theta_profile_width_edit",
            "theta_profile_apply_btn",
            "rbasex_profile_theta_edit",
            "rbasex_profile_width_edit",
            "rbasex_profile_apply_btn",
        ):
            widget = getattr(self, name, None)
            if widget is not None:
                with contextlib.suppress(Exception):
                    widget.setEnabled(enable_theta)
        if enable_theta:
            return
        # Integrated mode does not use theta guides; cancel any in-flight theta dragging.
        self.dragging_theta_source = None
        self.pending_theta_drag_source = None
        self.pending_theta_drag_xy = None
        self.pending_theta_drag_deg = None
        if hasattr(self, "theta_drag_preview_timer") and self.theta_drag_preview_timer.isActive():
            self.theta_drag_preview_timer.stop()

    def _on_radial_profile_mode_changed(self, _index: int) -> None:
        """Switch radial profile mode between theta-slice raw and full-angle integrated."""
        self._sync_radial_profile_mode_controls()
        has_any_plot_data = (
            self._has_pairs()
            or self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        if has_any_plot_data:
            self._refresh_centered_theta_panels_only(draw_canvas=False)
            self._refresh_rbasex_profile_panels_only(draw_canvas=False)
            self._force_full_canvas_redraw_for_layout_change()
        else:
            self._draw_placeholder()
        if self._radial_profile_is_angular_integrated():
            self._set_status("Radial profile mode: angular integrated (2pi). Theta guides are disabled.")
        else:
            self._set_status("Radial profile mode: raw (theta-slice).")

    def _current_radial_profile_yscale(self) -> str:
        """Return selected y-axis scale for radial profile panels."""
        mode = (
            self.radial_profile_yscale_combo.currentData()
            if hasattr(self, "radial_profile_yscale_combo")
            else "linear"
        )
        return str(mode) if isinstance(mode, str) else "linear"

    def _on_radial_profile_yscale_changed(self, _index: int) -> None:
        """Apply radial profile y-axis linear/log scale to both radial profile panels."""
        has_any_plot_data = (
            self._has_pairs()
            or self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        if has_any_plot_data:
            self._refresh_radial_profile_axes_only()
        else:
            self._draw_placeholder()
        self._set_status(f"Radial profile Y scale: {self._current_radial_profile_yscale()}.")

    def _refresh_rbasex_profile_panels(self, announce: bool, fast_drag: bool = False) -> None:
        """Refresh rBasex reconstruction panel + angle-resolved radial profile."""
        theta_deg, dtheta_deg = self._get_rbasex_profile_params()
        integrated = self._radial_profile_is_angular_integrated()
        has_any_plot_data = (
            self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
        )
        _ = fast_drag
        if has_any_plot_data:
            self._refresh_rbasex_profile_panels_only()
        else:
            self._plot_rbasex_radial_profile(self.ax_rbasex_profile, self.rbasex_recon_result)
            self._add_subplot_save_markers()
            self._draw_axes_immediate([self.ax_rbasex_profile], include_tight=True)
        if announce:
            if integrated:
                self._set_status("rBasex radial profile updated: angular integrated mode.")
            else:
                self._set_status(f"rBasex angle profile updated: theta={theta_deg:.6g} deg, dTheta={dtheta_deg:.6g} deg.")

    def _clear_colorbar_attr(self, attr_name: str, gid: str | None = None) -> None:
        """Remove a stored colorbar artist attribute (plus stale gid axes) if present."""
        colorbar = getattr(self, attr_name, None)
        if colorbar is not None:
            with contextlib.suppress(Exception):
                colorbar.remove()
        setattr(self, attr_name, None)
        if gid:
            self._remove_colorbar_axes_by_gid(gid)

    def _clear_centered_bin_colorbar(self) -> None:
        """Remove centered-bin colorbar artist if it exists."""
        self._clear_colorbar_attr("centered_bin_colorbar")
        self._clear_colorbar_attr("centered_bin_colorbar_ax")
        self._clear_colorbar_attr("centered_bin_compare_colorbar")
        self._clear_colorbar_attr("centered_bin_compare_colorbar_ax")

    def _create_centered_bin_colorbar_axis(self, side: str):
        """Create a dedicated colorbar axis near centered-bin panel without resizing it."""
        ax = getattr(self, "ax_centered_bin", None)
        if ax is None:
            return None

        pos = ax.get_position()
        y0 = float(pos.y0 + 0.06 * pos.height)
        h = float(max(0.12 * pos.height, 0.88 * pos.height))

        if side == "left":
            neighbor = getattr(self, "ax_scatter_e", None)
            neighbor_edge = float(neighbor.get_position().x1) if neighbor is not None else float(pos.x0 - 0.03)
            gap = max(float(pos.x0 - neighbor_edge), 0.010)
            width = float(np.clip(gap * 0.22, 0.0038, 0.0075))
            pad = float(np.clip(gap * 0.42, 0.0065, 0.015))
            x0 = float(pos.x0 - pad - width)
            x0 = max(0.001, x0)
        else:
            neighbor = getattr(self, "ax_reserved_top", None)
            neighbor_edge = float(neighbor.get_position().x0) if neighbor is not None else float(pos.x1 + 0.03)
            gap = max(float(neighbor_edge - pos.x1), 0.010)
            width = float(np.clip(gap * 0.22, 0.0038, 0.0075))
            pad = float(np.clip(gap * 0.34, 0.0055, 0.012))
            x0 = float(pos.x1 + pad)
            x_max = 0.999 - width
            x0 = min(max(0.001, x0), max(0.001, x_max))

        cax = self.figure.add_axes([x0, y0, width, h])
        cax.set_in_layout(False)
        return cax

    @staticmethod
    def _style_centered_bin_colorbar(colorbar, side: str) -> None:
        """Place colorbar ticks/label on the outer side to avoid overlap with image."""
        if colorbar is None:
            return
        cax = getattr(colorbar, "ax", None)
        if cax is None:
            return
        if side == "left":
            with contextlib.suppress(Exception):
                cax.yaxis.set_ticks_position("left")
                cax.yaxis.set_label_position("left")
                cax.tick_params(axis="y", left=True, right=False, labelleft=True, labelright=False, pad=2)
            return
        with contextlib.suppress(Exception):
            cax.yaxis.set_ticks_position("right")
            cax.yaxis.set_label_position("right")
            cax.tick_params(axis="y", left=False, right=True, labelleft=False, labelright=True, pad=2)

    def _clear_electron_scatter_colorbar(self) -> None:
        """Remove electron-scatter colorbar artist if it exists."""
        self._clear_colorbar_attr("electron_scatter_colorbar", "electron_scatter_colorbar")

    def _clear_ion_scatter_colorbar(self) -> None:
        """Remove ion-scatter colorbar artist if it exists."""
        self._clear_colorbar_attr("ion_scatter_colorbar", "ion_scatter_colorbar")

    def _upsert_colorbar_for_axis(self, ax, mappable, label: str, attr_name: str, gid: str):
        """Reuse the stored colorbar for one axis when possible, otherwise (re)create it."""
        colorbar = getattr(self, attr_name, None)
        if colorbar is not None and getattr(colorbar, "ax", None) in list(getattr(self.figure, "axes", [])):
            try:
                colorbar.update_normal(mappable)
                colorbar.set_label(label)
                with contextlib.suppress(Exception):
                    colorbar.ax.set_gid(gid)
                return colorbar
            except Exception:
                with contextlib.suppress(Exception):
                    colorbar.remove()
                setattr(self, attr_name, None)

        colorbar = self.figure.colorbar(mappable, ax=ax, fraction=0.046, pad=0.04)
        colorbar.set_label(label)
        with contextlib.suppress(Exception):
            colorbar.ax.set_gid(gid)
        setattr(self, attr_name, colorbar)
        return colorbar

    def _upsert_scatter_colorbar(self, ax, mappable, label: str):
        """Reuse an existing scatter colorbar when possible, otherwise create one."""
        if ax is self.ax_scatter_e:
            attr_name = "electron_scatter_colorbar"
            gid = "electron_scatter_colorbar"
        elif ax is self.ax_scatter_i:
            attr_name = "ion_scatter_colorbar"
            gid = "ion_scatter_colorbar"
        else:
            return None
        return self._upsert_colorbar_for_axis(ax, mappable, label, attr_name, gid)

    def _clear_ion_tof_xy_colorbar(self) -> None:
        """Remove ion-TOF-XY colorbar artist if it exists."""
        self._clear_colorbar_attr("ion_tof_xy_colorbar", "ion_tof_xy_colorbar")

    def _upsert_ion_tof_xy_colorbar(self, mappable, label: str):
        """Reuse the ion-coincidence colorbar when possible instead of recreating its axes."""
        return self._upsert_colorbar_for_axis(
            self.ax_ion_tof_xy,
            mappable,
            label,
            "ion_tof_xy_colorbar",
            "ion_tof_xy_colorbar",
        )

    @staticmethod
    def _ion_tof_xy_colorbar_count_ticks(max_count: float, max_ticks: int = 6) -> np.ndarray:
        """Return a compact, human-readable count tick list for the coincidence-map colorbar."""
        if (not np.isfinite(max_count)) or max_count <= 0.0:
            return np.array([0.0, 1.0], dtype=np.float64)
        upper = float(max_count)
        if upper <= float(max_ticks - 1):
            return np.arange(0.0, float(int(np.floor(upper))) + 1.0, 1.0, dtype=np.float64)

        values: set[float] = {0.0, 1.0}
        max_exp = int(np.floor(np.log10(upper)))
        for exp in range(max_exp + 1):
            scale = float(10**exp)
            for mult in (1.0, 2.0, 5.0):
                value = mult * scale
                if value <= upper * (1.0 + 1e-12):
                    values.add(float(value))
        values.add(float(np.ceil(upper)))
        ticks = np.array(sorted(values), dtype=np.float64)
        if ticks.size > max_ticks:
            idx = np.unique(np.linspace(0, ticks.size - 1, max_ticks, dtype=int))
            ticks = ticks[idx]
            ticks[0] = 0.0
            ticks[-1] = float(np.ceil(upper))
        return ticks.astype(np.float64, copy=False)

    def _configure_ion_tof_xy_colorbar(
        self,
        colorbar,
        z_scale: str,
        *,
        finite_counts: np.ndarray | None = None,
    ) -> None:
        """Refresh coincidence-map colorbar ticks after scale changes."""
        if colorbar is None:
            return
        cax = getattr(colorbar, "ax", None)
        if cax is None:
            return
        with contextlib.suppress(Exception):
            colorbar.minorticks_off()
        if str(z_scale) == "log":
            finite = np.asarray(finite_counts if finite_counts is not None else np.zeros(0), dtype=np.float64).reshape(-1)
            max_count = float(np.max(finite)) if finite.size else 0.0
            tick_counts = self._ion_tof_xy_colorbar_count_ticks(max_count, max_ticks=6)
            tick_positions = np.log1p(tick_counts)
            tick_labels = [f"{int(round(v))}" if abs(v - round(v)) <= 1e-9 else f"{v:.6g}" for v in tick_counts]
            with contextlib.suppress(Exception):
                colorbar.set_ticks(tick_positions.tolist())
                colorbar.set_ticklabels(tick_labels)
        else:
            with contextlib.suppress(Exception):
                colorbar.locator = MaxNLocator(nbins=6, min_n_ticks=3)
                colorbar.update_ticks()
        with contextlib.suppress(Exception):
            formatter = ScalarFormatter(useOffset=False)
            formatter.set_scientific(False)
            cax.yaxis.set_major_formatter(formatter)
            cax.yaxis.get_offset_text().set_visible(False)
            cax.tick_params(axis="y", which="major", labelsize=8, pad=2)
            cax.tick_params(axis="y", which="minor", left=False, right=False)

    def _remove_colorbar_axes_by_gid(self, gid: str) -> None:
        """Remove any stale colorbar axes by gid to prevent subplot-overlap artifacts."""
        if not gid:
            return
        for cax in list(getattr(self.figure, "axes", [])):
            if cax is None:
                continue
            with contextlib.suppress(Exception):
                if cax.get_gid() == gid:
                    cax.remove()

    @staticmethod
    def _wrap_angle_deg(theta_deg: float) -> float:
        """Wrap angle to [-180, 180)."""
        if not np.isfinite(theta_deg):
            return 0.0
        wrapped = float((theta_deg + 180.0) % 360.0 - 180.0)
        if wrapped >= 180.0:
            wrapped -= 360.0
        if wrapped < -180.0:
            wrapped += 360.0
        return wrapped

    @staticmethod
    def _uniform_subsample_points(points_xy: np.ndarray, max_n: int) -> np.ndarray:
        """Deterministically subsample points for fast geometric estimation."""
        pts = np.asarray(points_xy, dtype=np.float64)
        if pts.ndim != 2 or pts.shape[0] <= max_n:
            return pts
        idx = np.linspace(0, pts.shape[0] - 1, int(max_n), dtype=np.int64)
        return pts[idx]

    @staticmethod
    def _uniform_subsample_indices(count: int, max_n: int) -> np.ndarray:
        """Return deterministic row indices limited to `max_n` samples."""
        n = int(max(count, 0))
        limit = int(max(max_n, 0))
        if n <= 0 or limit <= 0:
            return np.zeros(0, dtype=np.int64)
        if n <= limit:
            return np.arange(n, dtype=np.int64)
        return np.linspace(0, n - 1, limit, dtype=np.int64)

    def _estimate_ion_peak_center(self, ion_xy: np.ndarray) -> tuple[float, float] | None:
        """Estimate densest ion-cluster center directly from scatter points."""
        if ion_xy.ndim != 2 or ion_xy.shape[0] <= 0 or ion_xy.shape[1] < 2:
            return None
        pts_full = np.asarray(ion_xy[:, :2], dtype=np.float64)
        pts = self._uniform_subsample_points(pts_full, max_n=2200)
        n = int(pts.shape[0])
        if n <= 0:
            return None
        if n == 1:
            return float(pts[0, 0]), float(pts[0, 1])

        dx = pts[:, None, 0] - pts[None, :, 0]
        dy = pts[:, None, 1] - pts[None, :, 1]
        d2 = dx * dx + dy * dy
        np.fill_diagonal(d2, np.inf)
        k = max(1, min(24, n - 1))
        kdist2 = np.partition(d2, k, axis=1)[:, k]
        peak0 = pts[int(np.argmin(kdist2))]

        # One refinement pass on full scatter: weighted mean of nearest neighbors.
        d2_full = (pts_full[:, 0] - peak0[0]) ** 2 + (pts_full[:, 1] - peak0[1]) ** 2
        nn = max(1, min(320, pts_full.shape[0]))
        nbr_idx = np.argpartition(d2_full, nn - 1)[:nn]
        nbr = pts_full[nbr_idx]
        w = 1.0 / np.maximum(d2_full[nbr_idx], 1e-12)
        wsum = float(np.sum(w))
        if wsum <= 0.0 or not np.isfinite(wsum):
            cx, cy = float(peak0[0]), float(peak0[1])
        else:
            cx = float(np.sum(w * nbr[:, 0]) / wsum)
            cy = float(np.sum(w * nbr[:, 1]) / wsum)
        if not np.isfinite([cx, cy]).all():
            return None
        return cx, cy

    def apply_ion_rotation_center_from_inputs(self) -> None:
        """Apply ion-rotation center from controls and refresh views."""
        center = self._parse_ion_rotation_center(show_dialog=True)
        if center is None:
            return
        cx, cy = center
        self.ion_peak_shift_xy = np.array([0.0, 0.0], dtype=np.float64)
        self._set_ion_rotation_center_inputs(cx, cy)
        self.ion_auto_reference_angle_deg = None
        self._clear_circle_result()
        if self._has_pairs():
            self._refresh_plots()
        else:
            self._update_ion_overlay_only()
        self._set_status(f"Ion rotation center set to ({cx:.6g}, {cy:.6g}).")

    def set_ion_rotation_center_to_peak(self) -> None:
        """Set rotation center to current ion-density peak (without moving peak to origin)."""
        if not self._has_pairs():
            QMessageBox.warning(self, "No data", "Run Process and Plot first.")
            return
        mask, _bg_removed = self._selected_mask_with_optional_bg(show_dialog=False)
        _electron_now, ion_now = self._paired_points(mask)
        if ion_now.shape[0] == 0:
            QMessageBox.warning(self, "No points", "Current ion selection contains no points.")
            return
        peak = self._estimate_ion_peak_center(ion_now[:, :2])
        if peak is None:
            QMessageBox.warning(self, "Center failed", "Unable to locate ion peak center from current selection.")
            return
        cx, cy = peak
        self.ion_peak_shift_xy = np.array([0.0, 0.0], dtype=np.float64)
        self._set_ion_rotation_center_inputs(cx, cy)
        self.ion_auto_reference_angle_deg = None
        self._clear_circle_result()
        self._refresh_plots()
        self._set_status(f"Ion rotation center set to peak at ({cx:.6g}, {cy:.6g}).")

    def center_ion_peak_to_origin(self) -> None:
        """Find densest ion peak, set rotation center to that peak, then shift peak to origin."""
        if not self._has_pairs():
            QMessageBox.warning(self, "No data", "Run Process and Plot first.")
            return
        mask, _bg_removed = self._selected_mask_with_optional_bg(show_dialog=False)
        _electron_now, ion_now = self._paired_points(mask)
        if ion_now.shape[0] == 0:
            QMessageBox.warning(self, "No points", "Current ion selection contains no points.")
            return
        peak = self._estimate_ion_peak_center(ion_now[:, :2])
        if peak is None:
            QMessageBox.warning(self, "Center failed", "Unable to locate ion peak center from current selection.")
            return
        cx, cy = peak
        self.ion_peak_shift_xy = np.array([cx, cy], dtype=np.float64)
        self._set_ion_rotation_center_inputs(0.0, 0.0)
        self.ion_auto_reference_angle_deg = None
        self._clear_circle_result()
        self._refresh_plots()
        self._set_status(
            f"Ion peak centered+rotation-reference set: peak ({cx:.6g}, {cy:.6g}) moved to (0,0); rotation center is now (0,0)."
        )

    def _ion_rotation_deg_from_xy(self, x: float, y: float) -> float | None:
        """Map ion-scatter point direction to a rotation offset based on main-direction line."""
        if not np.isfinite([x, y]).all():
            return None
        if abs(float(x)) < 1e-12 and abs(float(y)) < 1e-12:
            return None
        angle = float(np.degrees(np.arctan2(y, x)))
        angle = self._wrap_angle_deg(self._snap_theta_deg(angle))
        if self.dragging_ion_rotation and self.ion_rotation_drag_base_main_angle_deg is not None:
            main_angle = float(self.ion_rotation_drag_base_main_angle_deg)
            manual_now = float(self.ion_rotation_drag_start_manual_deg)
        else:
            main_angle = float(self.ion_main_axis_angle_deg) if self.ion_main_axis_angle_deg is not None else 0.0
            manual_now = float(self.ion_user_rotation_deg)
        reference_angle = self._wrap_angle_deg(main_angle - manual_now)
        return self._wrap_angle_deg(angle - reference_angle)

    def _apply_ion_rotation_deg(self, angle_deg: float, announce: bool = True) -> bool:
        """Apply ion manual rotation offset and refresh plots."""
        if not np.isfinite(angle_deg):
            return False
        if not self.ion_dirline_btn.isChecked():
            if announce:
                self._set_status("Enable 'Show Main Direction Line' before rotating ion scatter.")
            return False
        if self._has_pairs() and self.ion_main_axis_angle_deg is None:
            if announce:
                self._set_status("Main-direction angle is unavailable for current ion data; rotation is locked.")
            return False
        angle_deg = self._wrap_angle_deg(float(angle_deg))
        self.ion_user_rotation_deg = angle_deg
        self._set_line_edit_numeric(self.ion_rot_offset_edit, angle_deg, ".6g")
        if self._has_pairs():
            self._clear_circle_result()
            self._refresh_plots()
        else:
            self._update_ion_overlay_only()
        if announce:
            self._set_status(f"Ion rotation offset set to {angle_deg:.6g} deg.")
        return True

    def apply_ion_rotation_offset(self) -> None:
        """Apply user-entered extra rotation (degrees) for ion scatter display."""
        try:
            offset = float(self.ion_rot_offset_edit.text().strip())
        except Exception:
            QMessageBox.warning(self, "Invalid rotation", "Ion rotation offset must be a valid number (degrees).")
            return
        self._apply_ion_rotation_deg(offset, announce=True)

    def _on_toggle_ion_direction_line(self, checked: bool) -> None:
        """Show or hide the ion main-direction reference line."""
        if not checked:
            self.dragging_ion_rotation = False
            self.pending_ion_rotation_deg = None
            self.ion_auto_reference_angle_deg = None
            self._clear_ion_rotation_drag_preview_state(restore_preview=False)
            self._clear_ion_main_direction_artists()
        else:
            self.ion_auto_reference_angle_deg = None
        status = (
            "Ion main-direction line enabled. Rotation controls unlocked."
            if checked
            else "Ion main-direction line disabled. Rotation controls locked."
        )
        if self._has_pairs():
            self._refresh_plots()
        else:
            self._update_ion_overlay_only()
        self._set_status(status)

    def _clear_ion_main_direction_artists(self) -> None:
        """Remove ion main-direction line artists from the axis."""
        if self.ion_main_axis_line is not None:
            with contextlib.suppress(Exception):
                self.ion_main_axis_line.remove()
            self.ion_main_axis_line = None
        self.ion_main_axis_marker = None
        self.ion_main_axis_angle_deg = None

    def _estimate_ion_high_gradient_direction(
        self, ion_points: np.ndarray
    ) -> tuple[float, float, np.ndarray, float] | None:
        """Estimate ion main direction from scatter points around the density peak."""
        if ion_points.shape[0] < 8:
            return None
        pts_full = np.asarray(ion_points[:, :2], dtype=np.float64)
        peak = self._estimate_ion_peak_center(pts_full)
        if peak is None:
            return None
        cx, cy = float(peak[0]), float(peak[1])

        pts = self._uniform_subsample_points(pts_full, max_n=5000)
        dxy = pts - np.array([cx, cy], dtype=np.float64)
        r2 = dxy[:, 0] * dxy[:, 0] + dxy[:, 1] * dxy[:, 1]
        valid = np.isfinite(r2)
        if not np.any(valid):
            return None
        dxy = dxy[valid]
        r2 = r2[valid]
        if dxy.shape[0] < 6:
            return None

        # Focus on local cloud around peak; this approximates strongest density-change orientation.
        cut = float(np.percentile(r2, 35.0)) if r2.size > 4 else float(np.max(r2))
        cut = max(cut, 1e-12)
        local = r2 <= cut
        if int(np.count_nonzero(local)) >= 6:
            dxy = dxy[local]
            r2 = r2[local]

        sigma2 = max(float(np.percentile(r2, 60.0)) if r2.size > 4 else float(np.max(r2)), 1e-12)
        w = np.exp(-0.5 * r2 / sigma2)
        sw = float(np.sum(w))
        if sw <= 1e-12 or not np.isfinite(sw):
            return None
        mx = float(np.sum(w * dxy[:, 0]) / sw)
        my = float(np.sum(w * dxy[:, 1]) / sw)
        ux = dxy[:, 0] - mx
        uy = dxy[:, 1] - my
        cxx = float(np.sum(w * ux * ux) / sw)
        cxy = float(np.sum(w * ux * uy) / sw)
        cyy = float(np.sum(w * uy * uy) / sw)
        cov = np.array([[cxx, cxy], [cxy, cyy]], dtype=np.float64)
        if not np.isfinite(cov).all():
            return None
        evals, evecs = np.linalg.eigh(cov)
        direction = evecs[:, int(np.argmax(evals))]
        norm = float(np.hypot(direction[0], direction[1]))
        if norm <= 1e-12:
            return None
        direction = direction / norm

        theta = float(np.arctan2(direction[1], direction[0]))
        if theta > 0.5 * np.pi:
            theta -= np.pi
        elif theta <= -0.5 * np.pi:
            theta += np.pi
        direction = np.array([np.cos(theta), np.sin(theta)], dtype=np.float64)
        angle_deg = float(np.degrees(theta))
        return float(cx), float(cy), direction, angle_deg

    def _draw_ion_main_direction_line(self, ion_points: np.ndarray) -> None:
        """Estimate and draw ion highest-gradient direction through highest-density region."""
        if not self.ion_dirline_btn.isChecked():
            self._clear_ion_main_direction_artists()
            return
        estimated = self._estimate_ion_high_gradient_direction(ion_points)
        if estimated is None:
            self._clear_ion_main_direction_artists()
            return
        cx, cy, direction, angle_deg = estimated
        self.ion_main_axis_angle_deg = angle_deg

        x0, x1 = self.ax_scatter_i.get_xlim()
        y0, y1 = self.ax_scatter_i.get_ylim()
        span = max(abs(x1 - x0), abs(y1 - y0), 1e-9)
        t = 1.6 * span
        x_line = np.array([cx - direction[0] * t, cx + direction[0] * t], dtype=np.float64)
        y_line = np.array([cy - direction[1] * t, cy + direction[1] * t], dtype=np.float64)

        if self.ion_main_axis_line is None or self.ion_main_axis_line.axes is not self.ax_scatter_i:
            (self.ion_main_axis_line,) = self.ax_scatter_i.plot(
                x_line,
                y_line,
                color="#00e5ff",
                linewidth=1.6,
                alpha=0.9,
                zorder=6,
                scalex=False,
                scaley=False,
            )
            self.ion_main_axis_line.set_gid("ion_main_axis_line")
        else:
            self.ion_main_axis_line.set_data(x_line, y_line)

    def _compute_ion_rotation(self, ion_xy: np.ndarray) -> tuple[np.ndarray, float]:
        """Compute rotation matrix that aligns ion main-direction line to horizontal."""
        estimated = self._estimate_ion_high_gradient_direction(ion_xy)
        if estimated is None:
            return np.eye(2, dtype=np.float64), 0.0
        _cx, _cy, _direction, angle_deg = estimated
        theta = float(np.deg2rad(angle_deg))
        alpha = -theta
        c, s = float(np.cos(alpha)), float(np.sin(alpha))
        rot = np.array([[c, -s], [s, c]], dtype=np.float64)
        # One refinement pass: re-estimate after first rotation and correct residual tilt.
        with contextlib.suppress(Exception):
            transformed = ion_xy @ rot.T
            residual = self._estimate_ion_high_gradient_direction(transformed)
            if residual is not None:
                _cx2, _cy2, _dir2, residual_deg = residual
                residual_deg = self._wrap_angle_deg(float(residual_deg))
                if abs(residual_deg) > 1e-6:
                    ar = -np.deg2rad(residual_deg)
                    cr, sr = float(np.cos(ar)), float(np.sin(ar))
                    rot_res = np.array([[cr, -sr], [sr, cr]], dtype=np.float64)
                    rot = rot_res @ rot
                    angle_deg = self._wrap_angle_deg(float(angle_deg) + residual_deg)
        return rot, float(angle_deg)

    def _update_ion_rotation_from_points(self, ion_xy: np.ndarray) -> None:
        """Update ion rotation from current manual offset only (line must be ON)."""
        _ = ion_xy
        center_input = self._parse_ion_rotation_center(show_dialog=False)
        if center_input is None:
            center_input = (0.0, 0.0)

        line_on = self.ion_dirline_btn.isChecked()
        rot_auto = np.eye(2, dtype=np.float64)
        auto_angle_deg = 0.0
        center_eff = (float(center_input[0]), float(center_input[1]))
        self.ion_auto_reference_angle_deg = None

        user_angle_deg = float(self.ion_user_rotation_deg) if line_on else 0.0
        a = np.deg2rad(user_angle_deg)
        c, s = float(np.cos(a)), float(np.sin(a))
        rot_user = np.array([[c, -s], [s, c]], dtype=np.float64)

        self.ion_auto_angle_deg = auto_angle_deg
        self.ion_rotation_center_effective_xy = np.array([center_eff[0], center_eff[1]], dtype=np.float64)
        self.ion_rotation_matrix = rot_user @ rot_auto
        self.ion_rotation_angle_deg = auto_angle_deg + user_angle_deg

    def _transform_ion_xy(self, ion_xy: np.ndarray, ion_t: np.ndarray | None = None) -> np.ndarray:
        """Apply current ion shift/rotation and active XY-TOF alignment to XY points.

        Order is fixed and shared by all callers: subtract peak shift ->
        rotate about the effective center -> apply the per-axis linear TOF
        alignment `-(slope*t + intercept)` in the rotated frame. Because the
        alignment is applied after rotation, a refit is required after the
        rotation angle changes; the shared helpers
        (`_apply_ion_tof_terms_to_xy`, `_ion_tof_display_coord_values`) keep
        this ordering consistent across all panels.
        """
        if ion_xy.size == 0:
            return ion_xy.copy()
        shift_xy = np.asarray(self.ion_peak_shift_xy, dtype=np.float64).reshape(-1)
        if shift_xy.size < 2 or (not np.isfinite(shift_xy[:2]).all()):
            shift_xy = np.array([0.0, 0.0], dtype=np.float64)
        else:
            shift_xy = np.array([float(shift_xy[0]), float(shift_xy[1])], dtype=np.float64)
        center_eff = np.asarray(self.ion_rotation_center_effective_xy, dtype=np.float64).reshape(-1)
        if center_eff.size < 2 or (not np.isfinite(center_eff[:2]).all()):
            center = self._parse_ion_rotation_center(show_dialog=False)
            if center is None:
                center = (0.0, 0.0)
            center_eff = np.array([float(center[0]), float(center[1])], dtype=np.float64)
        else:
            center_eff = np.array([float(center_eff[0]), float(center_eff[1])], dtype=np.float64)

        pts = ion_xy.astype(np.float64, copy=True)
        pts[:, 0] -= shift_xy[0]
        pts[:, 1] -= shift_xy[1]
        pts[:, 0] -= center_eff[0]
        pts[:, 1] -= center_eff[1]
        pts = pts @ self.ion_rotation_matrix.T
        pts[:, 0] += center_eff[0]
        pts[:, 1] += center_eff[1]
        if ion_t is not None:
            pts = self._apply_ion_tof_alignment_to_xy(pts, ion_t)
        return pts

    def _transform_ion_xy_for_scatter(self, ion_xy: np.ndarray, ion_t: np.ndarray | None = None) -> np.ndarray:
        """Apply ion transforms plus temporary scatter-only TOF centering."""
        pts = self._transform_ion_xy(ion_xy, ion_t)
        if ion_t is None:
            return pts
        return self._apply_ion_scatter_tof_center_to_xy(pts, ion_t)

    @staticmethod
    def _use_safe_ion_overlay_redraw() -> bool:
        """Return whether the ion overlay refresh should use the stable full redraw.

        This now gates only the non-drag (typing / post-refresh) path; the
        per-frame drag path uses the animated-artist blit sessions below on
        every platform (16f).
        """
        return bool(sys.platform.startswith("win"))

    @staticmethod
    def _use_safe_circle_overlay_redraw() -> bool:
        """Return whether the electron overlay refresh should use the stable full redraw.

        This now gates only the non-drag (typing / post-refresh) path; the
        per-frame drag path uses the animated-artist blit sessions below on
        every platform (16f).
        """
        return bool(sys.platform.startswith("win"))

    def _prepare_ion_overlay_for_safe_redraw(self) -> bool:
        """Pre-create the ion overlay so a normal axis/canvas draw can render it safely."""
        safe_mode = self._use_safe_ion_overlay_redraw()
        if safe_mode:
            with contextlib.suppress(Exception):
                self._draw_ion_overlay()
        return safe_mode

    # ------------------------------------------------------------------
    # Animated-artist blit sessions for drag previews (16f)
    # ------------------------------------------------------------------
    # Mirrors the working ion-TOF fit-preview discipline: while a drag is
    # active its overlay artists carry set_animated(True), so they are skipped
    # by every normal draw. Backgrounds captured during the session can
    # therefore never contain baked-in overlay pixels (the historical ghost
    # ring); each frame only restore_region(bg) + draw_artist(overlays) +
    # blit(ax.bbox). Any failure downgrades that session to the proven
    # whole-axes _draw_axes_immediate path after logging once.
    _OVERLAY_BLIT_ATTRS_BY_KEY = {
        "electron": (
            "inner_ring_patch",
            "outer_ring_patch",
            "circle_center_marker",
            "polar_roi_span_patch",
            "polar_roi_line_lo",
            "polar_roi_line_hi",
        ),
        "ion": (
            "ion_filter_patch",
            "ion_filter_center_marker",
        ),
    }
    _ION_ROTATION_PREVIEW_TITLE_SUFFIX_MAX = " [preview rot=-888.8 deg]"

    def _overlay_blit_axes_attrs(self, axis_key: str):
        """Return (axes, overlay attribute names) for one blit session key."""
        if axis_key == "rotation":
            return self.ax_scatter_i, ("ion_main_axis_line",)
        if axis_key == "electron":
            return self.ax_scatter_e, self._OVERLAY_BLIT_ATTRS_BY_KEY["electron"]
        if axis_key == "ion":
            return self.ax_scatter_i, self._OVERLAY_BLIT_ATTRS_BY_KEY["ion"]
        return None, ()

    def _overlay_blit_session_active(self, axis_key: str) -> bool:
        """Return whether a drag blit session is active for this overlay family."""
        return bool(getattr(self, "_overlay_blit_sessions", {}).get(axis_key))

    def _overlay_blit_downgrade(self, axis_key: str) -> None:
        """Permanently fall back to the safe redraw path for this drag session."""
        downgraded = getattr(self, "_overlay_blit_downgraded", None)
        if downgraded is None or axis_key in downgraded:
            return
        downgraded.add(axis_key)
        if not getattr(self, "_overlay_blit_downgrade_logged", False):
            self._overlay_blit_downgrade_logged = True
            print(
                f"overlay drag blit unavailable ({axis_key}); "
                "using safe whole-axes redraw for this session",
                flush=True,
            )

    def _begin_scatter_overlay_blit_session(self, axis_key: str) -> None:
        """Start one overlay drag session: animate its artists, drop stale bgs."""
        sessions = getattr(self, "_overlay_blit_sessions", None)
        if not isinstance(sessions, dict):
            sessions = {}
            self._overlay_blit_sessions = sessions
        if not isinstance(getattr(self, "_overlay_blit_downgraded", None), set):
            self._overlay_blit_downgraded = set()
        sessions[axis_key] = True
        self._overlay_blit_downgraded.discard(axis_key)
        _ax, attrs = self._overlay_blit_axes_attrs(axis_key)
        for name in attrs:
            artist = getattr(self, name, None)
            if artist is not None:
                with contextlib.suppress(Exception):
                    artist.set_animated(True)
        # Cached backgrounds predate the animated state and may contain
        # baked-in overlay pixels; recapture cleanly on the first frame.
        if axis_key == "electron":
            self.bg_scatter_e = None
        elif axis_key == "ion":
            self.bg_scatter_i = None

    def _begin_ion_rotation_blit_session(self) -> None:
        """Start the ion direction-line rotation drag session (title blit incl.)."""
        if not isinstance(getattr(self, "_overlay_blit_downgraded", None), set):
            self._overlay_blit_downgraded = set()
        self._overlay_blit_downgraded.discard("rotation")
        if self.ion_main_axis_line is not None:
            with contextlib.suppress(Exception):
                self.ion_main_axis_line.set_animated(True)
        self.bg_ion_rotation = None
        self._ion_rotation_blit_region = None

    def _end_scatter_overlay_blit_sessions(self) -> None:
        """Close any active drag sessions: de-animate artists, release backgrounds."""
        sessions = getattr(self, "_overlay_blit_sessions", None)
        active = bool(sessions)
        if isinstance(sessions, dict):
            for axis_key in list(sessions):
                _ax, attrs = self._overlay_blit_axes_attrs(axis_key)
                for name in attrs:
                    artist = getattr(self, name, None)
                    if artist is not None:
                        with contextlib.suppress(Exception):
                            artist.set_animated(False)
            sessions.clear()
        if self.ion_main_axis_line is not None:
            with contextlib.suppress(Exception):
                if self.ion_main_axis_line.get_animated():
                    self.ion_main_axis_line.set_animated(False)
                    active = True
        if self.bg_ion_rotation is not None or self._ion_rotation_blit_region is not None:
            active = True
        self.bg_ion_rotation = None
        self._ion_rotation_blit_region = None
        self.bg_rbasex_range = None
        if isinstance(getattr(self, "_overlay_blit_downgraded", None), set):
            self._overlay_blit_downgraded.clear()
        if active:
            # Backgrounds are overlay-free by construction, but the de-animated
            # artists must be baked into the next stable render, and any refresh
            # that follows re-captures anyway.
            self._invalidate_blit_background()

    def _capture_scatter_overlay_blit_background(self, axis_key: str):
        """Render one scatter axes without its (animated) overlays and snapshot it.

        The single-axes render is the same primitive the whole-axes safe path
        uses per frame, but it is paid once per drag instead of per frame.
        Artists layered above the overlays (panel buttons, annotations) are
        hidden for the snapshot and re-drawn by the present, so the captured
        region contains exactly the below-overlay content. Returns the captured
        background region or None.
        """
        ax = self.ax_scatter_e if axis_key == "electron" else self.ax_scatter_i
        if ax is None:
            return None
        hidden = []
        try:
            renderer = self.canvas.get_renderer()
            if renderer is None:
                return None
            max_z = 0.0
            for name in self._OVERLAY_BLIT_ATTRS_BY_KEY.get(axis_key, ()):
                artist = getattr(self, name, None)
                if artist is not None:
                    artist.set_animated(True)
                    with contextlib.suppress(Exception):
                        max_z = max(max_z, float(artist.get_zorder()))
            for txt in self._axes_above_texts(ax, max_z):
                hidden.append((txt, txt.get_visible()))
                txt.set_visible(False)
            ax.draw(renderer)  # animated overlay artists are skipped: clean pixels
            return self.canvas.copy_from_bbox(ax.bbox)
        except Exception:
            return None
        finally:
            for txt, visible in hidden:
                with contextlib.suppress(Exception):
                    txt.set_visible(visible)

    def _present_scatter_overlay_blit(self, axis_key: str) -> bool:
        """Blit-present one scatter overlay family from its clean cached background."""
        if axis_key in getattr(self, "_overlay_blit_downgraded", set()):
            return False
        sessions = getattr(self, "_overlay_blit_sessions", {})
        if not sessions.get(axis_key):
            return False
        ax, attrs = self._overlay_blit_axes_attrs(axis_key)
        if ax is None:
            return False
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            self._end_plot_scroll_burst()
        bg = self.bg_scatter_e if axis_key == "electron" else self.bg_scatter_i
        bg_key = "scatter_e" if axis_key == "electron" else "scatter_i"
        try:
            if bg is None:
                bg = self._capture_scatter_overlay_blit_background(axis_key)
                if bg is None:
                    self._overlay_blit_downgrade(axis_key)
                    return False
                if axis_key == "electron":
                    self.bg_scatter_e = bg
                else:
                    self.bg_scatter_i = bg
                self._record_blit_bg_size(bg_key)
            if not self._blit_bg_size_matches(bg_key):
                # Stale geometry (canvas resized since capture): never restore.
                if axis_key == "electron":
                    self.bg_scatter_e = None
                else:
                    self.bg_scatter_i = None
                self._blit_bg_geom[bg_key] = None
                self._overlay_blit_downgrade(axis_key)
                return False
            self.canvas.restore_region(bg)
            max_z = 0.0
            ordered = sorted(
                (getattr(self, name) for name in attrs if getattr(self, name) is not None),
                key=lambda artist: artist.get_zorder(),
            )
            for artist in ordered:
                if artist.axes is ax:
                    ax.draw_artist(artist)
                    with contextlib.suppress(Exception):
                        max_z = max(max_z, float(artist.get_zorder()))
            # Keep above-layer artists (buttons, annotations) on top, matching
            # the normal draw order.
            for txt in self._axes_above_texts(ax, max_z):
                ax.draw_artist(txt)
            self.canvas.blit(ax.bbox)
            self._mark_plot_scroll_preview_cache_dirty(refresh_soon=False)
            return True
        except Exception:
            if axis_key == "electron":
                self.bg_scatter_e = None
            else:
                self.bg_scatter_i = None
            self._overlay_blit_downgrade(axis_key)
            return False

    def _capture_ion_rotation_blit_background(self) -> bool:
        """Snapshot the ion axes region covering base title and any preview suffix."""
        ax = self.ax_scatter_i
        if ax is None:
            return False
        try:
            renderer = self.canvas.get_renderer()
            if renderer is None:
                return False
            base_title = ax.get_title()
            extents = []
            try:
                ax.set_title(base_title)
                extents.append(ax.title.get_window_extent(renderer))
                ax.set_title(base_title + self._ION_ROTATION_PREVIEW_TITLE_SUFFIX_MAX)
                extents.append(ax.title.get_window_extent(renderer))
            finally:
                ax.set_title(base_title)
            x0 = float(ax.bbox.x0)
            y0 = float(ax.bbox.y0)
            x1 = float(ax.bbox.x1)
            y1 = float(ax.bbox.y1)
            for ext in extents:
                x0 = min(x0, float(ext.x0))
                y0 = min(y0, float(ext.y0))
                x1 = max(x1, float(ext.x1))
                y1 = max(y1, float(ext.y1))
            x0 -= 2.0
            y0 -= 2.0
            x1 += 2.0
            y1 += 2.0
            fig_bbox = getattr(self.figure, "bbox", None)
            if fig_bbox is not None:
                x0 = max(x0, float(fig_bbox.x0))
                y0 = max(y0, float(fig_bbox.y0))
                x1 = min(x1, float(fig_bbox.x1))
                y1 = min(y1, float(fig_bbox.y1))
            if x1 <= x0 or y1 <= y0:
                return False
            region = matplotlib.transforms.Bbox.from_extents(x0, y0, x1, y1)
            hidden = []
            for txt in self._axes_above_texts(ax, 6.0):
                hidden.append((txt, txt.get_visible()))
                txt.set_visible(False)
            # The filter rectangle/marker sit above the direction line in the
            # normal draw. Hide them for the snapshot (their antialiased edges
            # must not be baked in twice) and re-draw them in the present.
            for name in ("ion_filter_patch", "ion_filter_center_marker"):
                artist = getattr(self, name, None)
                if artist is not None and artist.axes is ax:
                    hidden.append((artist, artist.get_visible()))
                    artist.set_visible(False)
            try:
                ax.draw(renderer)  # animated direction line is skipped: clean base
                self.bg_ion_rotation = self.canvas.copy_from_bbox(region)
                self._record_blit_bg_size("ion_rotation")
            finally:
                for txt, visible in hidden:
                    with contextlib.suppress(Exception):
                        txt.set_visible(visible)
            self._ion_rotation_blit_region = region
            return self.bg_ion_rotation is not None
        except Exception:
            self.bg_ion_rotation = None
            self._ion_rotation_blit_region = None
            return False

    def _present_ion_rotation_blit(self) -> bool:
        """Blit-present the rotated direction line plus preview title suffix."""
        if "rotation" in getattr(self, "_overlay_blit_downgraded", set()):
            return False
        if not self.dragging_ion_rotation:
            return False
        ax = self.ax_scatter_i
        if ax is None:
            return False
        try:
            if self.bg_ion_rotation is None or self._ion_rotation_blit_region is None:
                if not self._capture_ion_rotation_blit_background():
                    self._overlay_blit_downgrade("rotation")
                    return False
            if not self._blit_bg_size_matches("ion_rotation"):
                # Stale geometry: never restore, fall back to a normal redraw.
                self.bg_ion_rotation = None
                self._ion_rotation_blit_region = None
                self._blit_bg_geom["ion_rotation"] = None
                self._overlay_blit_downgrade("rotation")
                return False
            self.canvas.restore_region(self.bg_ion_rotation)
            if self.ion_main_axis_line is not None and self.ion_main_axis_line.axes is ax:
                ax.draw_artist(self.ion_main_axis_line)
            # The ion filter rectangle/marker sit above the direction line in the
            # normal draw; re-draw them so the overlap order stays exact.
            for name in ("ion_filter_patch", "ion_filter_center_marker"):
                artist = getattr(self, name, None)
                if artist is not None and artist.axes is ax:
                    ax.draw_artist(artist)
            # Keep above-layer artists (buttons, annotations) on top.
            for txt in self._axes_above_texts(ax, 6.0):
                ax.draw_artist(txt)
            ax.draw_artist(ax.title)
            self.canvas.blit(self._ion_rotation_blit_region)
            self._mark_plot_scroll_cache_dirty_for_drag()
            return True
        except Exception:
            self.bg_ion_rotation = None
            self._ion_rotation_blit_region = None
            self._overlay_blit_downgrade("rotation")
            return False

    def _present_rbasex_range_blit(self, ax) -> bool:
        """Blit-present the rBasex radial-profile range span + stats text."""
        if "rbasex_range" in getattr(self, "_overlay_blit_downgraded", set()):
            return False
        if not getattr(self, "dragging_rbasex_profile_range", False):
            return False
        if ax is None:
            return False
        overlay_gids = {"rbasex_profile_range_span", "rbasex_profile_range_text"}
        overlays = [
            artist
            for artist in list(ax.patches) + list(ax.texts)
            if getattr(artist, "get_gid", lambda: None)() in overlay_gids
        ]
        if not overlays:
            return False
        try:
            for artist in overlays:
                artist.set_animated(True)
            if self.bg_rbasex_range is None:
                renderer = self.canvas.get_renderer()
                if renderer is None:
                    self._overlay_blit_downgrade("rbasex_range")
                    return False
                max_z = max(float(artist.get_zorder()) for artist in overlays)
                hidden = []
                for txt in self._axes_above_texts(ax, max_z):
                    hidden.append((txt, txt.get_visible()))
                    txt.set_visible(False)
                try:
                    ax.draw(renderer)  # animated span/text are skipped: clean base
                    self.bg_rbasex_range = self.canvas.copy_from_bbox(ax.bbox)
                    self._record_blit_bg_size("rbasex_range")
                finally:
                    for txt, visible in hidden:
                        with contextlib.suppress(Exception):
                            txt.set_visible(visible)
                if self.bg_rbasex_range is None:
                    self._overlay_blit_downgrade("rbasex_range")
                    return False
            if not self._blit_bg_size_matches("rbasex_range"):
                # Stale geometry: never restore, fall back to a normal redraw.
                self.bg_rbasex_range = None
                self._blit_bg_geom["rbasex_range"] = None
                self._overlay_blit_downgrade("rbasex_range")
                return False
            self.canvas.restore_region(self.bg_rbasex_range)
            # Z-order sorted like the normal draw: the span (z 3.8) composites
            # over the stats text (z 3) exactly as Axes.draw would.
            max_z = 0.0
            for artist in sorted(overlays, key=lambda a: a.get_zorder()):
                if artist.axes is ax:
                    ax.draw_artist(artist)
                    with contextlib.suppress(Exception):
                        max_z = max(max_z, float(artist.get_zorder()))
            for txt in self._axes_above_texts(ax, max_z):
                ax.draw_artist(txt)
            self.canvas.blit(ax.bbox)
            self._mark_plot_scroll_cache_dirty_for_drag()
            return True
        except Exception:
            self.bg_rbasex_range = None
            self._overlay_blit_downgrade("rbasex_range")
            return False

    def _mark_plot_scroll_cache_dirty_for_drag(self) -> None:
        """Mark the scroll preview stale during drags without scheduling recapture."""
        self._plot_scroll_preview_pixmap = QPixmap()

    @staticmethod
    def _axes_above_texts(ax, min_zorder: float) -> list:
        """Return visible, non-animated ax.texts layered at/above ``min_zorder``.

        These are the per-panel ``[raw]/[copy]`` buttons (zorder 50) and any
        in-axes annotations. During a blit present they must be re-drawn after
        the overlay artists so the layering matches the normal draw; during the
        background capture they must be hidden so the snapshot never contains
        them (otherwise the present would double-composite their translucent
        boxes). ``>=`` matches the stable z-order sort: an equal-zorder text is
        added after the overlay artists and therefore renders on top.
        """
        result = []
        for txt in getattr(ax, "texts", []):
            try:
                if txt.get_visible() and not txt.get_animated() and txt.get_zorder() >= min_zorder:
                    result.append(txt)
            except Exception:
                continue
        return result

    # ------------------------------------------------------------------
    # Overlay artist lifecycle and blitting
    # ------------------------------------------------------------------
    def _invalidate_blit_background(self) -> None:
        """Mark cached background as dirty (must be recaptured before blit)."""
        self.bg_scatter_e = None
        self.bg_scatter_i = None
        self.bg_theta_centered = None
        self.bg_theta_rbasex = None
        self.bg_ion_rotation = None
        self.bg_rbasex_range = None
        self._ion_rotation_blit_region = None
        self._blit_bg_geom.clear()

    def _record_blit_bg_size(self, key: str) -> None:
        """Record the canvas size at which a blit background was just captured."""
        try:
            self._blit_bg_geom[key] = tuple(self.canvas.get_width_height())
        except Exception:
            self._blit_bg_geom[key] = None

    def _blit_bg_size_matches(self, key: str) -> bool:
        """True if a captured blit background still matches the current canvas size.

        A background captured at a different canvas size must never be passed
        to ``restore_region``: offscreen Agg silently clips, but the on-screen
        Qt backing store write goes out of bounds and hard-crashes the app.
        """
        geom = self._blit_bg_geom.get(key)
        if geom is None:
            return False
        try:
            return tuple(geom) == tuple(self.canvas.get_width_height())
        except Exception:
            return False

    def _invalidate_theta_blit_backgrounds(self) -> None:
        """Drop the theta-guide blit backgrounds (centered image changed)."""
        self.bg_theta_centered = None
        self.bg_theta_rbasex = None
        self._blit_bg_geom["theta_centered"] = None
        self._blit_bg_geom["theta_rbasex"] = None

    def _dedupe_overlay_artists(self) -> None:
        """Remove stale duplicate overlay artists from scatter axes."""
        changed = False

        if self.inner_ring_patch is not None and self.inner_ring_patch.axes is not self.ax_scatter_e:
            self.inner_ring_patch = None
            changed = True
        if self.outer_ring_patch is not None and self.outer_ring_patch.axes is not self.ax_scatter_e:
            self.outer_ring_patch = None
            changed = True
        if self.circle_center_marker is not None and self.circle_center_marker.axes is not self.ax_scatter_e:
            self.circle_center_marker = None
            changed = True
        if self.polar_roi_span_patch is not None and self.polar_roi_span_patch.axes is not self.ax_scatter_e:
            self.polar_roi_span_patch = None
            changed = True
        if self.polar_roi_line_lo is not None and self.polar_roi_line_lo.axes is not self.ax_scatter_e:
            self.polar_roi_line_lo = None
            changed = True
        if self.polar_roi_line_hi is not None and self.polar_roi_line_hi.axes is not self.ax_scatter_e:
            self.polar_roi_line_hi = None
            changed = True
        if self.ion_filter_patch is not None and self.ion_filter_patch.axes is not self.ax_scatter_i:
            self.ion_filter_patch = None
            changed = True
        if self.ion_filter_center_marker is not None and self.ion_filter_center_marker.axes is not self.ax_scatter_i:
            self.ion_filter_center_marker = None
            changed = True
        if self.ion_main_axis_line is not None and self.ion_main_axis_line.axes is not self.ax_scatter_i:
            self.ion_main_axis_line = None
            changed = True
        if self.ion_main_axis_marker is not None and self.ion_main_axis_marker.axes is not self.ax_scatter_i:
            self.ion_main_axis_marker = None
            changed = True

        keep_ids = {
            id(a)
            for a in (
                self.inner_ring_patch,
                self.outer_ring_patch,
                self.circle_center_marker,
                self.polar_roi_span_patch,
                self.polar_roi_line_lo,
                self.polar_roi_line_hi,
                self.ion_filter_patch,
                self.ion_filter_center_marker,
                self.ion_main_axis_line,
                self.ion_main_axis_marker,
            )
            if a is not None
        }
        electron_overlay_gids = {
            "electron_inner_ring",
            "electron_outer_ring",
            "electron_center_marker",
            "polar_roi_span",
            "polar_roi_line_lo",
            "polar_roi_line_hi",
        }
        ion_overlay_gids = {
            "ion_filter_rect",
            "ion_filter_center",
            "ion_main_axis_line",
        }

        for p in list(self.ax_scatter_e.patches):
            gid = p.get_gid() if hasattr(p, "get_gid") else None
            if id(p) not in keep_ids and gid in electron_overlay_gids:
                with contextlib.suppress(Exception):
                    p.remove()
                changed = True
        for l in list(self.ax_scatter_e.lines):
            gid = l.get_gid() if hasattr(l, "get_gid") else None
            if id(l) not in keep_ids and gid in electron_overlay_gids:
                with contextlib.suppress(Exception):
                    l.remove()
                changed = True
        for p in list(self.ax_scatter_i.patches):
            gid = p.get_gid() if hasattr(p, "get_gid") else None
            if id(p) not in keep_ids and gid in ion_overlay_gids:
                with contextlib.suppress(Exception):
                    p.remove()
                changed = True
        for l in list(self.ax_scatter_i.lines):
            gid = l.get_gid() if hasattr(l, "get_gid") else None
            if id(l) not in keep_ids and gid in ion_overlay_gids:
                with contextlib.suppress(Exception):
                    l.remove()
                changed = True

        if changed:
            self._invalidate_blit_background()

    def _rebuild_blit_background(self) -> None:
        """Capture clean backgrounds for fast overlay redraw (blitting)."""
        self._dedupe_overlay_artists()

        artists = []
        for artist in (
            self.inner_ring_patch,
            self.outer_ring_patch,
            self.circle_center_marker,
            self.polar_roi_span_patch,
            self.polar_roi_line_lo,
            self.polar_roi_line_hi,
            self.ion_filter_patch,
            self.ion_filter_center_marker,
        ):
            if artist is not None:
                try:
                    artists.append((artist, artist.get_visible()))
                    artist.set_visible(False)
                except Exception:
                    pass

        # Draw once without overlays, so backgrounds never contain stale circles/markers.
        self._draw_canvas_without_overlay_draw_event_sync()
        try:
            self.bg_scatter_e = self.canvas.copy_from_bbox(self.ax_scatter_e.bbox)
            self.bg_scatter_i = self.canvas.copy_from_bbox(self.ax_scatter_i.bbox)
            self._record_blit_bg_size("scatter_e")
            self._record_blit_bg_size("scatter_i")
        except Exception:
            self._invalidate_blit_background()

        for artist, visible in artists:
            with contextlib.suppress(Exception):
                artist.set_visible(visible)

        self._blit_overlays()

    def _capture_scatter_blit_backgrounds(self, *, electron: bool = True, ion: bool = True) -> bool:
        """Capture only the scatter-axis backgrounds that were actually redrawn."""
        ok = True
        if electron:
            try:
                self.bg_scatter_e = self.canvas.copy_from_bbox(self.ax_scatter_e.bbox)
                self._record_blit_bg_size("scatter_e")
            except Exception:
                self.bg_scatter_e = None
                self._blit_bg_geom["scatter_e"] = None
                ok = False
        if ion:
            try:
                self.bg_scatter_i = self.canvas.copy_from_bbox(self.ax_scatter_i.bbox)
                self._record_blit_bg_size("scatter_i")
            except Exception:
                self.bg_scatter_i = None
                self._blit_bg_geom["scatter_i"] = None
                ok = False
        return ok

    def _capture_blit_background_from_current_canvas(self) -> None:
        """Capture scatter axis backgrounds from current full canvas draw."""
        if not self._capture_scatter_blit_backgrounds(electron=True, ion=True):
            self._invalidate_blit_background()
            return
        self._capture_theta_line_blit_background()
        if not self._radial_profile_is_angular_integrated():
            self._blit_theta_guides("centered")
            self._blit_theta_guides("rbasex")

    def _capture_theta_line_blit_background(self) -> None:
        """Capture line-free backgrounds for centered/rBasex theta-guide blitting.

        The two image panels are re-rendered without their (animated) guide
        lines and the axes regions are snapshotted from that clean render.
        Copying the shared renderer buffer instead would bake in whatever the
        previous ``_blit_theta_guides`` present had drawn on top (a ghost guide
        line at a stale angle in every subsequent blit), and the legacy
        hide-then-``canvas.draw()`` fallback recursed through the draw-event
        hook. A single-axes render is the same clean primitive the scatter
        overlay sessions use.
        """
        ax_centered = getattr(self, "ax_centered_bin", None)
        ax_rbasex = getattr(self, "ax_reserved_top", None)
        if ax_centered is None or ax_rbasex is None:
            return
        guide_artists = (
            self.theta_profile_line_main,
            self.theta_profile_line_lo,
            self.theta_profile_line_hi,
            self.rbasex_profile_line_main,
            self.rbasex_profile_line_lo,
            self.rbasex_profile_line_hi,
        )
        to_hide = []
        for artist in guide_artists:
            if artist is None:
                continue
            with contextlib.suppress(Exception):
                if not bool(artist.get_animated()):
                    to_hide.append((artist, artist.get_visible()))
                    artist.set_visible(False)
        try:
            renderer = self.canvas.get_renderer()
            if renderer is None:
                return
            hidden_texts = []
            for panel_ax in (ax_centered, ax_rbasex):
                hidden_texts.extend((txt, txt.get_visible()) for txt in self._axes_above_texts(panel_ax, 2.5))
            for txt, visible in hidden_texts:
                with contextlib.suppress(Exception):
                    txt.set_visible(False)
            try:
                ax_centered.draw(renderer)
                ax_rbasex.draw(renderer)
                self.bg_theta_centered = self.canvas.copy_from_bbox(ax_centered.bbox)
                self.bg_theta_rbasex = self.canvas.copy_from_bbox(ax_rbasex.bbox)
                self._record_blit_bg_size("theta_centered")
                self._record_blit_bg_size("theta_rbasex")
            finally:
                for txt, visible in hidden_texts:
                    with contextlib.suppress(Exception):
                        txt.set_visible(visible)
        except Exception:
            self.bg_theta_centered = None
            self.bg_theta_rbasex = None
            self._blit_bg_geom["theta_centered"] = None
            self._blit_bg_geom["theta_rbasex"] = None
        finally:
            for artist, visible in to_hide:
                with contextlib.suppress(Exception):
                    artist.set_visible(visible)

    def _blit_theta_guides(self, source: str) -> bool:
        """Blit theta guide lines on one image axis using cached background."""
        if source == "centered":
            ax = self.ax_centered_bin
            bg = self.bg_theta_centered
            main = self.theta_profile_line_main
            lo = self.theta_profile_line_lo
            hi = self.theta_profile_line_hi
        elif source == "rbasex":
            ax = self.ax_reserved_top
            bg = self.bg_theta_rbasex
            main = self.rbasex_profile_line_main
            lo = self.rbasex_profile_line_lo
            hi = self.rbasex_profile_line_hi
        else:
            return False

        if bg is None:
            return False
        if not self._blit_bg_size_matches("theta_centered" if source == "centered" else "theta_rbasex"):
            # Canvas was resized (or the panel image replaced) since capture:
            # never restore a stale region, recapture on the next frame instead.
            if source == "centered":
                self.bg_theta_centered = None
                self._blit_bg_geom["theta_centered"] = None
            else:
                self.bg_theta_rbasex = None
                self._blit_bg_geom["theta_rbasex"] = None
            return False
        for artist in (main, lo, hi):
            if artist is None or artist.axes is not ax:
                return False

        try:
            self.canvas.restore_region(bg)
            ax.draw_artist(main)
            ax.draw_artist(lo)
            ax.draw_artist(hi)
            # Keep above-layer artists (buttons, annotations) on top, matching
            # the normal draw order.
            for txt in self._axes_above_texts(ax, 2.5):
                ax.draw_artist(txt)
            self.canvas.blit(ax.bbox)
            return True
        except Exception:
            if source == "centered":
                self.bg_theta_centered = None
                self._blit_bg_geom["theta_centered"] = None
            else:
                self.bg_theta_rbasex = None
                self._blit_bg_geom["theta_rbasex"] = None
            return False

    @staticmethod
    def _parse_field_from_filename(file_path: str) -> float | None:
        """Extract field value F (V/cm) from filename text if present."""
        name = os.path.basename(file_path)
        patterns = (
            r"([-+]?\d+(?:\.\d+)?)\s*v\s*[_/\-]?\s*cm(?:\b|_)",
            r"electric\s*field\s*[_=\-]?\s*([-+]?\d+(?:\.\d+)?)",
        )
        for pattern in patterns:
            match = re.search(pattern, name, flags=re.IGNORECASE)
            if match:
                try:
                    return float(match.group(1))
                except Exception:
                    continue
        return None

    @staticmethod
    def _try_parse_float_text(text: str) -> float | None:
        """Parse a float from text; tolerant to units/thousands separators/comma decimals."""
        cleaned = str(text).strip().replace("\u2212", "-")
        if not cleaned:
            return None
        try:
            return float(cleaned)
        except Exception:
            pass
        # European decimal comma without dot.
        if "," in cleaned and "." not in cleaned:
            maybe = cleaned.replace(",", ".")
            try:
                return float(maybe)
            except Exception:
                pass
        match = re.search(r"[-+]?(?:\d{1,3}(?:[,\s]\d{3})+|\d+)(?:[.,]\d+)?(?:[eE][-+]?\d+)?", cleaned)
        if not match:
            return None
        token = match.group(0).strip().replace(" ", "")
        if ("," in token) and ("." in token):
            # Assume the last punctuation is decimal separator.
            if token.rfind(",") > token.rfind("."):
                token = token.replace(".", "").replace(",", ".")
            else:
                token = token.replace(",", "")
        elif "," in token:
            # One comma can be decimal separator, otherwise treat as thousands separators.
            if token.count(",") == 1 and re.search(r",\d+$", token):
                token = token.replace(",", ".")
            else:
                token = token.replace(",", "")
        try:
            return float(token)
        except Exception:
            return None

    @staticmethod
    def _parse_tof_ref_range_text(text: str) -> tuple[float, float] | None:
        """Parse TOF range text into sorted positive bounds with tolerant number parsing."""
        cleaned = str(text).strip()
        if cleaned == "":
            return None
        parts = re.split(r"(?:\s+to\s+|;|->|~|,|\s+)", cleaned, flags=re.IGNORECASE)
        nums: list[float] = []
        for part in parts:
            val = MainWindow._try_parse_float_text(part)
            if val is None:
                continue
            nums.append(float(val))
            if len(nums) >= 2:
                break
        if len(nums) < 2:
            # Fallback: extract first two numeric tokens from whole string.
            tokens = re.findall(r"[-+]?(?:\d{1,3}(?:[,\s]\d{3})+|\d+)(?:[.,]\d+)?(?:[eE][-+]?\d+)?", cleaned)
            for token in tokens:
                val = MainWindow._try_parse_float_text(token)
                if val is None:
                    continue
                nums.append(float(val))
                if len(nums) >= 2:
                    break
        if len(nums) < 2:
            return None
        a = float(nums[0])
        b = float(nums[1])
        if (not np.isfinite(a)) or (not np.isfinite(b)):
            return None
        lo, hi = sorted((float(a), float(b)))
        if lo <= 0.0 or hi <= 0.0:
            return None
        return lo, hi

    @staticmethod
    def _mq_snap_value_to_int(value: float) -> int:
        """Round one m/q display value to nearest integer (half-up)."""
        if not np.isfinite(value):
            return 0
        return int(np.floor(float(value) + 0.5))

    def _mq_snap_range_to_int_bins(self, low_axis: float, high_axis: float) -> tuple[int, int]:
        """Snap one m/q interval to integer bin indices."""
        lo, hi = sorted((float(low_axis), float(high_axis)))
        lo_i = max(0, self._mq_snap_value_to_int(lo))
        hi_i = max(0, self._mq_snap_value_to_int(hi))
        if hi_i < lo_i:
            hi_i = lo_i
        return lo_i, hi_i

    @staticmethod
    def _mq_bin_index_range_to_axis_bounds(lo_i: int, hi_i: int) -> tuple[float, float]:
        """Convert integer m/q bin-index range to continuous-axis bounds covering whole bins."""
        lo = float(max(0, int(lo_i))) - 0.5
        hi = float(max(0, int(hi_i))) + 0.5
        return max(0.0, lo), max(0.0, hi)

    @staticmethod
    def _mq_integer_hist_edges(values_mq: np.ndarray, roi_x: tuple[float, float] | None = None) -> np.ndarray:
        """Build integer-width m/q histogram edges so each bin spans exactly 1 m/q."""
        vals = np.asarray(values_mq, dtype=np.float64).reshape(-1)
        vals = vals[np.isfinite(vals)]
        if roi_x is None:
            if vals.size == 0:
                return np.array([-0.5, 0.5], dtype=np.float64)
            lo = float(np.min(vals))
            hi = float(np.max(vals))
        else:
            lo = float(min(roi_x[0], roi_x[1]))
            hi = float(max(roi_x[0], roi_x[1]))
            if not np.isfinite([lo, hi]).all():
                if vals.size == 0:
                    return np.array([-0.5, 0.5], dtype=np.float64)
                lo = float(np.min(vals))
                hi = float(np.max(vals))
        if not np.isfinite([lo, hi]).all():
            return np.array([-0.5, 0.5], dtype=np.float64)
        lo = max(0.0, lo)
        hi = max(lo, hi)
        lo_i = int(np.floor(lo))
        hi_i = int(np.ceil(hi))
        if hi_i < lo_i:
            hi_i = lo_i
        start = float(lo_i) - 0.5
        stop = float(hi_i) + 0.5
        edges = np.arange(start, stop + 1e-9, 1.0, dtype=np.float64)
        if edges.size < 2:
            edges = np.array([start, start + 1.0], dtype=np.float64)
        return edges

    def _ion_tof_reference_center_and_range(self) -> tuple[float | None, tuple[float, float] | None]:
        """Return (effective_ref_tof_center, optional_ref_tof_range)."""
        tof_center = self._try_parse_float_text(self.ion_tof_ref_edit.text()) if hasattr(self, "ion_tof_ref_edit") else None
        tof_range = None
        if hasattr(self, "ion_tof_ref_range_edit"):
            text_range = self.ion_tof_ref_range_edit.text().strip()
            if text_range == "":
                self.ion_tof_ref_range_value = None
            else:
                parsed = self._parse_tof_ref_range_text(text_range)
                if parsed is not None:
                    self.ion_tof_ref_range_value = (float(parsed[0]), float(parsed[1]))
                # Keep last valid parsed range when text is non-empty but partially malformed.
            if self.ion_tof_ref_range_value is not None:
                tof_range = self.ion_tof_ref_range_value
        if tof_center is not None and (not np.isfinite(tof_center) or float(tof_center) <= 0.0):
            tof_center = None
        if tof_range is not None:
            lo, hi = float(tof_range[0]), float(tof_range[1])
            # Range is the calibration anchor; center must be inside that range.
            if tof_center is None or (tof_center < lo) or (tof_center > hi):
                tof_center = 0.5 * (lo + hi)
        return (float(tof_center) if tof_center is not None else None), tof_range

    @staticmethod
    def _set_line_edit_text_silent(edit: QLineEdit, value: str) -> None:
        """Set QLineEdit text without triggering signal loops."""
        if edit.text() == value:
            return
        was = edit.blockSignals(True)
        edit.setText(value)
        edit.blockSignals(was)

    def _update_field_from_file_paths(self, preferred_role: str | None = None) -> None:
        """Parse F from selected filenames and update field controls."""
        roles: list[str] = []
        if preferred_role in self.file_paths:
            roles.append(str(preferred_role))
        for role in ("trigger", "electron", "ion"):
            if role not in roles:
                roles.append(role)
        parsed: float | None = None
        for role in roles:
            path = self.file_paths.get(role, "")
            if not path:
                continue
            parsed = self._parse_field_from_filename(path)
            if parsed is not None:
                break
        if parsed is None:
            return
        self.parsed_field_vcm = float(parsed)
        self._set_line_edit_text_silent(self.field_f_vcm_edit, f"{parsed:.6g}")
        self._update_voltage_parameters()

    @staticmethod
    def _ion_time_to_mq_values(time_values: np.ndarray, mq_ref: float, tof_ref: float) -> np.ndarray:
        """Map TOF values to m/q using m/q = (t/t_ref)^2 * (m/q)_ref."""
        t_arr = np.asarray(time_values, dtype=np.float64)
        return float(mq_ref) * np.square(t_arr / float(tof_ref))

    @staticmethod
    def _ion_mq_to_time_values(mq_values: np.ndarray, mq_ref: float, tof_ref: float) -> np.ndarray:
        """Map m/q values to TOF using t = t_ref * sqrt((m/q)/(m/q)_ref)."""
        q_arr = np.asarray(mq_values, dtype=np.float64)
        out = np.full_like(q_arr, np.nan, dtype=np.float64)
        valid = np.isfinite(q_arr) & (q_arr >= 0.0)
        if np.any(valid):
            out[valid] = float(tof_ref) * np.sqrt(q_arr[valid] / float(mq_ref))
        return out

    @staticmethod
    def _ion_mq_calibration_params(ref: tuple[float, ...] | None) -> tuple[float, float] | None:
        """Return (a,b) for m/q = a*t^2 + b from reference data.

        Calibration is constrained to square-law scaling (`b=0`) so each displayed
        integer m/q bin corresponds to a deterministic TOF interval.

        Physics/Method: for a spectrometer with negligible time-zero offset the
        flight time follows `t = t_ref * sqrt((m/q)/(m/q)_ref)`, i.e. the exact
        square law through the single reference point `a = (m/q)_ref / t_ref^2`.

        Assumptions / Limitations:
        - `b=0` forces the time-zero offset `t0` to zero. A real offset `t0`
          (extraction-pulse delay, cable delays) makes the true law
          `m/q = a*(t - t0)^2`; the fitted square law is then systematically
          stretched/compressed away from `t_ref` (relative m/q error grows
          roughly like `2*t0/t` near the reference and worsens at small t).
        - Range-fit mode (`arr[2], arr[3]` present) treats the selected TOF
          range as exactly one integer m/q bin `[m_ref-1/2, m_ref+1/2]` and
          refits `a` by least squares through the two range edges. If the
          selected range is not one full bin, the axis is stretched
          accordingly; the fit has a single free parameter and no feedback of
          the residual to the user.
        """
        if ref is None:
            return None
        arr = np.asarray(ref, dtype=np.float64).reshape(-1)
        if arr.size < 2:
            return None
        mq_ref = float(arr[0])
        tof_ref = float(arr[1])
        if (not np.isfinite(mq_ref)) or (not np.isfinite(tof_ref)) or mq_ref <= 0.0 or tof_ref <= 0.0:
            return None

        # Base square-law scale from reference center.
        a = float(mq_ref) / (float(tof_ref) * float(tof_ref))
        if (not np.isfinite(a)) or a <= 0.0:
            return None

        # Range-calibrated refinement: treat selected TOF range as one reference m/q bin,
        # and fit square-law scale through both range edges in least-squares sense.
        if arr.size >= 4 and np.isfinite(arr[2]) and np.isfinite(arr[3]):
            t_lo, t_hi = sorted((float(arr[2]), float(arr[3])))
            if t_lo > 0.0 and t_hi > t_lo:
                m_lo = float(mq_ref) - 0.5
                m_hi = float(mq_ref) + 0.5
                if m_lo < 0.0:
                    m_lo = 0.0
                    m_hi = max(1.0, m_hi)
                t_sq = np.array([t_lo * t_lo, t_hi * t_hi], dtype=np.float64)
                m_targets = np.array([m_lo, m_hi], dtype=np.float64)
                denom = float(np.dot(t_sq, t_sq))
                if np.isfinite(denom) and denom > 1e-18:
                    a_fit = float(np.dot(m_targets, t_sq) / denom)
                    if np.isfinite(a_fit) and a_fit > 0.0:
                        a = a_fit

        return float(a), 0.0

    @staticmethod
    def _ion_time_to_mq_from_ab(time_values: np.ndarray, a: float, b: float) -> np.ndarray:
        """Map TOF to m/q using calibrated relation m/q = a*t^2 + b."""
        t_arr = np.asarray(time_values, dtype=np.float64)
        return (float(a) * np.square(t_arr)) + float(b)

    @staticmethod
    def _ion_mq_to_time_from_ab(mq_values: np.ndarray, a: float, b: float) -> np.ndarray:
        """Inverse map m/q to TOF using calibrated relation m/q = a*t^2 + b."""
        q_arr = np.asarray(mq_values, dtype=np.float64)
        out = np.full_like(q_arr, np.nan, dtype=np.float64)
        if (not np.isfinite(a)) or a <= 0.0:
            return out
        inner = q_arr - float(b)
        valid = np.isfinite(inner) & (inner >= 0.0)
        if np.any(valid):
            out[valid] = np.sqrt(inner[valid] / float(a))
        return out

    def _ion_axis_mode_and_ref(
        self,
        *,
        show_dialog: bool,
        strict: bool,
    ) -> tuple[str, tuple[float, ...] | None]:
        """Resolve active ion-hist axis mode and validated reference pair."""
        use_mq = bool(getattr(self, "ion_mq_axis_checkbox", None) and self.ion_mq_axis_checkbox.isChecked())
        if not use_mq:
            return "time", None
        mq_ref = self._try_parse_float_text(self.ion_mq_ref_edit.text()) if hasattr(self, "ion_mq_ref_edit") else None
        tof_ref, tof_range = self._ion_tof_reference_center_and_range()
        valid = (
            mq_ref is not None
            and tof_ref is not None
            and np.isfinite(mq_ref)
            and np.isfinite(tof_ref)
            and float(mq_ref) > 0.0
            and float(tof_ref) > 0.0
        )
        if valid:
            if tof_range is not None:
                ref_pair = (float(mq_ref), float(tof_ref), float(tof_range[0]), float(tof_range[1]))
            else:
                ref_pair = (float(mq_ref), float(tof_ref))
            self.ion_mq_last_valid_ref = ref_pair
            return "mq", ref_pair
        if show_dialog:
            QMessageBox.warning(
                self,
                "Invalid m/q reference",
                "Enable m/q axis requires positive 'Ref m/q' and a valid Ref TOF center or Ref TOF range.",
            )
        if strict:
            return "invalid", None
        if self.ion_mq_last_valid_ref is not None:
            return "mq", self.ion_mq_last_valid_ref
        return "time", None

    @staticmethod
    def _ion_axis_tag(mode: str, ref: tuple[float, ...] | None) -> tuple:
        """Build immutable cache tag for histogram axis transform state."""
        if mode == "mq" and ref is not None:
            arr = np.asarray(ref, dtype=np.float64).reshape(-1)
            if arr.size >= 4 and np.isfinite(arr[:4]).all():
                return ("mq", float(arr[0]), float(arr[1]), float(arr[2]), float(arr[3]))
            if arr.size >= 2 and np.isfinite(arr[:2]).all():
                return ("mq", float(arr[0]), float(arr[1]))
        return ("time",)

    @staticmethod
    def _ion_axis_symbol(mode: str) -> str:
        """Return short axis symbol for labels/messages."""
        return "m/q" if mode == "mq" else "t"

    @staticmethod
    def _ion_hist_title(mode: str) -> str:
        """Return concise title for ion histogram panel."""
        return "Ion Histogram (m/q)" if mode == "mq" else "Ion Histogram (t)"

    @staticmethod
    def _snap_ion_hist_marker_axis_values(
        values: np.ndarray | list[float] | tuple[float, ...] | float,
        mode: str,
    ) -> np.ndarray:
        """Snap ion-hist marker display values to valid discrete axis positions."""
        arr = np.asarray(values, dtype=np.float64)
        if mode != "mq":
            return arr
        snapped = np.array(arr, copy=True, dtype=np.float64)
        finite = np.isfinite(snapped)
        if np.any(finite):
            snapped[finite] = np.floor(np.clip(snapped[finite], 0.0, None) + 0.5)
        return snapped

    @staticmethod
    def _snap_ion_hist_click_to_bin_centers(
        values: np.ndarray | list[float] | tuple[float, ...] | float,
        edges: np.ndarray | list[float] | tuple[float, ...] | None,
    ) -> np.ndarray:
        """Snap click positions to the center of the containing histogram bin."""
        arr = np.asarray(values, dtype=np.float64)
        e = np.asarray(edges if edges is not None else [], dtype=np.float64).reshape(-1)
        if arr.size == 0 or e.size < 2 or not np.isfinite(e).all():
            return np.array(arr, copy=True, dtype=np.float64)
        snapped = np.array(arr, copy=True, dtype=np.float64)
        finite = np.isfinite(snapped)
        if not np.any(finite):
            return snapped
        lo = float(min(e[0], e[-1]))
        hi = float(max(e[0], e[-1]))
        work = np.clip(snapped[finite], lo, hi)
        idx = np.searchsorted(e, work, side="right") - 1
        idx = np.clip(idx, 0, e.size - 2)
        snapped[finite] = 0.5 * (e[idx] + e[idx + 1])
        return snapped

    def _ion_axis_xlabel(self, mode: str, ref: tuple[float, ...] | None) -> str:
        """Return x-axis label text for ion histogram."""
        if mode == "mq" and ref is not None:
            return "m/q"
        return "t (ns)"

    def _ion_time_to_axis_values(
        self,
        values: np.ndarray | list[float] | tuple[float, ...] | float,
        mode: str,
        ref: tuple[float, ...] | None,
    ) -> np.ndarray:
        """Convert internal TOF values to active display-axis values."""
        arr = np.asarray(values, dtype=np.float64)
        if mode == "mq" and ref is not None:
            cal = self._ion_mq_calibration_params(ref)
            if cal is not None:
                return self._ion_time_to_mq_from_ab(arr, cal[0], cal[1])
            return self._ion_time_to_mq_values(arr, ref[0], ref[1])
        return arr

    def _ion_axis_to_time_values(
        self,
        values: np.ndarray | list[float] | tuple[float, ...] | float,
        mode: str,
        ref: tuple[float, ...] | None,
    ) -> np.ndarray:
        """Convert display-axis values back to internal TOF values."""
        arr = np.asarray(values, dtype=np.float64)
        if mode == "mq" and ref is not None:
            cal = self._ion_mq_calibration_params(ref)
            if cal is not None:
                return self._ion_mq_to_time_from_ab(arr, cal[0], cal[1])
            return self._ion_mq_to_time_values(arr, ref[0], ref[1])
        return arr

    def _ion_time_range_to_axis_range(
        self,
        roi_t: tuple[float, float] | None,
        mode: str,
        ref: tuple[float, ...] | None,
    ) -> tuple[float, float] | None:
        """Convert one internal TOF range to displayed-axis range."""
        if roi_t is None:
            return None
        vals = self._ion_time_to_axis_values(np.array([roi_t[0], roi_t[1]], dtype=np.float64), mode, ref)
        if vals.size != 2 or (not np.isfinite(vals).all()):
            return None
        low, high = sorted((float(vals[0]), float(vals[1])))
        if mode == "mq":
            # In m/q mode, ROI inputs/labels represent integer m/q bins.
            lo_i = int(np.ceil(low - 1e-9))
            hi_i = int(np.floor(high + 1e-9))
            if hi_i < lo_i:
                center_i = self._mq_snap_value_to_int(0.5 * (low + high))
                lo_i, hi_i = center_i, center_i
            low, high = float(max(0, lo_i)), float(max(0, hi_i))
        return low, high

    def _ion_time_range_to_axis_span(
        self,
        roi_t: tuple[float, float] | None,
        mode: str,
        ref: tuple[float, ...] | None,
    ) -> tuple[float, float] | None:
        """Convert one internal TOF range to the displayed span that covers the whole selected ROI.

        In `m/q` mode the fine/coarse ROI text boxes intentionally show integer bin labels
        like `19`, but the plotted histogram span for that selection is the full displayed
        bin, e.g. `18.5 .. 19.5`. This helper returns that full span.
        """
        if roi_t is None:
            return None
        vals = self._ion_time_to_axis_values(np.array([roi_t[0], roi_t[1]], dtype=np.float64), mode, ref)
        if vals.size != 2 or (not np.isfinite(vals).all()):
            return None
        low, high = sorted((float(vals[0]), float(vals[1])))
        if mode == "mq":
            lo_i = int(np.ceil(low - 1e-9))
            hi_i = int(np.floor(high + 1e-9))
            if hi_i < lo_i:
                center_i = self._mq_snap_value_to_int(0.5 * (low + high))
                lo_i, hi_i = center_i, center_i
            return self._mq_bin_index_range_to_axis_bounds(lo_i, hi_i)
        return float(low), float(high)

    def _on_ion_axis_controls_changed(self, _checked: bool | None = None) -> None:
        """Apply ion-hist x-axis transform settings and refresh dependent views."""
        auto_used_fine_ref = False
        status_override: str | None = None
        mq_toggle_on = bool(hasattr(self, "ion_mq_axis_checkbox") and self.ion_mq_axis_checkbox.isChecked())
        # UX helper: when user enables m/q axis after drawing Fine ROI, auto-capture that
        # ROI as reference TOF range if no TOF reference is set yet.
        if mq_toggle_on:
            tof_ref_now, _tof_range_now = self._ion_tof_reference_center_and_range()
            if tof_ref_now is None and self._has_pairs() and self.ion_range is not None:
                lo, hi = sorted((float(self.ion_range[0]), float(self.ion_range[1])))
                if np.isfinite([lo, hi]).all() and lo > 0.0 and hi > 0.0 and abs(hi - lo) > 1e-12:
                    center = 0.5 * (lo + hi)
                    ion_t = self._paired_ion_t()
                    if ion_t.size > 0:
                        roi_vals = ion_t[(ion_t >= lo) & (ion_t <= hi)]
                        roi_vals = roi_vals[np.isfinite(roi_vals) & (roi_vals > 0.0)]
                        if roi_vals.size > 0:
                            center = float(np.median(roi_vals))
                    if hasattr(self, "ion_tof_ref_range_edit"):
                        self._set_line_edit_text_silent(self.ion_tof_ref_range_edit, f"[{lo:.6g}, {hi:.6g}]")
                    self.ion_tof_ref_range_value = (float(lo), float(hi))
                    if hasattr(self, "ion_tof_ref_edit"):
                        self._set_line_edit_numeric(self.ion_tof_ref_edit, center, ".6g")
                    auto_used_fine_ref = True

        mode, ref = self._ion_axis_mode_and_ref(show_dialog=False, strict=True)
        if mode == "invalid":
            if hasattr(self, "ion_mq_axis_checkbox"):
                was = self.ion_mq_axis_checkbox.blockSignals(True)
                self.ion_mq_axis_checkbox.setChecked(False)
                self.ion_mq_axis_checkbox.blockSignals(was)
            mq_ref_now = self._try_parse_float_text(self.ion_mq_ref_edit.text()) if hasattr(self, "ion_mq_ref_edit") else None
            tof_ref_now, _tof_range_now = self._ion_tof_reference_center_and_range()
            missing: list[str] = []
            if mq_ref_now is None or (not np.isfinite(mq_ref_now)) or float(mq_ref_now) <= 0.0:
                missing.append("Ref m/q")
            if tof_ref_now is None or (not np.isfinite(tof_ref_now)) or float(tof_ref_now) <= 0.0:
                missing.append("Ref TOF center/range")
            missing_txt = ", ".join(missing) if missing else "reference values"
            hint = "Set positive Ref m/q, then enable m/q axis."
            if self.ion_range is not None:
                hint = "Set positive Ref m/q. Fine ROI exists; click 'Take Fine ROI as Ref TOF' if needed."
            status_override = f"m/q axis not enabled. Missing/invalid: {missing_txt}. {hint}"
            mode, ref = "time", None
        self._invalidate_ion_hist_cache()
        self._sync_hist_roi_inputs(force=True)
        self._sync_fine_roi_inputs(force=True)
        self._update_ion_selection_label()
        if self._has_pairs():
            self._refresh_ion_histogram_only(draw_canvas=False)
            self._refresh_ion_tof_pos_panel_only(draw_canvas=False)
        else:
            self.ax_hist_ion.clear()
            self.ax_hist_ion.set_title(self._ion_hist_title(mode))
            self.ax_hist_ion.set_xlabel(self._ion_axis_xlabel(mode, ref))
            self.ax_hist_ion.set_ylabel(self._ion_hist_ylabel_text())
            self.ax_hist_ion.grid(alpha=0.2)
            self._apply_ion_hist_xtick_locator()
            self._refresh_ion_tof_pos_panel_only(draw_canvas=False)
        self._add_subplot_save_markers()
        axes_to_draw = [self.ax_hist_ion, self.ax_ion_tof_xy]
        if self.ion_tof_xy_colorbar is not None:
            axes_to_draw.append(getattr(self.ion_tof_xy_colorbar, "ax", None))
        self._draw_axes_immediate(axes_to_draw, include_tight=True)
        self._reset_ion_hist_navigation_history()
        if mode == "mq" and ref is not None:
            _tof_center, tof_range = self._ion_tof_reference_center_and_range()
            if tof_range is not None:
                auto_msg = " Ref TOF range auto-set from Fine ROI." if auto_used_fine_ref else ""
                self._set_status(
                    (
                        "Ion histogram x-axis: m/q (ref=%.6g, t_ref center=%.6g ns, "
                        "range=[%.6g, %.6g] ns, bin width=1, square-law).%s"
                    )
                    % (ref[0], ref[1], tof_range[0], tof_range[1], auto_msg)
                )
            else:
                auto_msg = " Ref TOF range auto-set from Fine ROI." if auto_used_fine_ref else ""
                self._set_status(
                    (
                        f"Ion histogram x-axis: m/q (ref={ref[0]:.6g}, t_ref={ref[1]:.6g} ns, "
                        f"bin width=1, square-law).{auto_msg}"
                    )
                )
        else:
            self._set_status(
                status_override
                or "Ion histogram x-axis: t (ns). Set Ref m/q and Ref TOF center/range before enabling m/q."
            )

    def _on_ion_axis_reference_edited(self) -> None:
        """Auto-apply m/q axis mapping after reference edits, only when references are complete."""
        if not (hasattr(self, "ion_mq_axis_checkbox") and self.ion_mq_axis_checkbox.isChecked()):
            return
        self._on_ion_axis_controls_changed()

    def _on_take_fine_roi_as_tof_ref_clicked(self) -> None:
        """Use current fine ROI TOF interval as m/q reference range and center."""
        if not self._has_pairs():
            QMessageBox.warning(self, "No data", "Run Process and Plot first.")
            return
        if self.ion_range is None:
            QMessageBox.warning(self, "No fine ROI", "Set Fine ROI first, then click this button.")
            return
        lo, hi = sorted((float(self.ion_range[0]), float(self.ion_range[1])))
        if (not np.isfinite([lo, hi]).all()) or lo <= 0.0 or hi <= 0.0 or abs(hi - lo) <= 1e-12:
            QMessageBox.warning(
                self,
                "Invalid fine ROI",
                "Fine ROI must define a valid positive TOF interval before using it as m/q reference.",
            )
            return
        center = 0.5 * (lo + hi)
        # Use current ROI data to estimate a robust center when possible.
        ion_t = self._paired_ion_t()
        if ion_t.size > 0:
            roi_vals = ion_t[(ion_t >= lo) & (ion_t <= hi)]
            roi_vals = roi_vals[np.isfinite(roi_vals) & (roi_vals > 0.0)]
            if roi_vals.size > 0:
                center = float(np.median(roi_vals))
        if hasattr(self, "ion_tof_ref_range_edit"):
            self._set_line_edit_text_silent(self.ion_tof_ref_range_edit, f"[{lo:.6g}, {hi:.6g}]")
        self.ion_tof_ref_range_value = (float(lo), float(hi))
        if hasattr(self, "ion_tof_ref_edit"):
            self._set_line_edit_numeric(self.ion_tof_ref_edit, center, ".6g")

        mq_axis_on = bool(hasattr(self, "ion_mq_axis_checkbox") and self.ion_mq_axis_checkbox.isChecked())
        mode_now, _ref_now = self._ion_axis_mode_and_ref(show_dialog=False, strict=True)
        if mq_axis_on and mode_now == "mq":
            # Apply immediately only when both references are valid; avoid pop-up warnings here.
            self._on_ion_axis_controls_changed()
            self._set_status(
                "Ref TOF range captured from Fine ROI: [%.6g, %.6g] ns (center=%.6g ns). "
                "m/q calibration refreshed for full histogram."
                % (lo, hi, center)
            )
            return
        self._set_status(
            "Ref TOF range captured from Fine ROI: [%.6g, %.6g] ns (center=%.6g ns). "
            "Set positive Ref m/q to calibrate full histogram to m/q."
            % (lo, hi, center)
        )

    def _reset_ion_hist_navigation_history(self) -> None:
        """Reset toolbar view stack so Home/back don't jump to stale axis-unit ranges."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return
        if self.ion_hist_x_roi is not None:
            mode, ref = self._ion_axis_mode_and_ref(show_dialog=False, strict=False)
            roi_x = self._ion_time_range_to_axis_range(self.ion_hist_x_roi, mode, ref)
            if roi_x is None:
                roi_x = (float(self.ion_hist_x_roi[0]), float(self.ion_hist_x_roi[1]))
            lo = float(min(roi_x[0], roi_x[1]))
            hi = float(max(roi_x[0], roi_x[1]))
            if np.isfinite([lo, hi]).all() and abs(hi - lo) > 1e-12:
                self.ax_hist_ion.set_xlim(lo, hi, auto=False)
        self._reset_toolbar_navigation_history()

    def _reset_toolbar_navigation_history(self) -> None:
        """Clear toolbar Home/Back/Forward history and seed it with the current figure view."""
        tb = getattr(self, "toolbar", None)
        if tb is None:
            return
        with contextlib.suppress(Exception):
            tb.update()
        nav_stack = getattr(tb, "_nav_stack", None)
        if nav_stack is not None and hasattr(nav_stack, "clear"):
            with contextlib.suppress(Exception):
                nav_stack.clear()
        with contextlib.suppress(Exception):
            tb.push_current()
        with contextlib.suppress(Exception):
            tb.set_history_buttons()

    def _capture_ion_hist_view_state(self) -> dict | None:
        """Capture current ion-hist view in display-axis units for redraw restoration."""
        x0, x1 = self.ax_hist_ion.get_xlim()
        y0, y1 = self.ax_hist_ion.get_ylim()
        if not np.isfinite([x0, x1, y0, y1]).all():
            return None
        mode, ref = self._ion_axis_mode_and_ref(show_dialog=False, strict=False)
        return {
            "axis_tag": self._ion_axis_tag(mode, ref),
            "xlim": (float(x0), float(x1)),
            "ylim": (float(y0), float(y1)),
            "yscale": str(self.ax_hist_ion.get_yscale()),
        }

    def _ion_hist_display_x_bounds(self, mode: str, ref: tuple[float, ...] | None) -> tuple[float, float] | None:
        """Return valid display-axis x bounds for current histogram contents."""
        bounds: tuple[float, float] | None = None
        edges = np.asarray(self._ion_hist_cache_edges, dtype=np.float64).reshape(-1)
        if edges.size >= 2 and np.isfinite(edges).all():
            bounds = (float(min(edges[0], edges[-1])), float(max(edges[0], edges[-1])))
        if self.ion_hist_x_roi is not None:
            roi_x = self._ion_time_range_to_axis_range(self.ion_hist_x_roi, mode, ref)
            if roi_x is None:
                roi_x = (float(self.ion_hist_x_roi[0]), float(self.ion_hist_x_roi[1]))
            roi_lo = float(min(roi_x[0], roi_x[1]))
            roi_hi = float(max(roi_x[0], roi_x[1]))
            if np.isfinite([roi_lo, roi_hi]).all() and abs(roi_hi - roi_lo) > 1e-12:
                if bounds is None:
                    bounds = (roi_lo, roi_hi)
                else:
                    bounds = (max(bounds[0], roi_lo), min(bounds[1], roi_hi))
        if bounds is None:
            return None
        lo, hi = bounds
        if (not np.isfinite(lo)) or (not np.isfinite(hi)) or abs(hi - lo) <= 1e-12:
            return None
        return lo, hi

    def _restore_ion_hist_view_state(
        self,
        view_state: dict | None,
        mode: str,
        ref: tuple[float, ...] | None,
    ) -> bool:
        """Restore ion-hist display limits after redraw when axis units are unchanged."""
        if not isinstance(view_state, dict):
            return False
        if tuple(view_state.get("axis_tag", ())) != self._ion_axis_tag(mode, ref):
            return False
        xlim = view_state.get("xlim")
        ylim = view_state.get("ylim")
        if not (
            isinstance(xlim, (list, tuple))
            and len(xlim) == 2
            and isinstance(ylim, (list, tuple))
            and len(ylim) == 2
        ):
            return False
        try:
            x0, x1 = float(xlim[0]), float(xlim[1])
            y0, y1 = float(ylim[0]), float(ylim[1])
        except Exception:
            return False
        if not np.isfinite([x0, x1]).all():
            return False
        bounds = self._ion_hist_display_x_bounds(mode, ref)
        if bounds is not None:
            lo, hi = bounds
            left = max(float(min(x0, x1)), lo)
            right = min(float(max(x0, x1)), hi)
            if (right - left) <= 1e-12:
                left, right = lo, hi
        else:
            left, right = float(min(x0, x1)), float(max(x0, x1))
        self.ax_hist_ion.set_xlim(left, right, auto=False)
        yscale_saved = str(view_state.get("yscale", "linear"))
        if yscale_saved == str(self.ax_hist_ion.get_yscale()) and np.isfinite([y0, y1]).all():
            y_low = float(min(y0, y1))
            y_high = float(max(y0, y1))
            if yscale_saved == "log":
                y_low = max(y_low, 1e-12)
            if (y_high - y_low) > 1e-12:
                self.ax_hist_ion.set_ylim(y_low, y_high, auto=False)
        return True

    def _on_voltage_input_changed(self, _value=None) -> None:
        """Recompute derived voltages when any physical-parameter input changes."""
        self._update_voltage_parameters()

    def _update_voltage_parameters(self) -> None:
        """Compute voltage parameters from F/L/offset (with optional auto offset lock)."""
        f_vcm = self._try_parse_float_text(self.field_f_vcm_edit.text())
        lens_l = self._try_parse_float_text(self.field_l_edit.text())
        offset = self._try_parse_float_text(self.voltage_offset_edit.text())
        if f_vcm is None or lens_l is None or abs(lens_l) < 1e-12:
            for edit in (
                self.v_ion_grid_edit,
                self.v_repeller_edit,
                self.v_e_grid_edit,
                self.v_extractor_edit,
                self.v_detector_edit,
            ):
                self._set_line_edit_text_silent(edit, "n/a")
            return
        if offset is None:
            offset = 0.0

        field_factor = 20.0 / 3.0
        # Iteratively correct offset so V_I.Grid converges to 0 in auto mode.
        if self.auto_offset_checkbox.isChecked():
            offset_iter = float(offset)
            for _ in range(10):
                v_igrid_iter = offset_iter - field_factor * f_vcm
                if abs(v_igrid_iter) <= 1e-12:
                    break
                offset_iter -= v_igrid_iter
            offset = offset_iter
            self._set_line_edit_text_silent(self.voltage_offset_edit, f"{offset:.6g}")

        v_ion_grid = offset - field_factor * f_vcm
        # The repeller sits one additional field-drop upstream from the ion-grid side.
        # Using `offset` directly here collapses repeller and ion-grid to the same
        # value when `L == 1`, which is not the intended electrode stack.
        # Keep the existing magnitude but display the repeller in the positive convention used in the UI.
        v_repeller = abs(v_ion_grid - field_factor * f_vcm / lens_l)
        v_e_grid = offset - field_factor * f_vcm / (2.0 * lens_l)
        v_extractor = offset
        v_detector = offset

        self._set_line_edit_text_silent(self.v_ion_grid_edit, f"{v_ion_grid:.6g}")
        self._set_line_edit_text_silent(self.v_repeller_edit, f"{v_repeller:.6g}")
        self._set_line_edit_text_silent(self.v_e_grid_edit, f"{v_e_grid:.6g}")
        self._set_line_edit_text_silent(self.v_extractor_edit, f"{v_extractor:.6g}")
        self._set_line_edit_text_silent(self.v_detector_edit, f"{v_detector:.6g}")

    def _voltage_snapshot(self) -> dict:
        """Return current physical parameter values as plain numbers/text."""
        return {
            "F_v_cm": self._try_parse_float_text(self.field_f_vcm_edit.text()),
            "L": self._try_parse_float_text(self.field_l_edit.text()),
            "auto_offset_to_zero_ion_grid": bool(self.auto_offset_checkbox.isChecked()),
            "V_offset": self._try_parse_float_text(self.voltage_offset_edit.text()),
            "V_I_Grid": self._try_parse_float_text(self.v_ion_grid_edit.text()),
            "V_Repeller": self._try_parse_float_text(self.v_repeller_edit.text()),
            "V_E_Grid": self._try_parse_float_text(self.v_e_grid_edit.text()),
            "V_Extractor": self._try_parse_float_text(self.v_extractor_edit.text()),
            "V_Detector": self._try_parse_float_text(self.v_detector_edit.text()),
        }

    # ------------------------------------------------------------------
    # File/cache state and base processing
    # ------------------------------------------------------------------
    def _set_status(self, text: str) -> None:
        """Update one-line status text shown below the control panel."""
        msg = str(text)
        self.status_label.setText(f"Status: {msg}")
        stamp = datetime.now().astimezone().isoformat(timespec="seconds")
        if not hasattr(self, "operation_log") or not isinstance(self.operation_log, list):
            self.operation_log = []
        if (not self.operation_log) or (self.operation_log[-1].get("text") != msg):
            self.operation_log.append({"time_local": stamp, "text": msg})
            if len(self.operation_log) > 5000:
                self.operation_log = self.operation_log[-5000:]

    def _force_full_canvas_redraw_for_layout_change(
        self,
        *,
        refresh_circle_overlay: bool = True,
        refresh_ion_overlay: bool = True,
    ) -> None:
        """Force a clean full redraw and refresh blit caches after layout-sensitive changes."""
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            self._end_plot_scroll_burst()
        safe_ion_overlay = bool(refresh_ion_overlay and self._prepare_ion_overlay_for_safe_redraw())
        self._draw_canvas_without_overlay_draw_event_sync()
        self._axis_last_blit_extents = {}
        self._capture_blit_background_from_current_canvas()
        if self._has_pairs():
            if refresh_circle_overlay:
                self._update_circle_overlay_only()
            if refresh_ion_overlay and not safe_ion_overlay:
                self._update_ion_overlay_only()
        self._present_canvas_now(request_idle_draw=False)

    def _present_canvas_now(self, *, request_idle_draw: bool) -> None:
        """Schedule a safe canvas present without forcing re-entrant Qt painting.

        Direct `repaint()` / `flush_events()` / `processEvents()` calls from ROI
        callbacks can re-enter Qt painting while the matplotlib canvas is already
        inside an interaction draw, which can crash the app during fine-ROI drags.
        Keep this helper non-reentrant and let Qt present the updated widget on
        the next normal GUI cycle.
        """
        with contextlib.suppress(Exception):
            if request_idle_draw:
                self.canvas.draw_idle()
        with contextlib.suppress(Exception):
            self.canvas.update()

    def _draw_axes_immediate(
        self,
        axes: list | tuple,
        *,
        include_tight: bool = False,
        force_full: bool = False,
    ) -> None:
        """Redraw only selected axes when possible; fall back to full-canvas draw."""
        if bool(getattr(self, "_plot_scroll_preview_active", False)):
            self._end_plot_scroll_burst()
        if not hasattr(self, "_axis_last_blit_extents") or not isinstance(self._axis_last_blit_extents, dict):
            self._axis_last_blit_extents = {}
        unique_axes = []
        seen = set()
        for ax in axes:
            if ax is None:
                continue
            ax_id = id(ax)
            if ax_id in seen:
                continue
            seen.add(ax_id)
            unique_axes.append(ax)
        if not unique_axes:
            return

        if force_full:
            self.canvas.draw()
            self._axis_last_blit_extents = {}
            self._mark_plot_scroll_preview_cache_dirty(refresh_soon=True)
            self._present_canvas_now(request_idle_draw=False)
            return

        renderer = None
        with contextlib.suppress(Exception):
            renderer = self.canvas.get_renderer()
        if renderer is None:
            self.canvas.draw()
            self._axis_last_blit_extents = {}
            self._mark_plot_scroll_preview_cache_dirty(refresh_soon=True)
            self._present_canvas_now(request_idle_draw=False)
            return

        fig_bbox = getattr(self.figure, "bbox", None)
        valid_ids = {id(ax) for ax in getattr(self.figure, "axes", [])}
        stale_ids = [k for k in self._axis_last_blit_extents.keys() if k not in valid_ids]
        if stale_ids:
            # When axes are removed/recreated (typical for colorbars), a partial blit can
            # leave stale pixels from old labels/ticks. Force one clean full redraw.
            self.canvas.draw()
            self._axis_last_blit_extents = {}
            self._mark_plot_scroll_preview_cache_dirty(refresh_soon=True)
            self._present_canvas_now(request_idle_draw=False)
            return

        for ax in unique_axes:
            try:
                ax_id = id(ax)
                ax.draw(renderer)
                x0 = float(ax.bbox.x0)
                y0 = float(ax.bbox.y0)
                x1 = float(ax.bbox.x1)
                y1 = float(ax.bbox.y1)
                if include_tight:
                    tight = ax.get_tightbbox(renderer)
                    if tight is not None:
                        x0 = min(x0, float(tight.x0))
                        y0 = min(y0, float(tight.y0))
                        x1 = max(x1, float(tight.x1))
                        y1 = max(y1, float(tight.y1))
                x0 -= 2.0
                y0 -= 2.0
                x1 += 2.0
                y1 += 2.0

                prev = self._axis_last_blit_extents.get(ax_id)
                if prev is not None:
                    px0, py0, px1, py1 = prev
                    x0 = min(x0, float(px0))
                    y0 = min(y0, float(py0))
                    x1 = max(x1, float(px1))
                    y1 = max(y1, float(py1))

                if fig_bbox is not None:
                    x0 = max(x0, float(fig_bbox.x0))
                    y0 = max(y0, float(fig_bbox.y0))
                    x1 = min(x1, float(fig_bbox.x1))
                    y1 = min(y1, float(fig_bbox.y1))
                if x1 <= x0 or y1 <= y0:
                    blit_box = ax.bbox
                    self._axis_last_blit_extents[ax_id] = (
                        float(blit_box.x0),
                        float(blit_box.y0),
                        float(blit_box.x1),
                        float(blit_box.y1),
                    )
                else:
                    blit_box = matplotlib.transforms.Bbox.from_extents(x0, y0, x1, y1)
                    self._axis_last_blit_extents[ax_id] = (x0, y0, x1, y1)
                self.canvas.blit(blit_box)
            except Exception:
                self.canvas.draw()
                self._axis_last_blit_extents = {}
                self._mark_plot_scroll_preview_cache_dirty(refresh_soon=True)
                self._present_canvas_now(request_idle_draw=False)
                return
        self._mark_plot_scroll_preview_cache_dirty(refresh_soon=True)
        self._present_canvas_now(request_idle_draw=bool(include_tight))

    def _draw_axes_preview(self, axes: list | tuple) -> None:
        """Redraw lightweight preview artists via the local blit path (60 fps)."""
        self._draw_axes_immediate(axes, include_tight=False, force_full=False)

    def _progress_start(self, text: str, determinate: bool = True) -> None:
        """Show and initialize bottom progress bar for long operations."""
        if not self._progress_widgets_valid():
            return
        if determinate:
            self.progress_bar.setRange(0, 100)
            self.progress_bar.setValue(0)
            self.progress_bar.setFormat("%p%")
        else:
            self.progress_bar.setRange(0, 0)
            self.progress_bar.setFormat("busy")
        self.progress_bar.setVisible(True)
        self._set_status(text)
        self._pump_progress_events_if_safe()

    def _progress_update(self, value: int | None = None, text: str | None = None) -> None:
        """Update progress bar percentage and optional status text."""
        if not self._progress_widgets_valid():
            return
        if value is not None and self.progress_bar.maximum() > 0:
            target = int(np.clip(value, 0, self.progress_bar.maximum()))
            if target != self.progress_bar.value():
                self.progress_bar.setValue(target)
        if text is not None:
            if self.progress_bar.maximum() > 0:
                self._set_status(f"{text} ({self.progress_bar.value()}%)")
            else:
                self._set_status(text)
        self._pump_progress_events_if_safe()

    def _progress_finish(self) -> None:
        """Hide and reset progress bar after long operation ends."""
        if not self._progress_widgets_valid():
            return
        self.progress_bar.setVisible(False)
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_bar.setFormat("%p%")
        self._pump_progress_events_if_safe()

    def _progress_widgets_valid(self) -> bool:
        """Return whether progress widgets are still backed by live Qt objects."""
        progress_bar = getattr(self, "progress_bar", None)
        status_label = getattr(self, "status_label", None)
        try:
            return bool(
                progress_bar is not None
                and status_label is not None
                and shiboken_is_valid(self)
                and shiboken_is_valid(progress_bar)
                and shiboken_is_valid(status_label)
            )
        except Exception:
            return False

    def _pump_progress_events_if_safe(self) -> None:
        """Avoid nested Qt event pumping in crash-prone Windows save/export paths."""
        if sys.platform.startswith("win") and bool(getattr(self, "_suspend_progress_event_pump", False)):
            return
        with contextlib.suppress(Exception):
            QApplication.processEvents()

    def _paired_count(self) -> int:
        """Return number of currently paired lookup rows."""
        return int(self.paired_lookup_i_idx.shape[0])

    def _has_pairs(self) -> bool:
        """Return whether at least one paired lookup row exists."""
        return self._paired_count() > 0

    def _paired_ion_t(self) -> np.ndarray:
        """Return ion TOF values from raw ion table using paired lookup indices."""
        if self.cache is None or self.paired_lookup_i_idx.size == 0:
            return np.zeros(0, dtype=np.float64)
        cache_key = (
            self._ion_hist_data_version,
            id(self.cache.ion_points),
            id(self.paired_lookup_i_idx),
            int(self.paired_lookup_i_idx.size),
        )
        if cache_key != self._paired_ion_t_cache_key:
            ion_t = np.asarray(self.cache.ion_points[self.paired_lookup_i_idx, 2], dtype=np.float64).reshape(-1)
            self._paired_ion_t_cache_key = cache_key
            self._paired_ion_t_cache_values = ion_t
            # Paired ion_t changed, downstream ROI mask cache is no longer valid.
            self._selected_mask_cache_key = None
            self._selected_mask_cache_values = np.zeros(0, dtype=bool)
        return self._paired_ion_t_cache_values

    def _paired_points(self, mask: np.ndarray | None = None) -> tuple[np.ndarray, np.ndarray]:
        """Return paired electron/ion rows from raw tables, optionally masked."""
        if self.cache is None or self.paired_lookup_i_idx.size == 0:
            return np.empty((0, 3), dtype=np.float64), np.empty((0, 3), dtype=np.float64)
        e_idx = self.paired_lookup_e_idx
        i_idx = self.paired_lookup_i_idx
        if mask is not None:
            if mask.shape[0] != i_idx.shape[0]:
                return np.empty((0, 3), dtype=np.float64), np.empty((0, 3), dtype=np.float64)
            e_idx = e_idx[mask]
            i_idx = i_idx[mask]
        if i_idx.size == 0:
            return np.empty((0, 3), dtype=np.float64), np.empty((0, 3), dtype=np.float64)
        return self.cache.electron_points[e_idx], self.cache.ion_points[i_idx]

    def _paired_bg_keep_mask(self, *, show_dialog: bool) -> np.ndarray:
        """Return the active BG-subtraction keep mask over all paired rows."""
        n = self._paired_count()
        if n <= 0:
            return np.zeros(0, dtype=bool)
        if not self._ion_tof_bg_subtraction_enabled():
            return np.ones(n, dtype=bool)
        keep = np.asarray(self._current_ion_tof_bg_keep_mask(show_dialog=show_dialog), dtype=bool).reshape(-1)
        if keep.shape[0] != n:
            return np.ones(n, dtype=bool)
        return keep

    def _apply_optional_bg_keep_to_mask(
        self,
        mask: np.ndarray,
        *,
        show_dialog: bool,
    ) -> tuple[np.ndarray, int]:
        """Apply the active BG keep-mask to one paired-row boolean mask."""
        mask_arr = np.asarray(mask, dtype=bool).reshape(-1).copy()
        if mask_arr.size <= 0:
            return mask_arr, 0
        keep = self._paired_bg_keep_mask(show_dialog=show_dialog)
        if keep.shape[0] != mask_arr.shape[0]:
            return mask_arr, 0
        removed = int(np.count_nonzero(mask_arr & (~keep)))
        mask_arr &= keep
        return mask_arr, removed

    def _selected_mask_with_optional_bg(self, *, show_dialog: bool) -> tuple[np.ndarray, int]:
        """Return current coarse+fine ion selection after optional BG subtraction."""
        return self._apply_optional_bg_keep_to_mask(self._selected_mask(), show_dialog=show_dialog)

    def _visible_paired_count(self, *, show_dialog: bool) -> int:
        """Return paired-row count after optional BG subtraction."""
        return int(np.count_nonzero(self._paired_bg_keep_mask(show_dialog=show_dialog)))

    def _has_circle_or_reconstruction_result(self) -> bool:
        """Return whether projection/reconstruction results depend on the current paired data."""
        return bool(
            self.centered_hist_data is not None
            or self.rbasex_recon_result is not None
            or self.ring_inner_selected_electron.shape[0] > 0
            or self.ring_outer_noise_electron.shape[0] > 0
            or self.circle_centered_electron.shape[0] > 0
            or self.noise_ring_centered_electron.shape[0] > 0
        )

    def _refresh_after_bg_filter_change(self, *, preserve_hist_view: bool = True) -> bool:
        """Refresh all BG-dependent views after the active pair mask changes."""
        hist_view = None
        if preserve_hist_view:
            with contextlib.suppress(Exception):
                hist_view = (self.ax_hist_ion.get_xlim(), self.ax_hist_ion.get_ylim())
        self._invalidate_ion_hist_cache()
        self._scatter_display_cache_key = None
        self._scatter_display_cache_data = None
        self._selected_pairs_cache_key = None
        self._selected_pairs_cache_data = None
        had_derived = self._has_circle_or_reconstruction_result()
        if had_derived:
            self._clear_circle_result()
        if self._has_pairs() or self._has_session_subplot_previews():
            self._refresh_plots(preserve_hist_view=hist_view)
        return had_derived

    def _refresh_after_ion_hist_roi_change(self) -> None:
        """Refresh only the panels touched by a coarse ion-hist ROI change.

        This avoids the heavier full-plot refresh when the projection/reconstruction
        panels are already empty placeholders.
        """
        had_derived = self._has_circle_or_reconstruction_result()
        self._clear_circle_result()
        self._refresh_ion_histogram_only(draw_canvas=False, preserve_view=False)
        self._refresh_after_circle_clear(
            refresh_scatter=True,
            refresh_ion_scatter=True,
            refresh_ion_tof_map=True,
            preserve_scatter_view=False,
            refresh_projection_panels=had_derived,
            extra_axes_to_draw=None if had_derived else [self.ax_hist_ion],
        )

    def _current_trigger_mode(self) -> str:
        """Return current trigger pairing mode key."""
        mode = self.trigger_mode_combo.currentData() if hasattr(self, "trigger_mode_combo") else "coincidence"
        if isinstance(mode, str):
            return mode
        return "coincidence"

    def _trigger_mode_label(self, mode: str | None = None) -> str:
        """Return user-facing label for trigger pairing mode key."""
        key = self._current_trigger_mode() if mode is None else mode
        if key == "one_e_three_i":
            return "1e+3i coincidence"
        if key == "one_e_two_i":
            return "1e+2i coincidence"
        return "all valid rows" if key == "all_one" else "1e+1i coincidence"

