    def _invalidate_trigger_event_count_cache(self) -> None:
        """Clear cached trigger event count summary."""
        self._trigger_event_count_cache_ref = None
        self._trigger_event_count_cache_values = (0, 0, 0, 0)

    def _trigger_event_counts(self) -> tuple[int, int, int, int]:
        """Return (all-valid, strict-1e1i, strict-1e2i, strict-1e3i) event counts for current trigger table."""
        if self.cache is None:
            return (0, 0, 0, 0)
        trigger = self.cache.trigger_indices
        if self._trigger_event_count_cache_ref is trigger:
            return self._trigger_event_count_cache_values

        e = trigger[:, 0]
        i = trigger[:, 1]
        valid_now = (~np.isnan(e)) & (~np.isnan(i))
        all_valid = int(np.count_nonzero(valid_now))
        one_one = 0
        one_two = 0
        one_three = 0

        if trigger.shape[0] > 1:
            e_prev = e[:-1]
            i_prev = i[:-1]
            e_curr = e[1:]
            i_curr = i[1:]
            valid_adj = (
                (~np.isnan(e_prev))
                & (~np.isnan(i_prev))
                & (~np.isnan(e_curr))
                & (~np.isnan(i_curr))
            )
            if np.any(valid_adj):
                e_prev_i = np.rint(e_prev[valid_adj]).astype(np.int64, copy=False)
                i_prev_i = np.rint(i_prev[valid_adj]).astype(np.int64, copy=False)
                e_curr_i = np.rint(e_curr[valid_adj]).astype(np.int64, copy=False)
                i_curr_i = np.rint(i_curr[valid_adj]).astype(np.int64, copy=False)
                de = e_curr_i - e_prev_i
                di = i_curr_i - i_prev_i
                one_one = int(np.count_nonzero((de == 1) & (di == 1)))
                one_two = int(np.count_nonzero((de == 1) & (di == 2)))
                one_three = int(np.count_nonzero((de == 1) & (di == 3)))

        out = (all_valid, one_one, one_two, one_three)
        self._trigger_event_count_cache_ref = trigger
        self._trigger_event_count_cache_values = out
        return out

    def _update_trigger_mode_combo_labels(self) -> None:
        """Update trigger-mode dropdown texts to show event counts per mode."""
        combo = getattr(self, "trigger_mode_combo", None)
        if combo is None:
            return
        if self.cache is None:
            saved = getattr(self, "session_saved_trigger_event_counts", None)
            if isinstance(saved, tuple) and len(saved) >= 5:
                c_all, c_11, c_12, c_13 = (
                    int(saved[0]),
                    int(saved[2]),
                    int(saved[3]),
                    int(saved[4]),
                )
            elif isinstance(saved, tuple) and len(saved) == 4:
                c_all, c_11, c_12, c_13 = (int(saved[0]), int(saved[1]), int(saved[2]), int(saved[3]))
            else:
                c_all = c_11 = c_12 = c_13 = None
        else:
            c_all, c_11, c_12, c_13 = self._trigger_event_counts()

        def _fmt_count(value: int | None) -> str:
            return "n/a" if value is None else f"{int(value)}"

        label_map = {
            "coincidence": f"1e + 1i coincidence (+1/+1) [events: {_fmt_count(c_11)}]",
            "one_e_two_i": f"1e + 2i coincidence (+1/+2, keep both ions) [events: {_fmt_count(c_12)}]",
            "one_e_three_i": f"1e + 3i coincidence (+1/+3, keep three ions) [events: {_fmt_count(c_13)}]",
            "all_one": f"All valid trigger rows (drop NaN) [events: {_fmt_count(c_all)}]",
        }
        for idx in range(int(combo.count())):
            key = combo.itemData(idx)
            if key in label_map:
                new_text = label_map[key]
                if combo.itemText(idx) != new_text:
                    combo.setItemText(idx, new_text)

    def _set_file_path(self, role: str, file_path: str) -> None:
        """Register selected file path for one role: trigger/electron/ion."""
        file_path = os.path.normpath(file_path)
        if not os.path.isfile(file_path):
            QMessageBox.warning(self, "Invalid path", "Dropped path is not a file.")
            return
        self.file_paths[role] = file_path
        self.drop_frames[role].set_path(file_path)
        self._update_field_from_file_paths(preferred_role=role)
        keep_pending_restore = bool(self.session_restore_pending and isinstance(self.session_restore_bundle, dict))
        if not keep_pending_restore:
            self.session_restore_bundle = None
            self.session_restore_pending = False

        if self.cache is not None:
            self.cache = None
            self._clear_processed_data()
            self._set_status("File changed. Cache invalidated, please load again.")
        else:
            self._set_status(f"{ROLE_LABELS[role]} file selected.")

